SELECT 'moj-all-verified-judgments-review-002-chunk-177' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"64cc5c82-5f5f-54e3-89d8-c56e4bd95c2a","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقد -أجارة -مطالبة بأجرة عن -سماع الدعوى غيابي ا لتعذر إباغ املدعى عليه -البينة بشهادة الشهود واليمن -األصل عدم دفع األجرة -وجوب الوفاء بالعقود احلكم بإلزام املدعى عليه بدفع باقي أجرة العن -رفع احلكم حملكمة الاستئناف لتعذر تبليغ املدعى عليه باحلكم.","document_number":"34271615","case_number":"33710584","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/17","year":"1434","subject":"عقد -أجارة -مطالبة بأجرة عن -سماع الدعوى غيابي ا لتعذر إباغ املدعى عليه -البينة بشهادة الشهود واليمن -األصل عدم دفع األجرة -وجوب الوفاء بالعقود احلكم بإلزام املدعى عليه بدفع باقي أجرة العن -رفع احلكم حملكمة الاستئناف لتعذر تبليغ املدعى عليه باحلكم.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/7/17 :‬هـ‬\n                 ‫ُ‬                 ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪34271615 :‬‬\n                    ‫َر ْق ُم الدعوى‪33710584 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n           ‫‪ 34345213‬تاريخه‪1434/10/29:‬هـ‬\n\n\n\n‫عقــد ‪ -‬أجــارة ‪ -‬مطالبــة بأجــرة عــن ‪ -‬ســماع الدعــوى غيابي ـ ًا لتعــذر‬\n‫إبــاغ املدعــى عليــه ‪ -‬البينــة بشــهادة الشــهود واليمــن ‪ -‬األصــل عــدم‬\n‫دفــع األجــرة ‪ -‬وجــوب الوفــاء بالعقــود احلكــم بإلــزام املدعــى عليــه‬\n‫بدفــع باقــي أجــرة العــن ‪ -‬رفــع احلكــم حملكمــة االســتئناف لتعــذر‬\n                                            ‫تبليــغ املدعــى عليــه باحلكــم‪.‬‬\n\n\n\n\n                   ‫‪ .1‬قوله تعالى (يا أيها الذين آمنوا أوفوا بالعقود)‪.‬‬\n‫‪ .2‬قولــه صلــى اهلل عليــه وســلم (املســلمون علــى شــروطهم) رواه‬\n                                                  ‫الترمــذي وأبــو داوود‪.‬‬\n‫‪ .3‬قولــه صلــى اهلل عليــه وســلم (البينــة علــى املدعــي واليمــن علــى‬\n                                              ‫املدعــى عليــه) رواه الترمــذي‪.‬‬\n‫‪ .4‬جــاء يف مجمــوع الفتــاوى ‪( 24/300‬إذا كان الــذي عليــه احلــق قــادرا‬\n‫علــى الوفــاء وعطلــه حتــى أحوجــه إلــى الشــكاية فمــا غرمــه بســبب‬\n      ‫ذلــك فهــو علــى الظالــم املماطــل إذا غرمــه علــى الوجــه املعتــاد)‪.‬‬\n                          ‫‪ .5‬املادة ‪ 55‬و‪ 5/176‬من نظام املرافعات الشرعية‪.‬‬\n                                                     ‫‪ .6‬قاعدة‪ :‬األصل العدم ‪.‬‬\n\n\n\n\n                                                                                  ‫‪184‬‬\n\f      ‫ادعــى املدعــي ضــد املدعــى عليــه الغائــب عــن مجلــس احلكــم بأنــه‬\n      ‫كان مســتأجر ًا للشــقة رقــم ‪ 11‬يف عمــارة بحــي ‪ ...‬مبحافظــة جــدة‪،‬‬\n      ‫بأجــرة ســنوية قدرهــا اثنــان وعشــرون ألــف ريــال‪ ،‬إضافــة إلــى اخلدمــات‬\n      ‫مببلــغ قــدره ألفــان وأربعمائــة ريــال‪ ،‬اعتبــار ًا مــن تاريــخ ‪1432/9/1‬هــ‪،‬‬\n      ‫وقــد أخلــى العقــار يف ‪1434/2/10‬ه ـ مبوجــب محضــر معــد مــن قبــل‬\n      ‫حــارس العمــارة واثنــن مــن ســكانها‪ ،‬وبقــي يف ذمتــه مــن أجــرة العقــار‬\n      ‫مــن تاريــخ ‪1432/11/1‬ه ـ وحتــى تاريــخ اإلخــاء يف ‪1434/2/10‬ه ـ‬\n      ‫مبلغــا قــدره واحــد وثالثــون ألفــا ومائــة وســبعون ريــا ًال ‪ ،‬وعليــه فاتــورة‬\n      ‫اســتهالك كهربــاء مبلغــا قــدره أربعمائــة وثمانيــة وخمســون ريــاال‬\n      ‫وخمســه وأربعــون هللــة‪ ،‬وقــد نصــت الفقــرة ‪ 19‬مــن العقــد املبــرم بــن‬\n      ‫الطرفــن علــى أنــه (إذا تأخــر الطــرف الثانــي عــن دفــع أي مبلــغ مســتحق‬\n      ‫مــدة خمســة عشــر يومــا فــإن ‪ ..‬للطــرف األول أو نائبــه احلــق يف رفــع‬\n      ‫القضيــة إلــى اجلهــة املختصــة إلجبــار الطــرف الثانــي بدفــع املســتحق‬\n      ‫مــع إلــزام الطــرف الثانــي بدفــع ‪ %25‬مــن أصــل املبلــغ زيــادة علــى املبلــغ‬\n      ‫األصلــي)‪ ،‬وقدرهــا ســبعة آالف وتســعمائة وســبعة ريــاالت‪ ،‬يطلــب إلزام‬\n      ‫املدعــى عليــه بدفــع كامــل املبلــغ محــل الدعــوى هكــذا ادعى‪،‬لــم يبلــغ‬\n      ‫املدعــى عليــه حيــث لــم يتــم العثــور عليــه حســب إفــادة الشــرطة‪ ،‬جــرى‬\n      ‫ســماع الدعــوى غيابيـ ًا بنــاء علــى املــادة ‪ 55‬مــن نظــام املرافعات الشــرعية‬\n      ‫‪ ،‬بينــة املدعــي عقــد اإليجــار وصــك ملكيــة العقــار ومحضــر اإلخــاء‪،‬‬\n      ‫كمــا أحضــر شــاهدين شــهدا بإخــاء املدعــى عليــه للعقــار كمــا يف‬\n      ‫الدعــوى‪ ،‬قــرر املدعــي بــأن املدعــى عليــه ســلم مبلــغ وقــدره ســبعة آالف‬\n\n‫‪185‬‬\n\f‫ريــال حلــارس العمــارة وأن املتبقــي يف ذمتــه مــن املبلــغ املدعــى بــه قــدره‬\n‫اثنــان وثالثــون ألــف وخمســمائة وثالثــون رياالً‪،‬حلف املدعــي على صحة‬\n‫دعــواه بعــد طلبهــا منــه‪ ،‬وبنــاء علــى البينــة ســالفة الذكــر‪ ،‬وبنــاء علــى‬\n‫أن األصــل عــدم دفــع األجــرة ‪ ،‬وليمــن املدعــي علــى صحــة دعــواه وعــدم‬\n‫اســتالمه مــن مبلــغ الدعــوى شــيئا ‪ ،‬ولقولــه تعالــى (يــا أيهــا الذيــن آمنــوا‬\n‫أوفــوا بالعقــود)‪ ،‬وحلديــث (املســلمون علــى شــروطهم) رواه الترمــذي‬\n‫وأبــو داوود‪ ،‬وحلديــث (البينــة علــى املدعــي واليمــن علــى املدعــى عليــه)‬\n‫رواه الترمــذي ‪ ،‬وملــا جــاء يف الفتــاوى مــا نصــه قــال شــيخ اإلســام ( إذا‬\n‫كان الــذي عليــه احلــق قــادرا علــى الوفــاء وعطلــه حتــى أحوجــه إلــى‬\n‫الشــكاية فمــا غرمــه بســبب ذلــك فهــو علــى الظالــم املماطــل إذا غرمــه‬\n‫علــى الوجــه املعتــاد) ‪ ، 24/300‬وهــو موافــق للشــرط املضمــن بالعقــد‬\n‫مــن حيــث املبــدأ ‪ ،‬وبنــاء علــى املــادة ‪ 55‬و ‪ 5/176‬مــن نظــام املرافعــات‬\n‫الشــرعية‪ ،‬وملــا تقــدم صــدر احلكــم علــى املدعــى عليــه بدفــع مبلــغ قــدره‬\n‫اثنــان وثالثــون ألفــا وخمســمائة وثالثــون ريــاال للمدعــي‪ ،‬قنــع املدعــي‬\n‫باحلكــم مت بعــث املعاملــة حملكمــة االســتئناف لتدقيــق احلكــم‪ ،‬صــدق‬\n‫احلكــم مــن الدائــرة احلقوقيــة الرابعــة مبحكمــة االســتئناف مبنطقــة‬\n                                                                 ‫مكــة املكرمــة‪.‬‬\n\n\n\n\n‫احلمد هلل وحده وبعد فلدي ‪.......‬القاضي يف احملكمة العامة مبحافظة‬\n‫جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫مبحافظــة جدة‪/‬املســاعد برقــم ‪ 33710584‬وتاريــخ ‪1433/12/28‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 332267614‬وتاريــخ ‪1433/12/28‬ه ـ ففــي‬\n\n                                                                                        ‫‪186‬‬\n\f      ‫يــوم الســبت املوافــق ‪1434/03/28‬ه ـ افتتحــت اجللســة الســاعة ‪08 : 30‬‬\n      ‫وفيهــا حضــر املدعــي ‪ .......‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n      ‫رقــم ‪ .......‬ولــم يحضــر املدعــى عليــه ‪ .......‬ســعودي اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم ‪ .......‬وال مــن ميثلــه ‪ ،‬وقــد خطــاب مديــر مركــز‬\n      ‫شــرطة النزهــة برقــم ‪ 36/1300‬وتاريــخ ‪1434/2/19‬ه ـ واملتضمــن‬\n      ‫أنــه (بالرجــوع إلــى احلاســب اآللــي طرفنــا اتضــح بــأن عنــوان املذكــور‬\n      ‫حــي ‪ ...‬وبالبحــث والتحــري عــن املذكــور لــم يتــم العثــور عليــه كمــا مت‬\n      ‫االتصــال علــى جــوال‪ .......‬ومت الــرد مــن قبــل شــخص اســمه‪ ......‬وبســؤاله‬\n      ‫عــن املذكــور أفــاد بأنــه ال يعرفــه)‪ .‬أه ـ وبعرضــه علــى املدعــي قــال ‪:‬‬\n      ‫أطلــب التعميــم علــى املدعــى عليــه وإيقــاف خدماتــه‪ .‬ثــم رفعــت اجللســة‬\n      ‫لذلك‪ .‬ويف يوم األحد املوافق ‪1434/06/18‬هـ افتتحت اجللســة الســاعة‬\n      ‫‪ 10 : 30‬وفيهــا حضــر املدعــي ‪ .......‬ولــم يحضــر املدعــى عليــه‪.......‬وال من‬\n      ‫ميثلــه ‪ ،‬وقــد جــرت الكتابــة لشــرطة محافظــة جــدة إليقــاف خدمــات‬\n      ‫املدعــى عليــه مبوجــب خطابنــا رقــم ‪ 34764870‬وتاريــخ ‪1434/3/29‬هـ‬\n      ‫ولــم يراجعنــا أحــد ‪ ،‬فبنــاء علــى املــادة ‪ 55‬مــن نظــام املرافعــات الشــرعية‬\n      ‫ولتعــذر العثــور علــى املدعــى عليــه وتبليغــه فقــد قررت الســير يف الدعوى‬\n      ‫غيابيــا يف حــق املدعــى عليــه ‪ ،‬وادعــى املدعــي قائــا ‪ :‬لقــد كان املدعى‬\n      ‫عليــه مســتأجرا للشــقة رقــم ‪ 11‬يف عمــارة مملوكــة لــي يف حــي ‪ ...‬رقــم‬\n      ‫‪ ....‬مبحافظــة جــدة ‪ ،‬بأجــرة ســنوية قدرهــا اثنــان وعشــرون ألــف ريــال ‪،‬‬\n      ‫إضافــة إلــى اخلدمــات مببلــغ قــدره ألفــان وأربعمائــة ريــال‪ ،‬اعتبــارا مــن‬\n      ‫تاريــخ ‪1432/9/1‬ه ـ ‪ ،‬مبوجــب عقــد إيجــار رقــم ‪ 11‬فئــة (أ) وتاريــخ‬\n      ‫‪1432/9/1‬ه ـ ‪ ،‬وقــد أخلــى العقــار يف ‪1434/2/10‬ه ـ مبوجــب محضر‬\n      ‫معــد مــن قبــل حــارس العمــارة واثنــن مــن ســكانها ‪ ،‬وبقــي يف ذمتــه‬\n\n\n‫‪187‬‬\n\f‫مــن أجــرة العقــار مــن تاريــخ ‪1432/11/1‬ه ـ وحتــى تاريــخ اإلخــاء يف‬\n‫‪1434/2/10‬ه ـ مبلغــا قــدره واحــد وثالثــون ألفــا ومائــة وســبعون ريــاال ‪،‬‬\n‫وعليــه فاتــورة اســتالك كهربــاء مبلغــا قــدره أربعمائة وثمانية وخمســون‬\n‫ريــاال وخمســة وأربعــون هللــة مبوجــب فاتــورة اســتالك كهربــاء رقــم‬\n‫‪ 24902‬للفتــرة مــن ‪1434/1/7‬ه ـ وحتــى ‪1434/2/6‬ه ـ للحســاب رقــم‬\n‫‪ ، 267384906‬وقــد نصــت الفقــرة ‪ 19‬مــن العقــد املبــرم بــن الطرفــن‬\n‫علــى أنــه (إذا تأخــر الطــرف الثانــي عــن دفــع أي مبلــغ مســتحق مــدة‬\n‫خمســة عشــر يومــا فــإن ‪ ..‬للطــرف األول أو نائبــه احلــق يف رفــع القضيــة‬\n‫إلــى اجلهــة املختصــة إلجبــار الطــرف الثانــي بدفــع املســتحق مــع إلــزام‬\n‫الطــرف الثانــي بدفــع ‪ %25‬مــن أصــل املبلــغ زيــادة علــى املبلــغ األصلــي) ‪،‬‬\n‫وقدرهــا ســبعة آالف وتســعمائة وســبعة ريــاالت ‪ ،‬أطلــب إلــزام املدعــى‬\n‫عليــه بدفــع كامــل املبلــغ محــل الدعــوى وقــدره تســعة وثالثــون ألفــا‬\n‫وخمســمائة وخمســة وثالثون رياال ‪ .‬هذه دعواي ‪ .‬ثم أبرز املدعي صورة‬\n‫مــن عقــد اإليجــار وأصــل محضــر اإلخــاء وأصــل فاتــورة اســتهالك‬\n‫كهربــاء ‪ ،‬ومت تزويــد املعاملــة بنســخة منهــا ‪ ،‬وبســؤاله عــن أصــل عقــد‬\n‫اإليجــار وأصــل صــك امللكيــة وشــهود محضــر اإلخــاء قــال‪ :‬أطلــب‬\n‫اإلمهــال إلحضارهــا يف اجللســة القادمــة ‪ .‬ثــم رفعــت اجللســة لذلــك‪ .‬ويف‬\n‫يــوم االثنــن املوافــق ‪1434/07/17‬ه ـ افتتحــت اجللســة الســاعة ‪02 : 00‬‬\n‫وفيهــا حضــر املدعــي ‪ .......‬ولــم يحضــر املدعــى عليــه ‪ .......‬وال مــن ميثلــه‪،‬‬\n‫وقــد أبــرز املدعــي أصــل صــك امللكيــة الصــادر مــن كتابة العــدل الولى‬\n‫بجــدة برقــم ‪ 3557‬وتاريــخ ‪1420/12/27‬ه ـ واملتضمــن انتقــال ملكيتــه‬\n‫للمدعــي يف ‪1425/6/23‬ه ـ ‪ ،‬كمــا أبــرز أصــل عقــد اإليجــار‪ ،‬ومت‬\n‫تزويــد املعاملــة بنســخة منهمــا ‪ ،‬كمــا أحضــر للشــهادة وأدائهــا كال‬\n\n\n                                                                                        ‫‪188‬‬\n\f      ‫مــن ‪.......‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪.......‬وهــو مــن‬\n      ‫مواليــد ‪1403‬ه ـ ويعمــل يف ‪.......‬ويســكن يف حــي ‪.......‬مبحافظــة جــدة‪،‬‬\n      ‫وهــو ابــن أخ للمدعــي ‪ ،‬و‪.......‬مصــري اجلنســية مبوجــب اإلقامــة رقــم‬\n      ‫‪.......‬وهــو مــن مواليــد ‪1979‬م ويعمــل حــارس للعمــارة محــل الدعــوى لــدى‬\n      ‫املدعــي ‪ ،‬ويســكن فيهــا بحــي ‪ ...‬رقــم ‪ ...‬مبحافظــة جــدة ‪ ،‬وشــهد كل‬\n      ‫واحــد منهمــا مبفــرده قائــا ‪ :‬أشــهد هلل تعالــى بــأن املدعــى عليــه ‪.......‬‬\n      ‫قــد أخلــى الشــقة رقــم ‪ 11‬محــل الدعــوى يف ‪1434/2/10‬ه ـ بعــد أن‬\n      ‫أخــذ كل أغراضــه ‪ ،‬وســلم املفتــاح للشــاهد الثانــي حــارس العمــارة ‪.‬‬\n      ‫هكــذا شــهدا ‪ .‬وقــرر املدعــي قائــا ‪ :‬لقــد تبــن لــي بــأن املدعــى عليــه‬\n      ‫قــد ســدد مبلغــا قــدره ســبعة آالف ريــال وســلمها حلــارس العمــارة وهــو‬\n      ‫الشــاهد الثانــي ‪ ،‬وبقــي يف ذمتــه مــن مبلــغ الدعــوى مبلغــا قــدره اثنــان‬\n      ‫وثالثــون ألفــا وخمســمائة وثالثــون ريــاال ‪ ،‬وأطلــب إلــزام املدعــى عليــه‬\n      ‫بدفــع هــذا املبلــغ بالتفصيــل الســابق ‪ .‬وبعــرض اليمــن علــى املدعــي علــى‬\n      ‫صحــة الدعــوى وعــدم اســتالمه مــن مبلــغ الدعــوى شــيئا اســتعد لذلــك‪،‬‬\n      ‫ثــم حلــف قائــا ‪ :‬واهلل العظيــم الــذي ال إلــه إال هــو أن املدعــى عليــه‬\n      ‫يف‪.......‬ي كان مســتأجرا للشــقة رقــم ‪ 11‬يف عمــارة مملوكــة لــي يف‬\n      ‫حــي ‪.......‬رقــم ‪ ...‬مبحافظــة جــدة ‪ ،‬بأجــرة ســنوية قدرهــا اثنان وعشــرون‬\n      ‫ألــف ريــال ‪ ،‬إضافــة إلــى اخلدمــات مببلــغ قــدره ألفــان وأربعمائــة ريــال‬\n      ‫‪ ،‬اعتبــارا مــن تاريــخ ‪1432/9/1‬ه ـ ‪ ،‬مبوجــب عقــد إيجــار رقــم ‪11‬‬\n      ‫فئــة (أ) وتاريــخ ‪1432/9/1‬ه ـ ‪ ،‬وقــد أخلــى العقــار يف ‪1434/2/10‬ه ـ‬\n      ‫مبوجــب محضــر معــد مــن قبــل حــارس العمــارة واثنــن مــن ســكانها ‪،‬‬\n      ‫وبقــي يف ذمتــه مــن أجــرة العقــار مــن تاريــخ ‪1432/11/1‬ه ـ وحتــى تاريــخ‬\n      ‫اإلخــاء يف ‪1434/2/10‬ه ـ مبلغــا قــدره أربعــة وعشــرون ألفــا ومائــة‬\n\n\n‫‪189‬‬\n\f‫وســبعون ريــاال ‪ ،‬وعليــه فاتــورة اســتالك كهربــاء مبلغــا قــدره أربعمائــة‬\n‫وثمانيــة وخمســون ريــاال وخمســة وأربعــون هللــة مبوجــب فاتورة اســتالك‬\n‫كهربــاء رقــم ‪ 24902‬للفتــرة مــن ‪1434/1/7‬ه ـ وحتــى ‪1434/2/6‬ه ـ‬\n‫للحســاب رقــم ‪ ، 267384906‬وقــد نصــت الفقــرة ‪ 19‬مــن العقــد املبــرم‬\n‫بــن الطرفــن علــى أنــه (إذا تأخــر الطــرف الثانــي عــن دفــع أي مبلــغ‬\n‫مســتحق مــدة خمســة عشــر يومــا فــإن ‪ ..‬للطــرف األول أو نائبــه احلــق يف‬\n‫رفــع القضيــة إلــى اجلهــة املختصــة إلجبــار الطــرف الثانــي بدفــع املســتحق‬\n‫مــع إلــزام الطــرف الثانــي بدفــع ‪ %25‬مــن أصــل املبلــغ زيــادة علــى املبلــغ‬\n‫األصلــي) ‪ ،‬وقدرهــا ســبعة آالف وتســعمائة وســبعة ريــاالت ‪ ،‬وبقــي يف‬\n‫ذمتــه مــن مبلــغ الدعــوى مبلغــا قــدره اثنــان وثالثــون ألفــا وخمســمائة‬\n‫وثالثــون ريــاال‪ ،‬ولــم يدفــع املدعــى عليــه مــن ذلــك املبلــغ شــيئا حتــى‬\n‫اآلن‪ .‬هكــذا حلــف ‪ .‬فبنــاء علــى مــا تقــدم مــن الدعــوى والبينــة املتمثلــة‬\n‫يف الصــك رقــم ‪ 3557‬وتاريــخ ‪1420/12/27‬هــ‪ ،‬وعقــد اإليجــار رقــم‬\n‫‪ 11‬فئــة (أ) وتاريــخ ‪1432/9/1‬ه ـ ‪ ،‬وشــهادة ‪ ،..............‬ومحضــر‬\n‫اإلخــاء‪ ،‬وفاتــورة اســتهالك كهربــاء رقــم ‪ ، 24902‬وبنــاء علــى أن‬\n‫األصــل عــدم دفــع األجــرة ‪ ،‬وليمــن املدعــي علــى صحــة دعــواه وعــدم‬\n‫اســتالمه مــن مبلــغ الدعــوى شــيئا ‪ ،‬ولقولــه تعالــى (يــا أيهــا الذيــن آمنــوا‬\n‫أوفــوا بالعقــود) ‪ ،‬وحلديــث (املســلمون علــى شــروطهم) رواه الترمــذي‬\n‫وأبــو داوود ‪ ،‬وحلديــث (البينــة علــى املدعــي واليمــن علــى املدعــى عليــه)‬\n‫رواه الترمــذي ‪ ،‬قــال أبــو عيســى ‪ :‬العمــل عنــد أهــل العلــم مــن أصحــاب‬\n‫النبــي صلــى اهلل عليــه وســلم وغيرهــم أن البينــة علــى املدعــي واليمــن‬\n‫علــى املدعــى عليــه ‪ ،‬وملــا جــاء يف الفتــاوى مــا نصــه قــال شــيخ اإلســام‬\n‫(إذا كان الــذي عليــه احلــق قــادرا علــى الوفــاء وعطلــه حتــى أحوجــه إلــى‬\n\n\n                                                                                        ‫‪190‬‬\n\f      ‫الشــكاية فمــا غرمــه بســبب ذلــك فهــو علــى الظالــم املماطــل إذا غرمــه‬\n      ‫علــى الوجــه املعتــاد) ‪ ،24/300‬وهــو موافــق للشــرط املضمــن بالعقــد‬\n      ‫مــن حيــث املبــدأ‪ ،‬وبنــاء علــى املــادة ‪ 55‬و ‪ 5/176‬مــن نظــام املرافعــات‬\n      ‫الشــرعية‪ ،‬لذلــك كلــه‪ ،‬فقــد حكمــت علــى املدعــى عليــه‪ ...........‬بدفــع‬\n      ‫مبلــغ قــدره اثنــان وثالثــون ألفــا وخمســمائة وثالثــون ريــاال للمدعــي‬\n      ‫‪ ...........‬وبــه قنــع املدعــي‪ ،‬وقــررت بعــث املعاملــة حملكمــة االســتئناف‬\n      ‫لتدقيــق احلكــم لتعــذر العثــور علــى املدعــى عليــه‪ .‬وأقفلــت اجللســة‬\n      ‫الســاعة ‪ .02 : 40‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                    ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/07/17‬ه ـ‬\n      ‫احلمــد هلل‪ ،‬والصــاة والســام علــى رســول اهلل‪ ،‬وبعــد‪ .:‬فقــد‬\n      ‫جــرى اطالعنــا نحــن رئيــس وعضــوي الدائــرة احلقوقيــة الرابعــة يف‬\n      ‫محكمــة االســتئناف مبنطقــة مكــة املكرمــة علــى الصــك الصــادر‬\n      ‫مــن فضيلــة الشــيخ‪ .......‬القاضــي باحملكمــة العامــة بجــدة واملســجل‬\n      ‫بعــدد‪ 34271615‬وتاريــخ ‪1434/7/17‬ه ـ املتضمــن دعــوى ‪ .......‬ضــد‬\n      ‫‪ .......‬واحملكــوم فيــه مبــا دون باطنــة وبدراســة الصــك وصــورة ضبطــه‬\n      ‫تقــررت املوافقــة علــى احلكــم واملدعــي عليــه علــى حجتــه إذا حضــر‬\n                    ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪191‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"612f1ba9-3f27-52bc-993f-69d3ecdc8564","source_page_start":184,"source_page_end":191,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"f119e2076133a1638374c24f2193a49ca29814e168b2ab1567b413570d934d5f","normalized_text_hash":"2ee8d3c609e3430eedc002ef5dd1846ebbf1fb519706c5ac3888d6c6552fd1f3","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v7-p184-34271615"},{"id":"f912dc5f-1519-5730-bc23-6405cc4880d3","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقد -إجارة -إخاء عقار من غائب -سماع الدعوى غيابي ا لتعذر تبليغ املدعى عليه -البينة بشهادة الشهود املعدلن واليمني -وجوب الوفاء بالعقود -احلكم بفتح العن وإخالءها وحفظ محتويات العن يف بيت املال -بيع ما يخشى تلفه وإيداع ثمنه يف بيت املال -الغائب على حجته متى حضر .","document_number":"3463007","case_number":"34106198","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/15","year":"1434","subject":"عقد -إجارة -إخاء عقار من غائب -سماع الدعوى غيابي ا لتعذر تبليغ املدعى عليه -البينة بشهادة الشهود املعدلن واليمني -وجوب الوفاء بالعقود -احلكم بفتح العن وإخالءها وحفظ محتويات العن يف بيت املال -بيع ما يخشى تلفه وإيداع ثمنه يف بيت املال -الغائب على حجته متى حضر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/3/15 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪3463007 :‬‬\n                   ‫َر ْق ُم الدعوى‪34106198 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n           ‫‪ 34211510‬تاريخه‪1434/5/12:‬هـ‬\n\n\n‫عقــد ‪ -‬إجــارة ‪ -‬إخــاء عقــار مــن غائــب ‪-‬ســماع الدعــوى غيابيـ ًا لتعــذر‬\n‫تبليــغ املدعــى عليــه ‪-‬البينــة بشــهادة الشــهود املعدلــن واليمني ‪ -‬وجوب‬\n‫الوفــاء بالعقــود ‪ -‬احلكــم بفتــح العــن وإخالءهــا وحفــظ محتويــات‬\n‫العــن يف بيــت املــال ‪ -‬بيــع مــا يخشــى تلفــه وإيــداع ثمنــه يف بيــت املــال‬\n                                         ‫‪ -‬الغائــب علــى حجتــه متــى حضــر ‪.‬‬\n\n\n\n                      ‫‪ .1‬قوله تعالى (يا أيها الذين آمنوا أوفوا بالعقود)‪.‬‬\n‫‪ .2‬قولــه صلــى اهلل عليــه وســلم (املســلمون علــى شــروطهم) رواه‬\n                                                  ‫الترمــذي وأبــو داود‪.‬‬\n‫‪ .3‬قولــه صلــى اهلل عليــه وســلم (ال ضــرر وال ضــرار) رواه أبــو داود‬\n                                                   ‫وصححــه احلاكــم‪.‬‬\n‫‪ .4‬قولــه صلــى اهلل عليــه وســلم (البينــة علــى املدعــي واليمــن علــى‬\n                                         ‫املدعــى عليــه) رواه الترمــذي‪.‬‬\n                    ‫‪ .5‬املادة ‪ 55‬و ‪ 5/176‬من نظام املرافعات الشرعية‪.‬‬\n\n\n\n‫ادعــى املدعــي ضــد املدعــى عليــه الغائب عن مجلــس احلكم بأن املدعى‬\n‫عليــه اســتأجر منــه بيــت شــعبي يف ‪ ...‬حــي ‪ ...‬ملــدة ســنة اعتبــارا مــن تاريــخ‬\n\n                                                                                         ‫‪192‬‬\n\f      ‫‪1433/11/4‬ه ـ بأجــرة شــهرية قدرهــا ألــف ومائتــان وخمســون ريــاال ‪،‬‬\n      ‫وقــد دفــع املدعــى عليــه أجــرة شــهرين مــن تاريــخ العقــد ‪ ،‬ثــم انقطــع‬\n      ‫عــن الســداد‪ ،‬ومنــذ شــهر محــرم لعــام ‪1434‬ه ـ واملدعــى عليــه متغيــب‪،‬‬\n      ‫ولتضــرره مــن حرمانــه مــن االنتفــاع بالعقــار وعــدم دفــع املدعــى عليــه‬\n      ‫ألجــرة العقــار‪ ،‬يطلــب احلكــم بفتــح العقــار عــن طريــق اجلهــات املختصــة‬\n      ‫وإخــاء املدعــى عليــه منــه هكــذا ادعــى‪ ،‬مت البحــث عــن املدعــى عليــه‬\n      ‫لتبليغــه ولــم يعثــر عليــه حســب إفــادة الشــرطة‪ ،‬بنــاء علــى املــادة ‪ 55‬مــن‬\n      ‫نظــام املرافعــات الشــرعية ولتعــذر تبليــغ املدعــى عليــه تقــرر النظــر يف‬\n      ‫الدعــوى غيابي ـ ًا ‪ ،‬بينــة املدعــي عقــد اإليجــار وشــاهدان شــهدا طبــق‬\n      ‫دعــواه‪ ،‬حلــف املدعــي اليمــن بعــد طلبهــا منــه علــى صحــة دعــواه وعلــى‬\n      ‫عــدم اســتالمه األجــرة بعــد الشــهرين التاليــن لبدايــة العقــد ‪-‬لتغيــب‬\n      ‫املدعــى عليــه ولقولــه تعالــى (يــا أيهــا الذيــن آمنــوا أوفــوا بالعقــود)‬\n      ‫وقولــه صلــى اهلل عليــه وســلم (املســلمون علــى شــروطهم) رواه الترمــذي‬\n      ‫وأبــو داوود وقولــه صلــى اهلل عليــه وســلم ( ال ضــرر و ال ضــرار )‪ ،‬ملــا‬\n      ‫تقــدم احلكــم بفتــح العقــار محــل الدعــوى وإخــاؤه عــن طريــق اجلهــات‬\n      ‫املختصــة ‪ ،‬واالحتفــاظ مبوجــودات العقــار مــا يخــص املدعــى عليــه منــه‬\n      ‫لــدى اجلهــة املعنيــة ‪ ،‬وبيــع مــا يخشــى تلفــه ‪ ،‬وإيــداع ثمنــه لــدى بيــت‬\n      ‫مــال احملكمــة وتســليم املدعــي عقــاره ليتمكــن مــن االنتفــاع بــه‪ ،‬جــرى‬\n      ‫إفهــام املدعــي بــأن املدعــى عليــه علــى حجتــه متــى حضــر‪ ،‬بعــث املعاملــة‬\n      ‫حملكمــة االســتئناف لتدقيــق احلكــم‪ ،‬صــدق احلكــم مــن الدائــرة‬\n            ‫احلقوقيــة الثالثــة مبحكمــة االســتئناف مبنطقــة مكــة املكرمــة ‪.‬‬\n\n\n\n\n‫‪193‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.......‬القاضــي يف احملكمــة العامــة‬\n‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة مبحافظــة جدة‪/‬املســاعد برقــم ‪ 34106198‬وتاريــخ‬\n‫‪1434/03/03‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34533438‬وتاريــخ‬\n‫‪1434/03/01‬ه ـ ففــي يــوم األحــد املوافــق ‪1434/03/15‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪ 02 : 00‬وفيهــا حضــر املدعــي ‪.......‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم ‪.......‬ولــم يحضــر املدعــى عليــه ‪.......‬‬\n‫باكســتاني اجلنســية مبوجــب اإلقامــة رقــم ‪.......‬وال مــن ميثلــه ‪ ،‬وقــد‬\n‫وردنــا خطــاب مديــر شــرطة محافظــة جــدة برقــم ‪25/1/20/1653‬‬\n‫وتاريــخ ‪1434/2/25‬ه ـ املتضمــن أن مت البحــث والتحــري عــن املســتأجر‬\n‫ولــم يعثــر عليــه ‪ .‬أه ـ فبنــاء علــى املــادة ‪ 55‬مــن نظــام املرافعــات الشــرعية‬\n‫‪ ،‬ولتعــذر تبليــغ املدعــى عليــه فقــد قــررت النظــر يف الدعــوى غيابيــا‬\n‫يف حــق املدعــى عليــه ‪ ،‬وادعــى املدعــي قائــا ‪ :‬لقــد اســتأجر املدعــى‬\n‫عليــه منــي عقــارا مملــوكا لــي مبوجــب وثيقــة مبايعــة أنقــاض برقــم‬\n‫‪ 126‬وتاريــخ ‪1425/4/20‬ه ـ علــى أوراق مؤسســة ‪ .......‬للمقــاوالت‬\n‫العامــة والعقــار وهــو عبــارة بيــت شــعبي يف ‪ ...‬حــي ‪ ...‬ويحــده مــن الشــمال‬\n‫حــوش ‪ ،.......‬ومــن اجلنــوب شــارع عــرض ‪ 8‬م ‪ ،‬ومــن الغــرب شــارع عــرض‬\n‫‪7‬م ومــن الشــرق ملــك ‪ ،‬ومبوجــب عــداد التيــار الكهربائــي املســجل‬\n‫باســمي حتــت رقــم املشــترك ‪ 10023‬للحســاب رقــم ‪ ،.......‬وقــد اســتأجر‬\n‫املدعــى عليــه ذلــك العقــار ملــدة ســنة اعتبــارا مــن تاريــخ ‪1433/11/4‬ه ـ‬\n‫بأجــرة شــهرية قدرهــا ألــف ومائتــان وخمســون ريــاال مبوجــب عقــد‬\n\n                                                                                         ‫‪194‬‬\n\f      ‫اإليجــار رقــم ‪ 0337‬وتاريــخ ‪1433/11/4‬ه ـ احملــرر علــى أوراق ‪.......‬‬\n      ‫للعقــار ‪ ،‬وقــد دفــع املدعــى عليــه أجــرة شــهرين مــن تاريــخ العقــد ‪ ،‬ثــم‬\n      ‫انقطــع عــن الســداد ‪ ،‬ومنــذ شــهر محــرم لعــام ‪1434‬ه ـ واملدعــى عليــه‬\n      ‫متغيــب ‪ ،‬ولتضــرري مــن حرمانــي مــن االنتفــاع بعقــاري وعــدم دفــع‬\n      ‫املدعــى عليــه ألجــرة العقــار ‪ ،‬أطلــب احلكــم بفتــح العقــار عــن طريــق‬\n      ‫اجلهــات املختصــة ومتكينــي مــن عقــاري وإخــاء املدعــى عليــه منــه ومــن‬\n      ‫مــا ميلكــه فيــه ‪ .‬هــذه دعــواي ‪ .‬ثــم أبــرز املدعــي صــورة مــن وثيقــة مبايعــة‬\n      ‫أنقــاض وأصــل فاتــورة اســتهالك تيــار كهربائــي للحســاب املذكــور يف‬\n      ‫الدعــوى برقــم ‪ 13666‬وأصــل عقــد اإليجــار املشــار إليهــا يف الدعــوى‬\n      ‫‪ ،‬ومت تزويــد أوراق املعاملــة بنســخة منهــا ‪ ،‬وبطلــب زيــادة بينــة مــن‬\n      ‫املدعــي علــى صحــة دعــواه أحضــر للشــهادة وأدائهــا كال مــن ‪.......‬‬\n      ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪.......‬وهــو مــن مواليــد‬\n      ‫‪1394‬ه ـ ويعمــل يف ‪ ، ...‬ويســكن يف حــي ‪.......‬مبحافظــة جــدة ‪ ،‬وهــو‬\n      ‫أخ للمدعــي‪ ....... ،‬فلســطيني اجلنســية بوثيقــة مصريــة مبوجــب اإلقامــة‬\n      ‫رقــم ‪.......‬وهــو مــن مواليــد ‪1386‬ه ـ ويعمــل يف مؤسســة ‪ ،.......‬ويســكن‬\n      ‫يف حــي ‪.......‬مبحافظــة جــدة ‪ ،‬وليــس بينــه وبــن الطرفني قرابة ‪ ،‬وشــهد‬\n      ‫كل واحــد منهمــا مبفــرده قائــا ‪ :‬أشــهد بــاهلل العظيــم بــأن املدعــي‬\n      ‫‪.......‬مالــك للعقــار محــل الدعــوى ‪ ،‬وأن املدعــى عليــه ‪ ..............‬كان‬\n      ‫مســتأجرا لذلــك العقــار ‪ ،‬وأن املدعــى عليــه متغيــب منــذ حوالــي شــهرين‬\n      ‫‪ ،‬والعقــار محــل الدعــوى مغلــق منــذ تغيــب املدعــى عليــه ‪ .‬هكــذا شــهدا‬\n      ‫‪ .‬وعــدال مــن قبــل ‪.......‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n      ‫‪.......‬و‪.......‬مينــي اجلنســية مبوجــب اإلقامــة رقــم ‪ ........‬وبعــرض اليمــن‬\n      ‫علــى املدعــي علــى صحــة دعــواه وعــدم اســتالمه ألجــرة العقــار محــل‬\n\n\n‫‪195‬‬\n\f‫الدعــوى بعــد الشــهرين التاليــن لبدايــة عقــد اإليجــار ولتغيــب املدعــى‬\n‫عليــه ‪ ،‬اســتعد لذلــك ‪ ،‬ثــم حلــف قائــا ‪ :‬واهلل العظيــم الــذي ال إلــه إال‬\n‫هــو أننــي أملــك عقــارا مبوجــب وثيقــة مبايعــة أنقــاض برقــم ‪ 126‬وتاريــخ‬\n‫‪1425/4/20‬ه ـ علــى أوراق مؤسســة ‪ .......‬للمقــاوالت العامــة والعقــار‬\n‫وهــو عبــارة بيــت شــعبي يف كيلــو ‪ 7‬حــي (‪ ،)....‬ومبوجــب عــداد التيــار‬\n‫الكهربائــي املســجل باســمي حتــت رقــم املشــترك ‪ 10023‬للحســاب‬\n‫رقــم ‪ ، 252591609‬وقــد اســتأجر املدعــى عليــه ‪ .......‬ذلــك العقــار ملــدة‬\n‫ســنة اعتبــارا مــن تاريــخ ‪1433/11/4‬ه ـ بأجــرة شــهرية قدرهــا ألــف‬\n‫ومائتــان وخمســون ريــاال مبوجــب عقــد اإليجــار رقــم ‪ 0337‬وتاريــخ‬\n‫‪1433/11/4‬ه ـ احملــرر علــى أوراق ‪.......‬للعقــار ‪ ،‬وقــد دفــع املدعــى عليه‬\n‫أجــرة شــهرين مــن تاريــخ العقــد ‪ ،‬ثــم انقطــع عــن الســداد ‪ ،‬ومنــذ شــهر‬\n‫محــرم لعــام ‪1434‬ه ـ واملدعــى عليــه متغيــب ‪ .‬هكــذا حلــف فبنــاء علــى‬\n‫مــا تقــدم مــن الدعــوى والبينــة املتمثلــة يف وثيقــة مبايعــة أنقــاض برقــم‬\n‫‪ 126‬وتاريــخ ‪1425/4/20‬ه ـ ‪ ،‬وفاتــورة اســتهالك التيــار الكهربائــي‬\n‫رقــم ‪ 13666‬للمشــترك ‪ 10023‬باحلســاب رقــم ‪ ، 252591609‬وعقــد‬\n‫اإليجــار رقــم ‪ 0337‬وتاريــخ ‪1433/11/4‬ه ـ ‪ ،‬ومــا شــهد بــه الشــاهدان‬\n‫‪....... .......‬واملعدلــة شــهادتهما مــن قبــل كل مــن ‪ ،.......‬وبنــاء علــى‬\n‫خطــاب مديــر شــرطة محافظــة جــدة برقــم ‪ 25/1/20/1653‬وتاريــخ‬\n‫‪1434/2/25‬ه ـ ‪ ،‬ولقولــه تعالــى (يــا أيهــا الذيــن آمنــوا أوفــوا بالعقــود) ‪،‬‬\n       ‫وحلديــث (املســلمون علــى شــروطهم) رواه الترمــذي وأبــو داوود ‪،‬‬\n‫وحلديث ( ال ضرر و ال ضرار ) رواه أبو داوود وصححه احلاكم ‪ ،‬وألن‬\n‫الضــرر يف الشــريعة مرفــوع ‪ ،‬وحلديــث (البينــة علــى املدعــي واليمــن‬\n‫علــى املدعــى عليــه) رواه الترمــذي ‪ ،‬قــال أبــو عيســى ‪ :‬العمــل عنــد أهــل‬\n\n\n                                                                                    ‫‪196‬‬\n\f      ‫العلــم مــن أصحــاب النبــي صلــى اهلل عليــه وســلم وغيرهــم أن البينــة علــى‬\n      ‫املدعــي واليمــن علــى املدعــى عليــه ‪ ،‬وبنــاء علــى املــادة ‪ 55‬و ‪ 5/176‬مــن‬\n      ‫نظــام املرافعــات الشــرعية ‪ ،‬لذلــك كلــه ‪ ،‬فقــد حكمــت بفتــح العقــار‬\n      ‫محــل الدعــوى وإخــاؤه عــن طريــق اجلهــات املختصــة‪ ،‬واالحتفــاظ‬\n      ‫مبوجــودات العقــار مــا يخــص املدعــى عليــه منــه لــدى اجلهــة املعنيــة ‪،‬‬\n      ‫وأمــرت ببيــع مــا يخشــى تلفــه ‪ ،‬وإيــداع ثمنــه لــدى بيــت مــال احملكمــة‪،‬‬\n      ‫وتســليم املدعــي عقــاره ليتمكــن مــن االنتفــاع بــه ‪ .‬وبــه حكمــت‪.‬‬\n      ‫وأفهمــت املدعــي بــأن املدعــى عليــه علــى حجتــه متــى حضــر‪ ،‬وقــررت‬\n      ‫بعــث املعاملــة حملكمــة االســتئناف لتدقيــق احلكــم ‪ .‬وأقفلــت اجللســة‬\n      ‫الســاعة ‪ . 02 : 30‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                       ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/03/15‬ه ـ‬\n      ‫احلمد هلل ‪ ،‬والصالة والسالم على رسول اهلل ‪ ،‬وبعد ‪ :‬ـ فقـد جـرى م ّنا‬\n      ‫نح ــن رئيس وأعضاء الدائ ــرة احلقوقي ــة الثالثة يف محكم ــة االستئناف‬\n      ‫مبنطقة مك ــة املكرم ــة االطال ُع عل ــى هـذا الصك الصـادر من فضيـلة‬\n      ‫الشي ــخ ‪ .......‬القاضــي باحملكمــة العامــة مبحافظــة جــدة واملســجل‬\n      ‫بعــدد ‪ 3463007‬وتــاري ــخ ‪1434/3/15‬ه ـ املتضمــن دعــوى ‪ .....‬ضــد‬\n      ‫‪ ( .......‬باكســتاني اجلنســية ) يف عقــار احملكــوم فيــه مبــا دون باطنــه‪.‬‬\n      ‫وبــدراس ــة احلك ــم وص ــورة ضبط ــه تقـ ـ ـ ـ ــررت املـ ــوافقـ ـ ـ ــة علــى احلكــم‬\n      ‫والغائــب علــى حجتــه واهلل املوفــق وصل ــى اهلل عل ــى نبي ــنا محم ــد وعل ــى‬\n                                                                         ‫آل ــه وصحبـه وسـلم‪.‬‬\n\n\n\n\n‫‪197‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"612f1ba9-3f27-52bc-993f-69d3ecdc8564","source_page_start":192,"source_page_end":197,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"2f316ea0f4d6f3866f4f2a16cd0634076b9750e5cb8f92161f9fa1b923f8ac2d","normalized_text_hash":"27121781410bc3d2fb1049f624651cdc323ffc62cec8932594081682ec8312af","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v7-p192-3463007"},{"id":"6bfda33b-1522-514b-ad8a-bb65012a7e48","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقد -إجارة -إخاء عقار النتهاء مدته -إخطار باإلخاء - املسلمون على شروطهم -إقرار املدعى عليه بالدعوى -احلكم","document_number":"34182875","case_number":"34110084","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالدمام","circuit":"الدائرة احلقوقية الثانية رقم 34255062يف 1434/06/28ه وللبيان","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/8","year":"1434","subject":"عقد -إجارة -إخاء عقار النتهاء مدته -إخطار باإلخاء - املسلمون على شروطهم -إقرار املدعى عليه بالدعوى -احلكم","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1434/4/8 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34182875 :‬‬\n                   ‫َر ْق ُم الدعوى‪34110084 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n           ‫‪ 34255062‬تاريخه‪1434/6/28 :‬هـ‬\n\n\n‫عقــد ‪ -‬إجــارة ‪ -‬إخــاء عقــار النتهــاء مدتــه ‪-‬إخطــار باإلخــاء ‪-‬‬\n‫املســلمون علــى شــروطهم ‪ -‬إقــرار املدعــى عليــه بالدعــوى ‪ -‬احلكــم‬\n                                                      ‫بإخــاء العقــار‪.‬‬\n\n\n\n\n              ‫‪ .1‬قوله صلى اهلل عليه وسلم (( املسلمون على شروطهم ))‬\n                               ‫‪ .2‬القاعدة الفقهية ( ال عذر ملن اقر )‬\n\n\n\n\n‫ادعــى املدعــي بالوكالــة بــأن املدعــى عليــه اســتأجر مــن موكلــه‬\n‫شــقة ذكــر وصفهــا يف نــص القضيــة ملــدة ســنة قابلــة للتجديــد اعتبــار ًا‬\n‫مــن ‪1430/3/24‬ه ـ وقــد انتهــت مــدة العقــد وطالــب املدعــي أصالــة‬\n‫مــن املدعــى عليــه إخــاء الشــقة قبــل نهايــة العقــد بســتة أشــهر لعــدم‬\n‫رغبتــه بالتجديــد لكــن املدعــى عليــه رفــض اإلخــاء وطلــب احلكــم‬\n‫علــى املدعــى عليــه بإخــاء العقــار‪ ،‬أجــاب املدعــى عليــه باملصادقــة‬\n‫علــى الدعــوى وذكــر انــه لــن يخــرج إال بعــد أن يجــد لــه عقــار ًا آخــر‬\n‫‪-‬مت اطــاع ناظــر القضيــة علــى عقــد اإليجــار وصــك امللكيــة‪ ،‬صــدر‬\n‫ـاء علــى قولــه صلــى اهلل عليه وســلم (( املســلمون‬‫حكــم ناظــر القضيــة بنـ ً‬\n‫علــى شــروطهم )) و إلقــرار املدعــى عليــه باحلكــم علــى املدعــى عليــه‬\n\n                                                                                   ‫‪198‬‬\n\f      ‫بإخــاء العقــار فــور ًا وتســليمه للمدعــي بحالتــه الســليمة‪ ،‬قــرر املدعــى‬\n      ‫عليــه املعارضــة‪ ،‬صــدر قــرار محكمــة االســتئناف باملنطقــة الشــرقية‬\n                                                       ‫باملصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا‪ ...........‬القاضــي يف احملكمــة العامــة‬\n      ‫بالدمــام وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بالدمــام املســاعد برقــم ‪ 34110084‬وتاريــخ ‪1434/03/07‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 34577647‬وتاريــخ ‪1434/03/07‬ه ـ حضــر‬\n      ‫‪...........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‪ ...........‬بصفتــه‬\n      ‫وكيــا عــن املدعــي مبوجــب الوكالــة الصــادرة عــن كتــاب العــدل‬\n      ‫اجلفــر رقــم ‪.........‬مجلــد ‪ 1098‬بتاريــخ ‪1428/01/10‬ه ـ واملخــول‬\n      ‫لــه فيهــا باملطالبــة واملرافعــة واملخاصمــة وغيرهــا وحضــر حلضــوره‬\n      ‫‪ ...........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‪ ...........‬وادعــى‬\n      ‫األول قائــا اســتأجر هــذا احلاضــر معــي وأشــار إلــى املدعــى عليــه مــن‬\n      ‫موكلــي شــقة مكونــة مــن أربــع غــرف ودورتــن للميــاه ومطبــخ وصالــة‬\n      ‫ورقمهــا واحــد (‪ )1‬يف العقــار الكائــن بحــي ‪.........‬مبدينــة الدمــام‬\n      ‫واململــوك ملوكلــي مبوجــب الصــك الصــادر مــن كتابــة عــدل الدمــام‬\n      ‫األولــى برقــم ‪ 930106005923‬يف ‪1428/01/08‬ه ـ بأجــرة ســنوية‬\n      ‫قدرهــا اثنــان وعشــرون ألــف ريــال ملــدة ســنة قابلــة للتجديــد اعتبــارا‬\n      ‫مــن ‪ 1430/03 /24‬ه ـ وذلــك مبوجــب العقــد الصــادر مــن مكتــب‬\n      ‫‪ .........‬للخدمــات العقاريــة برقــم ‪ 953‬يف ‪1430/03/24‬ه ـ وقــد انتهــت‬\n      ‫املــدة يف ‪1434/03 /24‬ه ـ وطلــب منــه موكلــي إخــاء الشــقة قبلهــا‬\n\n‫‪199‬‬\n\f‫بســتة أشــهر لعــدم رغبــة موكلــي يف التجديــد لــه إال أنــه رفــض ولــذا‬\n‫وحيــث انتهــت مــدة اإليجــار ولــم يقــم باإلخــاء فأطلــب إلــزام املدعــى‬\n‫عليــه بإخــاء الشــقة املوصوفــة وتســليمها ملوكلــي حــاال هــذه دعــواي‬\n‫وبعــرض الدعــوى علــى املدعــى عليــه أجــاب بقولــه‪ :‬مــا ذكــره املدعــي‬\n‫وكالــة كلــه صحيــح فقــد اســتأجرت مــن موكلــه الشــقة املوصوفــة‬\n‫يف الدعــوى باألجــرة التــي ذكرهــا املدعــي وكالــة وقــد انتهــى العقــد‬\n‫يف‪1434/03/24‬ه ـ وصحيــح بــأن موكلــه أشــعرني باإلخــاء قبــل‬\n‫نهايتــه بســتة أشــهر إال أننــي لســت مســتعد باإلخــاء إال بعــد ســتة أشــهر‬\n‫مــن اآلن لكــي أمتكــن مــن البحــث عــن شــقة بديلــة هكــذا أجــاب وبــرد‬\n‫ذلــك علــى املدعــي وكالــة قــال موكلــي ال يوافــق علــى طلبــه ويطلــب‬\n‫إلزامــه باإلخــاء فــورا وقــد جــرى منــي االطــاع علــى العقــد املشــار إليــه‬\n‫بعــد أن أبــرزه املدعــي وكالــة فوجدتــه مطابقــا ملــا ذكــره كمــا اطلعــت‬\n‫علــى أصــل الصــك املشــار إليــه فوجدتــه مملــوكا للمدعــي أصالــة‬\n‫املدعــو فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وحيــث طلــب املدعــي‬\n‫وكالــة إلــزام املدعــى عليــه بإخــاء الشــقة املوصوفــة يف الدعــوى‬\n‫واململوكــة ملوكلــه النتهــاء العقــد و عــدم رغبــة موكلــه يف جتديــده‬\n‫وحيــث أقــر املدعــى عليــه باالســتئجار ومقــدار األجــرة وانتهــاء العقــد‬\n‫وإشــعاره باإلخــاء قبــل انتهائــة بســتة أشــهر وحيــث ال عــذر ملــن أقــر‬\n‫ولقولــه صلــى اهلل عليــه وســلم املســلمون علــى شــروطهم لــذا وجلميــع مــا‬\n‫تقــدم فقــد ألزمــت املدعــى عليــه بــأن يخلــي الشــقة املوصوفــة يف الدعــوى‬\n‫فــورا ويســلمها للمدعــي أصالــة بحالتهــا الســليمة ومبــا تقــدم حكمــت‬\n‫وبعــرض احلكــم عليــه قــرر اعتراضــه عليــه وطلــب االســتئناف بــدون‬\n‫تقــدمي الئحــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n\n\n                                                                                     ‫‪200‬‬\n\f                                     ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/04/07‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فقــد جــرى املصادقــة علــى هــذا احلكــم الصــادر‬\n      ‫منــا يف هــذه القضيــة وذلــك مبوجــب قــرار أصحــاب الفضيلــة قضــاة‬\n      ‫الدائــرة احلقوقيــة الثانيــة رقــم ‪ 34255062‬يف ‪1434/06/28‬ه ـ وللبيــان‬\n      ‫جــرى حتريــره وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد ‪.‬حــرر يف‬\n                                                                       ‫‪1434/07/09‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة احلقوقيــة‬\n      ‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة املقيــدة‬\n      ‫لــدى احملكمــة برقــم ‪ 341349347‬وتاريــخ ‪1434/ 6/5‬ه ـ الــواردة مــن‬\n      ‫فضيلــة رئيــس احملكمــة العامــة مبدينــة الدمــام برقــم ‪341074162‬‬\n      ‫وتاريــخ ‪1434/5/12‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة القاضي‬\n      ‫باحملكمــة الشــيخ‪ /‬املســجل برقــم ‪ 34182875‬وتاريــخ ‪1434/4/8‬ه ـ‬\n      ‫بشــأن دعــوى‪ /‬ضــد‪ /‬يف قضيــة حقوقيــة وقــد تضمــن الصــك حكــم‬\n      ‫فضيلــة القاضــي مبــا هــو مــدون ومفصــل فيــه ‪ .‬وبدراســة الصــك وصــورة‬\n      ‫ضبطــه وأوراق املعاملــة قررنــا املصادقــة علــى احلكم واهلل املوفق وصلى‬\n          ‫اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم حــرر يف‪1434/6/28‬ه ـ ‪.‬‬\n\n\n\n\n‫‪201‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"612f1ba9-3f27-52bc-993f-69d3ecdc8564","source_page_start":198,"source_page_end":201,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"6f03ff6c9adc19901e1dea4073cea32cc2577250afd298ed3bd51287ff065451","normalized_text_hash":"4c1ddbfbee8d6b0d6a9f17d9aa13fabd9efcd4ab3002043f145ce58c4efde8c6","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v7-p198-34182875"},{"id":"0928b3d1-b63e-5584-9dfd-97dd8fb0de22","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقد -إجارة -مطالبة بقيمة حتسينات -األصل يف الشروط احلل -ما يقوم به املستأجر من حتسينات ال تلزم املؤجر إذا نص العقد على ذلك -وجوب الوفاء بالعقود -رد دعوى املدعى .","document_number":"34203864","case_number":"34128028","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/1","year":"1434","subject":"عقد -إجارة -مطالبة بقيمة حتسينات -األصل يف الشروط احلل -ما يقوم به املستأجر من حتسينات ال تلزم املؤجر إذا نص العقد على ذلك -وجوب الوفاء بالعقود -رد دعوى املدعى .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/5/1 :‬هـ‬\n                ‫ُ‬                 ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34203864 :‬‬\n                   ‫َر ْق ُم الدعوى‪34128028 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n          ‫‪ 34366025‬تاريخه‪1434/11/23:‬هـ‬\n\n\n‫عقــد ‪ -‬إجــارة ‪ -‬مطالبــة بقيمــة حتســينات ‪ -‬األصــل يف الشــروط احلــل‬\n‫‪ -‬مــا يقــوم بــه املســتأجر مــن حتســينات ال تلــزم املؤجــر إذا نــص العقــد‬\n              ‫علــى ذلــك‪ -‬وجــوب الوفــاء بالعقــود ‪ -‬رد دعــوى املدعــى ‪.‬‬\n\n\n\n\n                     ‫‪ -1‬قوله تعالى {يا أيها الذين امنوا أوفوا بالعقود}‪.‬‬\n              ‫‪ -2‬قوله صلى اهلل عليه وسلم ( املسلمون على شروطهم ) ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي ضــد املدعــى عليــه بأنــه اســتأجر مــن املدعــى عليــه بيت ـ ًا‬\n‫شــعبي ًا مرفق ـ ًا بــه ثــاث محــات يف حــي ‪ .......‬بجــدة بأجــرة قدرهــا‬\n‫عشــرون ألــف ريــال وقــام بعمــل حتســينات باحملــل كلفتــه مبلــغ وقــدره‬\n‫خمســة وخمســون ألف ريال وطلب منه املدعى عليه بعدم جتديد العقد‬\n‫ويطالــب بإلزامــه بتعويضــه عــن اخلســارة التــي تكبدهــا يف التحســينات‬\n‫وقدرهــا خمســة وخمســون ألــف ريــال هكــذا ادعــى‪ ،‬أجــاب املدعــى‬\n‫عليــه بإنــكار عمــل التحســينات مــن قبــل املدعــي وأن الــذي قــام بــه هــو‬\n‫عمــل فتحــة واحــدة بــدون علمــه وال إخطار كتابي وأنه ال يســتحق شــيء‬\n‫ويطلــب رد الدعــوى‪ ،‬ليــس للمدعــي بينــة علــى أن املدعــى عليــه يلتــزم‬\n‫بدفــع التعويضــات‪ ،‬أضــاف املدعــى عليــه بــأن املــادة اخلامســة مــن عقــد‬\n\n                                                                                     ‫‪202‬‬\n\f      ‫اإليجــار تنــص ( بــأن ال يحــق للمســتأجر إجــراء أي تغييــر يف الواجهــات‬\n      ‫اخلارجيــة أو الترتيبــات الداخليــة إال بعــد احلصــول علــى موافقــة خطيــة‬\n      ‫مــن املالــك ‪ ...‬كل هــذا بــدون حــق مطالبــة الطــرف الثانــي للطــرف األول‬\n      ‫بــأي تعويــض علمــا بــأن كل اإلصالحــات والتغييــرات التــي ســيوافق‬\n      ‫عليهــا املؤجــر خطيــا تكــون علــى نفقــة املســتأجر بكاملهــا)‪ ،‬بنــاء‬\n      ‫علــى املــادة اخلامســة مــن العقــد املبــرم بــن الطرفــن‪ ،‬ولقولــه تعالــى ‪:‬‬\n      ‫(يــا أيهــا الذيــن امنــوا أوفــوا بالعقــود )‪ ،‬وألن األصــل يف الشــروط احلــل‬\n      ‫ولقولــه صلــى اهلل عليــه وســلم ‪ ( :‬املســلمون علــى شــروطهم )‪ ،‬ملــا تقــدم‬\n      ‫صــدر احلكــم بــرد دعــوى املدعــي لعــدم اســتحقاقه مــا يدعيــه‪ ،‬قنــع‬\n      ‫املدعــى عليــه باحلكــم واعتــرض املدعــي بالئحــة‪ ،‬صــدق احلكــم بعــد‬\n      ‫مداولــة مــن الدائــرة احلقوقيــة الثالثــة مبحكمــة االســتئناف مبنطقــة‬\n                                                                  ‫مكــة املكرمــة‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.......‬القاضــي يف احملكمــة العامــة‬\n      ‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة العامــة مبحافظــة جدة‪/‬املســاعد برقــم ‪ 34128028‬وتاريــخ‬\n      ‫‪1434/03/17‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34617355‬وتاريــخ‬\n      ‫‪1434/03/10‬ه ـ ففــي يــوم األربعــاء املوافق‪1434/05/01‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة ‪ 11 : 30‬وفيهــا حضــر املدعــي أصالــة ‪.......‬ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪.......‬وحضــر حلضــوره املدعــى‬\n      ‫عليــه أصالــة ‪.......‬ســعودي بالســجل رقــم ‪.......‬وبســؤال املدعــي عــن دعــواه‬\n      ‫أفــاد قائــا ‪ :‬لقــد قمــت باســتئجار بيــت شــعبي مــن دوريــن وبــه مرفــق‬\n\n‫‪203‬‬\n\f‫ثــاث محــات مــن املدعــى عليــه ‪.......‬يف حــي ‪.......‬بجــدة مببلــغ وقــدره‬\n‫عشــرون ألــف ريــال وكنــت ملتــزم بااليجــارات وقمــت بعمــل حتســينات‬\n‫يف هــذه احملــات كلفتنــي خمســة وخمســون ألــف ريــال ثــم قــام املدعــى‬\n‫عليــه ‪.......‬وطلــب منــي عــدم جتديــد العقــد أطلــب إلزامــه بتعويضــي عــن‬\n‫اخلســارات التــي تكبدتهــا يف التحســينات وهــي مبلــغ وقــدره خمســة‬\n‫وخمســون ألــف ريــال ودفعهــا لــي هــذه دعــواي وبعرضهــا علــى املدعــى‬\n‫عليــه أجــاب قائــا ‪ :‬مــا ذكــره املدعــي يف دعــواه غيــر صحيــح واملدعــي‬\n‫قــام بعمــل فتحــة واحــدة بــدون علمنــا وال إخطــار كتابــي منــا وعليــه فهــو‬\n‫ال يســتحق شــيئا لــذا أطلــب رد دعــوى املدعــي هكــذا أجــاب ثــم جــرى‬\n‫االطــاع علــى عقــد اإليجــار الــذي بــن الطرفــن فوجــدت البنــد اخلامــس‬\n‫يتضمــن مــا نصــه ‪ :‬ال يحــق للمســتأجر إجــراء أي تغييــر يف الواجهــات‬\n‫اخلارجيــة أو الترتيبــات الداخليــة إال بعــد احلصــول علــى موافقــة خطيــة‬\n‫مــن املالــك أو مــن ينــوب عنــه وإال كان علــى نفقتــه إعــادة املــكان‬\n‫املؤجــر إلــى حالتــه التــي كان عليهــا إمــا فــورا وإمــا عنــد انتهــاء عقــد‬\n‫اإليجــار وتســليم املــكان املؤجــر وهــذا االختيــار حســب رغبــة الطــرف‬\n‫األول ‪ ....‬كل هــذا بــدون حــق مطالبــة الطــرف الثانــي للطرف األول بأي‬\n‫تعويــض علمــا بــأن كل اإلصالحــات والتغييــرات التــي ســيوافق عليهــا‬\n‫املؤجــر خطيــا تكــون علــى نفقــة املســتأجر بكاملهــا أ ‪ .‬ه ـ وبســؤال‬\n‫املدعــي عــن بينتــه علــى أن املدعــى عليــه قــد التــزم بتعويضــه عمــا قــام‬\n‫بــه مــن إصالحــات أجــاب قائــا ‪ :‬ال بينــة لــدي علــى ذلــك هكــذا أجــاب‬\n‫وبعرضــه علــى املدعــى عليــه أجــاب قائــا ‪ :‬إن املــادة اخلامســة مــن العقــد‬\n‫تضمنــت مــا نصــه‪ ( :‬كل هــذا بــدون حــق مطالبــة الطــرف الثانــي‬\n‫للطــرف األول بــأي تعويــض علمــا بــأن كل االصالحــات والتغييــرات‬\n\n\n                                                                                     ‫‪204‬‬\n\f      ‫التــي ســيوافق عليهــا املؤجــر خطيــا تكــون علــى نفقــة املســتأجر‬\n      ‫بكاملهــا ) وقــد حاولــت الصلــح بــن الطرفــن فأصــر املدعــى عليــه على‬\n      ‫رفضــه عليــه فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة ومبــا أن املدعــي‬\n      ‫حصــر دعــواه يف املطالبــة بتعويضــه عمــا قــام بــه مــن حتســينات وذلــك‬\n      ‫مببلــغ وقــدره خمســة وخمســون ألــف ريــال ومبــا أن املدعــى عليــه أنكــر‬\n      ‫دعــوى املدعــي جملــة وتفصيــا ومبــا أن العقــد الــذي بــن الطرفــن‬\n      ‫قــد نــص كمــا يف املــادة اخلامســة منــه (كل هــذا بــدون حــق مطالبــة‬\n      ‫الطــرف الثانــي للطــرف األول بــأي تعويــض علمــا بــأن كل االصالحــات‬\n      ‫والتغييــرات التــي ســيوافق عليهــا املؤجــر خطيــا تكــون علــى نفقــة‬\n      ‫املســتأجر بكاملهــا) ولقولــه تعالــى ‪( :‬يــا أيهــا الذيــن أمنــوا أوفــوا‬\n      ‫بالعقــود ) اآليــة وألن األصــل يف الشــروط احلــل ولقولــه صلــى اهلل عليــه‬\n      ‫وســلم ‪ ( :‬املســلمون علــى شــروطهم) وجلميــع مــا تقــدم فقــد حكمــت بــرد‬\n      ‫دعــوى املدعــي لعــدم اســتحقاقه مــا يدعيــه وبعرضــه علــى الطرفــن قــرر‬\n      ‫املدعــى عليــه القناعــة وقــرر املدعــي عــدم القناعــة وطلــب االســتئناف‬\n      ‫فأجيــب إلــى طلبــه وجــرى تســليمه نســخة مــن احلكــم لالعتــراض عليــه‬\n      ‫خــال ثالثــن يومــا تبــدأ مــن تاريــخ احلكــم وإذا انتهــت مــدة االعتــراض‬\n      ‫ولــم يتقــدم بالالئحــة االعتراضيــة فيســقط حقــه يف طلــب االســتئناف‬\n      ‫ويكتســب احلكــم القطعيــة وأغلقــت اجللســة الســاعة ‪ 12 : 00‬وبــاهلل‬\n      ‫التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر‬\n                                                               ‫يف ‪1434/05/01‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.......‬القاضــي يف احملكمــة العامــة‬\n      ‫مبحافظــة جــدة ففــي يــوم األحــد املوافق‪1434/10/25‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة ‪ 08 : 30‬وفيهــا حضــر املدعــي أصالــة ‪.......‬املدونــة هويتــه‬\n\n\n‫‪205‬‬\n\f‫ســابقا ولــم يحضــر املدعــى عليــه ‪.......‬ولــم يردنــا مــا يفيــد تبلغــه وقــد‬\n‫عــادت لنــا املعاملــة مــن محكمــة االســتئناف مبكــة املكرمــة بخطــاب‬\n‫فضيلــة رئيســها رقــم ‪ 34617355‬وتاريــخ ‪1434/06/18‬ه ـ واملتضمنــة‬\n‫القــرار الصــادر مــن الدائــرة احلقوقيــة الثالثــة يف محكمــة االســتئناف‬\n‫برقــم ‪ 34237805‬وتاريــخ ‪1434/06/12‬ه ـ والــذي نصــه بعــد املقدمــة‪:‬‬\n‫( وبدراســة احلكــم وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر إعادتهــا‬\n‫لفضيلتــه ملالحظــة أنــه ذكــر يف الالئحــة مــا يوجــب فتــح جلســة‬\n‫والتأكــد منــه وهــو وجــود موافقــة خطيــة فهــل هــذا ثابــت ‪ ..‬إلــخ وإجــراء‬\n‫املقتضــى الشــرعي نحــوه وبــاهلل التوفيــق قاضــي اســتئناف ‪ .......‬توقيــع‬\n‫وقاضــي اســتئناف ‪.......‬توقيــع ورئيــس الدائــرة صقــر املــدرع توقيــع) أ ‪ .‬هـ‬\n‫وعليــه أجيــب أصحــاب الفضيلــة وفقهــم اهلل لطاعتــه وهداهــم ملرضاتــه‬\n‫أنــه بســؤال املدعــي مــن املوافقــة اخلطيــة التــي ذكرهــا أجــاب قائــا ‪:‬‬\n‫إن بينتــي هــي مــا ورد يف اخلطــاب الصــادر مــن املدعــى عليــه ‪.......‬بتاريــخ‬\n‫‪1433/11/23‬هـ ونصه ‪ ( :‬اتعهد أنا ‪ ....‬مبساعدة السيد ‪.......‬ومتكينه‬\n‫مــن حتصيــل جميــع إيجاراتــه املتبقيــة لــدى ســكان بيــت عمتــي ‪.......‬يف‬\n‫حــي ‪.......‬واعطــاءه مهلــة إلــى آخــر شــهر محــرم ‪ 1434‬الســتالم البيــت‬\n‫منــه ومــن حــق ‪.......‬اغــاق احمللــن الــذي اســتحدثهم يف البيــت وهــذا‬\n‫تعهــد منــا بذلــك ‪.......‬توقيــع) أ ‪ .‬ه ـ وبســؤاله هــل لديــك بينــة أخــرى أجاب‬\n‫قائــا ‪ :‬ال ليــس لــدي بينــة أخــرى وباالطــاع علــى هــذا اخلطــاب لــم أجــد‬\n‫فيــه مــا يــدل علــى إذن املدعــى عليــه للمدعــي باســتحداث احمللــن اللذين‬\n‫يطالــب املدعــي بالتعويــض عــن اخلســائر التــي تكبدهــا وعليــه فلــم أجــد‬\n‫تأثيــرا علــى مــا حكمــت بــه ســابقا أمــرت باحلــاق ذلــك علــى صكــه‬\n‫وســجله وإعادتــه إلــى محكمــة االســتئناف وأغلقــت اجللســة الســاعة ‪00‬‬\n\n\n                                                                                       ‫‪206‬‬\n\f      ‫‪ 09 :‬وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                  ‫وســلم ‪ .‬حــرر يف ‪1434/10/25‬ه ـ ‪.‬‬\n      ‫احلمد هلل ‪ ،‬والصالة والسالم على رسول اهلل ‪ ،‬وبعد ‪ :‬ـ فقـد جـرى م ّنا‬\n      ‫نح ــن رئيس وأعضاء الدائ ــرة احلقوقي ــة الثالثة يف محكم ــة االستئناف‬\n      ‫مبنطقــة مك ــة املكرم ــة االطــا ُع عل ــى ه ــذا الصــك الص ــادر مــن‬\n      ‫فضي ــلة الشــيخ ‪.......‬القاضــي باحملكمــة العامــة بجــدة املســجل بعــدد‬\n      ‫‪.......‬وتاريــخ ‪1434/05/01‬ه ـ املتضمــن دعــوى ‪ .......‬ضــد ‪.......‬يف مبلــغ‬\n      ‫مالــي احملكــوم فيــه مبــا دون باطنــه وبــدراس ــة احلكــم وصــورة ضبطــه‬\n      ‫والئحتــه االعتراضيــة تقـ ـ ـ ـ ــررت املـ ــوافقـ ـ ـ ــة علــى احلكــم بعــد اإلجــراء‬\n      ‫االخيــر وبــاهلل تعالــى التوفيــق وصل ــى اهلل عل ــى نبي ــنا محم ــد وعل ــى آل ــه‬\n                                                                              ‫وصحب ــه وسـلم ‪.‬‬\n\n\n\n\n‫‪207‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"612f1ba9-3f27-52bc-993f-69d3ecdc8564","source_page_start":202,"source_page_end":207,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d210023f9b795ea67e47c2da7760b94e9151f3e31f45d7553640f1bd37aa1b51","normalized_text_hash":"b7c061ea6be4db1d321352c88cb81b2b8dc3c2e262a4bf922d8830ead604c103","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v7-p202-34203864"},{"id":"69eb2376-4810-576f-a363-3c1118a50f6c","document_type":"judgment","category":"judicial","subcategory":"general","title":"إجارة -املطالبة بتنفيذ العقد -انتقال العن من مالك آلخر ال يلغي العقود املتعلقة بالعن -وجوب الوفاء بالعقود -شراء العن ال يسري على املنفعة إال بعد انتهاء مدة عقد اإليجار -احلكم بتسليم العن حتى نهاية مدة العقد .","document_number":"34191964","case_number":"34152805","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة الرس","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/20","year":"1434","subject":"إجارة -املطالبة بتنفيذ العقد -انتقال العن من مالك آلخر ال يلغي العقود املتعلقة بالعن -وجوب الوفاء بالعقود -شراء العن ال يسري على املنفعة إال بعد انتهاء مدة عقد اإليجار -احلكم بتسليم العن حتى نهاية مدة العقد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/4/20 :‬هـ‬\n                 ‫ُ‬                 ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪34191964 :‬‬\n                    ‫َر ْق ُم الدعوى‪34152805 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n            ‫‪ 34219690‬تاريخه‪1434/5/22:‬هـ‬\n\n\n‫إجــارة ‪ -‬املطالبــة بتنفيــذ العقــد ‪ -‬انتقــال العــن مــن مالــك آلخــر ال‬\n‫يلغــي العقــود املتعلقــة بالعــن ‪ -‬وجــوب الوفــاء بالعقــود ‪ -‬شــراء العــن‬\n‫ال يســري علــى املنفعــة إال بعــد انتهــاء مــدة عقــد اإليجــار ‪ -‬احلكــم‬\n                                ‫بتســليم العــن حتــى نهايــة مــدة العقــد ‪.‬‬\n\n\n\n\n                             ‫قوله تعالى {يا أيها الذين آمنوا أوفوا بالعقود}‪.‬‬\n\n\n\n\n‫ا جتاريـ ًا‬\n          ‫ادعــى املدعــي ضــد املدعــى عليــه بأنــه اســتأجر مــن املالــك محـ ً‬\n‫علــى طريــق ‪ ...........‬مقابــل ‪ ...‬علــى أن يبــدأ اإليجار بتاريخ ‪1432/4/1‬هـ‬\n‫وينتهــي يف ‪1435/4/1‬ه ـ بقيمــة ثمانيــة آالف للســنة الواحــدة وقــد قــام‬\n‫املدعــى عليــه يف يــوم األحــد املوافــق ‪1434/3/29‬ه ـ وقبــل أن يحــل‬\n‫اإليجــار بيــوم واحــد بالتهجــم علــى احملــل وأخبــره العامــل بــأن املدعــى‬\n‫عليــه يقــول‪ :‬عليــك أن تدفــع واحــد ًا وعشــرين ألــف ريــال بــدل املتفــق‬\n‫عليــه بالعقــد أو يطلــب منــه اخلــروج مــن احملــل وبعــد عــدة ســاعات أتــى‬\n‫للمحــل وأقفلــه بقفــل حديــدي ويطلــب إلــزام املدعــى عليــه بتنفيــذ موجب‬\n‫العقــد املبــرم بينهمــا هكــذا ادعــى‪ ،‬أجــاب املدعــى عليــه باملصادقــة‬\n‫علــى الدعــوى وأنــه اشــترى الــدكان مــن املالــك األصلــي يف شــهر‬\n\n                                                                                     ‫‪208‬‬\n\f      ‫جمــادى اآلخــرة مــن الســنة املاضيــة‪ ،‬وحيــث صــادق املدعــى عليــه علــى‬\n      ‫دعــوى املدعــي وبعــد االطــاع علــى أصــل عقــد الــدكان وأصــل صــك‬\n      ‫ملكيــة العقــار وحيــث أن انتقــال العــن مــن مالــك آلخــر ال يلغــي العقــود‬\n      ‫املتعلقــة بالعــن حيــث أن املســتأجر ميلــك منفعــة الــدكان حتــى نهايــة‬\n      ‫العقــد لقولــه تعالــى ( يــا أيهــا الذيــن آمنــو أوفــوا بالعقــود) وألن شــراء‬\n      ‫املدعــى عليــه وقــع علــى ذات العــن ولــم يقــع علــى منفعتهــا النشــغالها‬\n      ‫بعقــد ســابق فــا يســري علــى املنفعــة إال بعــد انتهــاء عقــد اإليجــار‪ ،‬ملــا‬\n      ‫تقــدم صــدر احلكــم علــى املدعــى عليــه بــأن يســلم الــدكان للمدعــي‬\n      ‫حتــى نهايــة العقــد املذكــور يف الدعــوى يف ‪1435/4/1‬ه ـ ‪ -‬قنــع املدعي‬\n      ‫باحلكــم واعتــرض املدعــى عليــه بالئحــة‪ ،‬صــدق احلكــم مــن الدائــرة‬\n                     ‫احلقوقيــة األولــى مبحكمــة االســتئناف مبنطقــة القصيــم ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.......‬القاضــي يف احملكمــة العامــة‬\n      ‫مبحافظــة الــرس وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة العامــة مبحافظــة الــرس برقــم ‪ 34152805‬وتاريــخ‬\n      ‫‪ 1434/04/03‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34813522‬وتاريــخ‬\n      ‫‪ 1434/04/03‬ه ـ ففــي يــوم األربعــاء املوافق‪ 1434/04/17‬هـ افتتحت‬\n      ‫اجللســة الســاعة ‪ 08 : 00‬وفيهــا حضــر ‪.......‬ســعودي اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم ‪.......‬وحضــر حلضــوره ‪.......‬ســعودي بالســجل رقــم‬\n      ‫ال جتاري ًا‬\n               ‫‪.......‬وادعــى االول قائــا اســتأجرت مــن املالك الســابق ‪.......‬مح ً‬\n      ‫علــى طريــق ‪ ...........‬املدينــة ســابقا مقابــل بــرج ‪.......‬بالعقــد الصــادر مــن‬\n      ‫مكتــب ‪.......‬بتاريــخ ‪1432/1/20‬ه ـ علــى ان يبــدأ االيجــار بتاريــخ‬\n\n‫‪209‬‬\n\f‫‪1432/4/1‬ه ـ وينتهــي يف ‪1435/4/1‬ه ـ بقيمــة ثمانيــة االف للســنة‬\n‫الواحــدة وقــد قــام املدعــى عليــه يف يــوم االحــد املوافــق ‪1434/3/29‬ه ـ‬\n‫وقبــل ان يحــل االيجــار بيــوم واحــد بالتهجــم علــى احملــل وابلغنــي العامــل‬\n‫ان املدعــى عليــه يقــول ‪ :‬ان عليــك ان تدفــع واحــدا وعشــرين الــف ريــال‬\n‫بــدل املتفــق عليــه بالعقــد او يطلــب منــي اخلــروج مــن احملــل وبعــد عــدة‬\n‫ســاعات اتــى للمحــل واقفلــه بقفــل حديــدي ويف نفــس اليــوم مت ابــاغ‬\n‫شــرطة الــرس بذلــك وحضــر البحــث اجلنائــي ومت رصــد الواقعــة لديهــم‬\n‫بالصــور اطلــب الــزام املدعــى عليــه بتنفيــذ موجــب العقــد املبــرم بيننــا‬\n‫هــذه دعــواي هكــذا ادعــى وبعــرض دعــوى املدعــي علــى املدعــى عليــه‬\n‫اجــاب قائــا ماذكــره املدعــي مــن اســتئجار الــدكان الواقــع يف شــارع‬\n‫امللك ‪.......‬مقابل مؤسســة ‪ ...‬من تاريخ ‪1432/4/1‬هـ الى ‪1435/4/1‬هـ‬\n‫كمــا جــاء بالعقــد املرفــق رقــم ‪ 1426‬يف ‪1432/1/20‬ه ـ كلــه صحيــح‬\n‫وقــد اشــتريت الــدكان مــن املالــك االصلــي يف شــهر جمــادى االخــرة مــن‬\n‫الســنة املاضيــة مــن املســمى ‪.......‬وقــد اغلقــت بــاب الــدكان ألن اســعار‬\n‫االيجــارات مرتفعــة فقلــت لــه إمــا ان يكــون االيجــار واحــدا وعشــرين‬\n‫الــف ريــال او تخــرج مــن الــدكان هــذه اجابتــي هكــذا اجــاب فبناء على‬\n‫ماتقــدم مــن الدعــوى واالجابــة وحيــث صــادق املدعــى عليــه علــى دعــوى‬\n‫املدعــي وبعــد االطــاع علــى اصــل عقــد الــدكان املتضمــن (مت االتفــاق‬\n‫بــن الطرفــن ‪.......‬طــرف اول و‪.......‬طــرف ثانــي ان يســتأجر الطــرف‬\n‫الثانــي ورشــة ‪ ...‬الشــارع ‪........‬مقابــل بــرج ‪ ...‬مــدة االيجــار ثــاث ســنوات‬\n‫بــدا مــن تاريــخ ‪1432/4/1‬ه ـ حتــى ‪1435/4/1‬ه ـ االيجــار الســنوي‬\n‫‪ 8000‬ريــال ســعودي ) ورخصــة احملــل املتضمنــة ( رقــم الرخصــة ‪.......‬‬\n‫يف ‪1420/1/5‬ه ـ وتنتهــي يف ‪1435/1/5‬ه ـ اســم صاحب الرخصة ‪.......‬‬\n\n\n                                                                                       ‫‪210‬‬\n\f      ‫االســم التجــاري محــل ‪ )....... .......‬وباالطــاع علــى أصــل صــك ملكيــة‬\n      ‫العقــار رقــم ‪ 93‬وتاريــخ ‪1433/5/15‬ه ـ املتضمــن (حضــر علــي ‪.......‬‬\n      ‫اصيــا عــن نفســه ووكالــة عــن ورثــة والــده وقــرر بطوعــه واختيــاره‬\n      ‫انــه اجلــاري يف ملكــي وحتــت تصــريف الــدكان رقــم ‪ 3‬الواقــع باجلهــة‬\n      ‫الغربيــة مــن محافظــة الــرس وقــد بعتــه ‪.‬ل‪ )......‬ومت االستفســار عــن‬\n      ‫ســريان مفعولــه برقــم ‪ 34952827‬وتاريــخ ‪1434/4/17‬ه ـ تبــن انــه‬\n      ‫الصــك ســاري املفعــول والتوجــد عليــه مالحظــات وكذلــك الصــك رقــم‬\n      ‫‪ 94‬يف ‪1433/5/15‬ه ـ املتضمــن (حضــر ‪.......‬اصيــا عن نفســه ووكالة‬\n      ‫عــن ورثــة والــده وقــرر بطوعــه واختيــاره انــه اجلــاري يف ملكــي وحتــت‬\n      ‫تصــريف الــدكان رقــم ‪ 2‬الواقــع باجلهــة الغربيــة مــن محافظــة الــرس وقــد‬\n      ‫بعتــه ل‪ ).......‬ومت االستفســار عــن ســريان مفعولــه برقــم ‪349527777‬‬\n      ‫يف ‪1434/4/17‬ه ـ تبــن انــه الصــك ســاري املفعــول والتوجــد عليــه‬\n      ‫مالحظــات وحيــث ان انتقــال العــن مــن مالــك آلخــر اليلغــي العقــود‬\n      ‫املتعلقــة بالعــن حيــث ان املســتأجر ميلــك منفعــة الــدكان حتــى نهايــة‬\n      ‫العقــد لقولــه تعالــى ( ياأيهــا الذيــن امنــو اوفــوا بالعقــود ) وألن شــراء‬\n      ‫املدعــى عليــه وقــع علــى ذات العــن ولــم يقــع علــى منفعتهــا إلنشــغالها‬\n      ‫بعقــد ســابق فاليســري علــى املنفعــة اال بعــد انتهــاء عقد االيجــار لذا فقد‬\n      ‫حكمــت علــى املدعــى عليــه بــأن يســلم الــدكان للمدعــي حتــى نهايــة‬\n      ‫العقــد املذكــور يف الدعــوى يف ‪1435/4/1‬ه ـ وبعــرض ماحكمــت بــه‬\n      ‫علــى الطرفــن قــرر املدعــي قناعتــه باحلكــم وقــرر املدعــى عليــه عــدم‬\n      ‫القناعة وافهمته بأن يحضر يف يوم الســبت الســتالم نســخة من احلكم‬\n      ‫لتقــدمي الالئحــة االعتراضيــة ففهــم ذلــك وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n      ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/04/17‬هـ‬\n\n\n‫‪211‬‬\n\f‫احلمــد هلل وحــده والصــاة والســام علــى نبينــا محمــد وعلــى آلــه‬\n‫وصحبــه وبعــد‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة احلقوقيــة األولــى‬\n‫مبحكمــة االســتئناف مبنطقــة القصيــم علــى املعاملــة الــواردة مــن‬\n‫فضيلــة رئيــس احملكمــة العامــة مبحافظــة الــرس برقــم(‪)34813522‬‬\n‫وتاريــخ ‪1434/5/6‬ه ـ ؛ احملالــة إلينــا برقــم (‪ )34214668‬؛ املرفــق بهــا‬\n‫الصــك املســجل برقــم(‪ ).......‬وتاريــخ ‪1434/4/20‬ه ـ ؛ الصــادر مــن‬\n‫فضيلــة الشــيخ‪......./‬القاضي باحملكمــة؛ اخلــاص بدعــوى ‪.......‬ضــد‬\n‫‪ ........‬بشــأن تنفيــذ عقــد مبــرم حملــل عقــار ‪ .‬وقــد تضمــن الصــك حكــم‬\n‫فضيلتــه بــأن علــى املدعــى عليــه أن يســلم الــدكان للمدعــي حتــى نهايــة‬\n‫العقــد املذكــور يف الدعــوى يف‪1435/4/1‬ه ـ ‪ .‬علــى النحــو املفصــل‬\n‫فيــه‪ .‬وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق‬\n‫املعاملــة نقــرر املصادقــة علــى احلكــم اهلل املوفــق‪ ،‬وصلــى اهلل وســلم‬\n                                    ‫علــى نبينــا محمــد وآلــه وصحبــه وســلم‪.‬‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.......‬القاضــي يف احملكمــة‬\n‫العامــة مبحافظــة الــرس وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n‫رئيــس احملكمــة العامــة مبحافظــة الــرس برقــم ‪34152805‬‬\n‫وتاريــخ ‪1434/04/03‬ه ـ املقيــدة باحملكمــة برقــم ‪34813522‬‬\n‫وتاريــخ ‪1434/04/03‬ه ـ ‪.......‬ضــد ‪ .......‬ففــي يــوم اخلميــس‬\n‫املوافق‪1434/10/15‬ه ـ افتتحــت اجللســة الســاعة ‪ 10.15‬وفيهــا وردت‬\n‫املعاملــة مــن رئيــس دائــرة التنفيــذ باحملكمــة العامــة مبحافظــة الــرس‬\n‫برقــم ‪342110908‬يف ‪1434/9/2‬ه ـ واملتضمــن اســتالم املدعــي‬\n‫الــدكان املطالــب بــه والصــادر بــه الصــك الشــرعي رقــم ‪34191964‬‬\n‫يف ‪1434/4 /20‬ه ـ وبهــذا ليــس للمدعــي اي شــئ بخصــوص هــذه‬\n\n\n                                                                                  ‫‪212‬‬\n\f      ‫القضيــة وامــرت بالتهميــش علــى ضبطــه وســجله حتــى ال يخفــى وبــاهلل‬\n      ‫التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر‬\n                                                             ‫يف ‪ 1434/10/15‬ه ـ‬\n\n\n\n\n‫‪213‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"612f1ba9-3f27-52bc-993f-69d3ecdc8564","source_page_start":208,"source_page_end":213,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"2bc3c6dc4472fc1f347bd72bc80f14ff4e12479e5287289cd302f53b725e7dab","normalized_text_hash":"c35bef4e573ee2adacba31033d979e3764f09ef12dc6fb24033725b71e9778f8","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v7-p208-34191964"},{"id":"794bcb94-f800-51b9-973b-b525ec3b0aea","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقد -اجاره -مطالبه بأجره مدة بقاء املستأجر بعد انتهاء العقد- مطالبه بالتعويض عن التأخير يف اخاء املبنى -تقدير األجرة عن طريق قسم اخلبراء -الضرر املضمون هو الضرر الواقع فقط وليس الضرر املتوقع -احلكم بسداد قيمة األجرة املستحقة -عدم استحقاق التعويض قال البهوتي يف شرح املنتهى ( 122/4وال يضمن ربح فات على مالك بحبس غاصب مال جتارة مدة ميكن أن يتجر فيها إذا لم","document_number":"34300352","case_number":"34154268","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/8/17","year":"1434","subject":"عقد -اجاره -مطالبه بأجره مدة بقاء املستأجر بعد انتهاء العقد- مطالبه بالتعويض عن التأخير يف اخاء املبنى -تقدير األجرة عن طريق قسم اخلبراء -الضرر املضمون هو الضرر الواقع فقط وليس الضرر املتوقع -احلكم بسداد قيمة األجرة املستحقة -عدم استحقاق التعويض قال البهوتي يف شرح املنتهى ( 122/4وال يضمن ربح فات على مالك بحبس غاصب مال جتارة مدة ميكن أن يتجر فيها إذا لم","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/8/17 :‬هـ‬\n                ‫ُ‬                  ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪34300352 :‬‬\n                    ‫َر ْق ُم الدعوى‪34154268 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34346377‬تاريخه‪1434/11/2 :‬هـ‬\n\n\n‫عقــد ‪ -‬اجــاره ‪ -‬مطالبــه بأجــره مــدة بقــاء املســتأجر بعــد انتهــاء العقد‪-‬‬\n‫مطالبــه بالتعويــض عــن التأخيــر يف اخــاء املبنــى ‪ -‬تقديــر األجــرة‬\n‫عــن طريــق قســم اخلبــراء ‪ -‬الضــرر املضمــون هــو الضــرر الواقــع فقــط‬\n‫وليــس الضــرر املتوقــع ‪ -‬احلكــم بســداد قيمــة األجــرة املســتحقة ‪ -‬عــدم‬\n                                                          ‫اســتحقاق التعويــض‬\n\n\n\n\n‫قــال البهوتــي يف شــرح املنتهــى ‪( 122/4‬وال يضمــن ربــح فــات علــى‬\n‫مالــك بحبــس غاصــب مــال جتــارة مــدة ميكــن أن يتجــر فيهــا إذا لــم‬\n     ‫يتجــر فيــه الغاصــب) وينظــر شــرح املنتهــى البــن النجــار ‪215/5‬‬\n\n\n\n\n‫ادعــى املدعــي وكالــة ضــد املدعــى عليــه مبطالبتــه باألجــرة والتعويــض‬\n‫عــن الضــرر لتأخــره يف إخــاء املبنــى ‪ -‬حيــث اســتأجر املدعــى عليــه‬\n‫املبنــى ملــدة ســنة تنتهــي يف ‪1432/12/30‬ه ـ ومت جتديــد العقــد ملــدة‬\n‫ســتة أشــهر تنتهــي يف ‪1433/6/30‬ه ثــم بــاع املالــك علــى املدعــي املبنــى‬\n‫وقبــل نهايــة الســتة أشــهر طلــب املدعــي مــن املدعــى عليــه إخــاء املبنــى‬\n‫بنهايــة الســتة أشــهر ولكــن املدعــى عليــه لــم يخلــه وأكمــل حتــى‬\n‫‪1433/12/18‬ه ـ يطالــب املدعــي بأجــرة قدرهــا أربعمائــة وخمســون‬\n\n                                                                                    ‫‪214‬‬\n\f      ‫ألــف ريــال وتعويــض عــن الضــرر يف التأخــر عــن إخــاء املبنــى مببلــغ‬\n      ‫قــدره مليــون وخمســمائة وخمســون ألــف ريــال وذلــك ألن موكلــه أراد‬\n      ‫هــدم املبنــى وبنــاء فنــدق لتأجيــره يف حــج عــام ‪1434‬ه ـ ‪ ،‬أجــاب املدعــى‬\n      ‫عليــه وكالــة باملصادقــة علــى عقــد اإليجــار ومتديــد العقــد ملــدة ســنة‬\n      ‫وليــس ســتة أشــهر وأن املالــك الســابق اســتلم أجــرة الســتة أشــهر وأن‬\n      ‫موكلــه تلقــى خطاب ـ ًا مــن املالــك األول ببيــع العقــار وتنبيهــه باإلخــاء‬\n      ‫بعــد نهايــة الســتة أشــهر وأن مديــر معــرض موكلــه تلقــى فاكــس‬\n      ‫مــن املالــك اجلديــد يطلــب فيــه اإلخــاء وأن ليــس للمدعــي ســوى مبلــغ‬\n      ‫مائتــن وخمســة وعشــرون ألــف ريــال املتبقــي مــن أجــرة الســتة أشــهر‬\n      ‫للســنة الثانيــة وان التعويــض يف الشــريعة يكــون عــن ضــرر مالــي واقــع‬\n      ‫كمــا أن اخلطــأ منتفــي عــن موكلــه فقــد انتفــع بالعــن حتــى نهايــة‬\n      ‫املــدة احملــددة هكــذا أجــاب‪ ،‬عقــد اإليجــار بــن املالــك األول واملدعــى‬\n      ‫عليــه ملــدة ســنة ولــم يذكــر فيــه جتــدد العقــد تلقائي ـاً‪ ،‬رخصــة البنــاء‬\n      ‫لــم تصــدر إال بتاريــخ ‪1434/3/25‬ه ـ مت تقديــر األجــرة عــن طريــق‬\n      ‫قســم اخلبــراء بانهــا مبلــغ أربعمائــة وثمانــون ألــف ريــال لــم يقنــع املدعــى‬\n      ‫عليــه وكالــة بالتقديــر‪ ،‬وأمــا املدعــي وكالــة فقــرر مبطالبتــه مببلــغ‬\n      ‫أربعمائــة وخمســن ألــف ريــال دون مــا قدرتــه هيئــة النظــر ‪ ،‬وألن هــذا‬\n      ‫العقــد نــص علــى أن مــدة العقــد ســنه واحــدة وهــي لعــام ‪1432‬ه ـ فقــط‬\n      ‫دون اإلشــارة إلــى جتــدده تلقائيــا وحيــث جــرى إبــاغ البائــع للمدعــى‬\n      ‫عليــه بالبيــع وإمهالــه للخــروج حتــى ‪1433/6/30‬ه ـ كمــا تضمــن أيضــا‬\n      ‫الســند املوقــع مــن البائــع باســتالم األجــرة أن هــذه األجــرة للمــدة مــن‬\n      ‫‪1432/1/1‬ه ـ حتــى ‪1433/6/30‬ه ـ فقــط وكذلــك مطالبــة املشــتري‬\n      ‫للمدعــى عليــه باخلــروج بعــد انتهــاء املــدة وألن املدعــي أصالــة قــدر أجــرة‬\n\n\n‫‪215‬‬\n\f‫املــدة مــن ‪1433/7/1‬ه ـ بأربعمائــة وخمســن ألــف ريــال وطالــب بهــذا‬\n‫املبلــغ وهــو أقــل ممــا قدرتــه هيئــة النظــر كمــا طالــب بتعويضــه عــن‬\n‫التأخيــر يف هــدم املوقــع وبنــاء عمــارة عليــه وتأجيرهــا ملوســم احلــج لهــذا‬\n‫العــام ‪1434‬ه ـ وألن الضــرر املضمــون هــو الضــرر الواقــع أمــا الربــح‬\n‫الفائــت والضــرر غيــر املتوقــع فهــو غيــر مضمــون كمــا قــرر ذلــك أهــل‬\n‫العلــم ينظــر شــرح املنتهــى ‪ ،122/4‬صــدر احلكــم بإلــزام املدعــى عليــه‬\n‫بدفــع أجــرة املــدة مــن ‪1433/7/1‬ه ـ حتــى تاريــخ اإلخــاء مبلــغ وقــدره‬\n‫أربعمائــة وخمســون ألــف ريــال وعــدم اســتحقاق املدعــي للتعويــض الــذي‬\n‫يطالــب بــه ‪ ،‬اعتــرض الطرفــان بالئحــة ‪ ،‬صــدق احلكــم مــن الدائــرة‬\n     ‫احلقوقيــة الثالثــة مبحكمــة االســتئناف مبنطقــة مكــة املكرمــة‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .......‬القاضــي باحملكمــة العامــة‬\n‫مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة مبكــة املكرمــة املقيــدة باحملكمــة برقــم‬\n‫‪ 34821159‬وتاريــخ ‪1434/04/03‬ه ـ وفيهــا حضــر املدعــي وكالــة‬\n‫‪.......‬ســجل مدنــي رقــم ‪ .......‬بوكالتــه عــن ‪.......‬بصفتــه الوكيــل‬\n‫الشــرعي عــن أخيــه ‪.......‬بالوكالــة الصــادرة مــن كتابــة عــدل بريــدة‬\n‫الثانيــة برقــم ‪ 5681/43997‬يف ‪1433/8/17‬ه ـ والتــي تخولــه املطالبــة‬\n‫واملداعــاة واملخاصمــة وســماع الدعــاوي والــرد عليهــا ‪..‬الــخ كمــا حضــر‬\n‫‪.......‬ســجل مدنــي رقــم ‪.......‬بوكالتــه عــن أوالد ‪.......‬بصفتهــم شــركاء‬\n‫يف شــركة ‪.......‬وشــركاه بالوكالــة الصــادرة مــن كتابــة عــدل الثانيــة‬\n‫بجنــوب الريــاض برقــم ‪ 2617/4779‬يف ‪1430/1/16‬ه ـ والتــي تخولــه‬\n\n                                                                                      ‫‪216‬‬\n\f      ‫املرافعــة واملدافعــة ‪..‬الــخ قائــا يف دعــواه عليــه بتاريــخ ‪1433/3/1‬ه ـ‬\n      ‫اشــترى موكلــي العقــار الواقــع بالعزيزيــة علــى طريــق الطائــف الهــدا‬\n      ‫احملــدود واملــذروع مبوجــب الصــك الصــادر مــن كتابــة العــدل مبكــة‬\n      ‫املكرمــة برقــم ‪/106‬أ يف ‪1400/3/17‬ه ـ وكان مؤجــرا مــن املالــك‬\n      ‫الســابق علــى شــركة ‪.......‬وشــركاه (‪ ).......‬وعقــد االيجــار يتنهــي يف‬\n      ‫‪1433/6/30‬ه ـ وقــد مت ابــاغ الشــركة باإلخــاء يف ذلــك التاريــخ‬\n      ‫بواســطة مديــر فــرع الشــركة مبكــة املكرمــة ‪.......‬ووقــع خطابــا‬\n      ‫بالتــزام الشــركة باإلخــاء يف املوعــد احملــدد ولكــن الشــركة لــم‬\n      ‫تخــل املوقــع وبقيــت فيــه حتــى ‪1433/12/18‬ه ـ فأطلــب الــزام الشــركة‬\n      ‫بدفــع اجــرة املــدة مــن ‪1433/7/1‬ه ـ حتــى ‪1433/12/3‬ه ـ وقدرهــا‬\n      ‫أربعمائــة وخمســون الــف ريــال كمــا أنــه بســبب تأخــر الشــركة يف‬\n      ‫االخــاء أدى ذلــك الــى ضــرر موكلــي فلــم يبــدأ بهــدم املوقــع واعــادة‬\n      ‫بنائــه وكان مــن املقــرر أنــه ســيبدأ بالهــدم فــور االخــاء ومــن ثــم بنــاء‬\n      ‫فندقــا يؤجــر يف حــج هــذا العــام ‪1434‬ه ـ وتأخــر الشــركة يف االخــاء‬\n      ‫ادى الــى فــوات ذلــك علــى موكلــي وموكلــي يطلــب الــزام الشــركة‬\n      ‫بدفــع مليــون وخمســمائه وخمســن مقابــل هــذا الضــرر هــذه دعــواي‬\n      ‫وبســؤال املدعــي عليــه وكالــه عــن دعــوى املدعــي وكالــه اجــاب بورقــه‬\n      ‫هــذا نصهــا ‪ -:‬أتقــدم لفضيلتكــم مبذكــرة الــرد علــى دعــوى املدعــي‬\n                            ‫‪.......‬بالوكالــة عــن ‪ .......‬والــذي يطلــب مبقتضاهــا‪:‬‬\n      ‫‪ .1‬أجــرة املــدة مــن ‪1433/7/1‬ه ـ وحتــى ‪1433/12/30‬ه ـ وقدرهــا‬\n                                                   ‫أربعمائــة وخمســون ألــف ريــال‪.‬‬\n      ‫‪ .2‬تعويضــه عــن التأخيــر يف إخــاء املبنــى وبالتالــي تأخــر هــدم املعــرض‬\n      ‫وبنائــه فنــدق وتأجيــره يف حــج عــام ‪1434‬ه ـ ممــا فـ ّـوت عليــه مبلــغ مليــون‬\n\n\n‫‪217‬‬\n\f‫وخمســمائة وخمســون ألــف ريــال ‪ .‬الوقائــع والدفــاع ‪ -:‬مبوجــب عقــد‬\n‫إيجــار محــرر يف ‪1432/1/1‬ه ـ جــدد ورثــة ‪ .......‬مــرزا إجــارة املعــرض‬\n‫العائــد ملورثهــم إلــى شــركة مجموعــة ‪ .......‬لســنة أخــرى تنتهــي يف‬\n‫‪1432/12/30‬ه ـ وبأجــرة ســنوية مقدارهــا (‪ )450.000‬أربعمائــة‬\n                                     ‫وخمســون ألــف ريــال (مســتند رقــم ‪. )1‬‬\n‫‪ .3‬وبعــد انقضــاء مــدة هــذا العقــد اســتمر الطرفــان يف تنفيــذه بشــغل‬\n‫املســتأجر العــن وقبــض املؤجــر ألجــرة القســط األول مــن األجــرة‬\n‫الســنوية ( مســتند رقــم ‪ ، ) 2‬تلقــي مديــر املعــرض خطــاب مــن وكيــل‬\n‫ورثــة املؤجــر بتاريــخ ‪1433/2/24‬ه ـ مفــاده أن موكليــه باعــوا العــن‬\n‫املســتأجرة (املعــرض) محــل عقــد اإليجــار وانتهــى إلــى طلــب اإلخــاء يف‬\n‫موعــد أقصــاه ‪1433/6/30‬ه ـ وذلــك بتســليمه للمالــك اجلديــد ( مســتند‬\n‫رقــم ‪ . ) 3‬وملــا كان مــن املســلم بــه شــرع ًا ؟ أن بيــع العــن املســتأجرة‬\n‫ينصــب علــى الرقبــة وال ينصــرف إلــى املنفعــة لتملــك املســتأجر لهــا‬\n‫وكانــت إجــارة موكلــي للعــن تنتهــي يف ‪1433/12/30‬ه ـ فقــد‬\n‫كان طبيعي ـ ًا أن يســتمر موكلــي يف االنتفــاع بالعــن املســتأجرة حتــى‬\n                                                                ‫‪1433/12/30‬ه ـ ‪.‬‬\n‫‪ .4‬وبتاريــخ ‪1433/8/7‬ه ـ املوافــق ‪2012/6/27‬م تلقــي مديــر املعــرض‬\n‫فاكــس بتوقيــع ‪( .......‬املالــك اجلديــد) يطلــب فيــه إخــاء املبنــى يف‬\n‫مــدة أقصاهــا خمســة أيــام مــن تاريخــه ‪ ( .‬مســتند رقــم ‪ ) 4‬وملــا كان‬\n‫مــن املســلم بــه شــرع ًا ؟ أن امللــك ينتقــل إلــى مــن خلــف البائــع يف مالــه‬\n‫ويتلقــى امللــك عنــه فــا اعتــراض لــه علــى عقــوده بــل هــو منفــذ لهــا وذلــك‬\n‫كالــوارث واملشــتري ؟ ومــن ثــم فــإن املالــك اجلديــد لــم يكــن لــه احلــق يف‬\n‫طلبــه إخــاء العــن قبــل انتهــاء مــدة اإلجــارة يف ‪1433/12/30‬ه ـ ‪ .‬ممــا‬\n\n\n                                                                                        ‫‪218‬‬\n\f                                                       ‫يتقــدم يتضــح لفضيلتكــم ‪:‬‬\n      ‫أو ًال ‪:‬أن كل مــا للمدعــي (املالــك اجلديــد) أجــرة النصــف الثانــي مــن‬\n      ‫مــدة اإلجــارة ومقدارهــا (‪ ) 225.000‬مائتــان وخمســة وعشــرون ألــف‬\n                                                                              ‫ريــال ‪.‬‬\n      ‫ثاني ـ ًا ‪:‬أنــه ال أســاس لطلــب املدعــى تعويضــه عــن الضــرر الــذي يدعيــه‬\n      ‫ليــس فقــط النتفــاء اخلطــأ يف جانــب املدعــي عليــه (ألن اجلــواز الشــرعي‬\n      ‫ينــايف الضمــان ) واملدعــى عليــه اســتعمل حقــه يف االنتفــاع بالعــن محــل‬\n      ‫اإلجــارة حتــى نهايــة املــدة احملــددة لدفــع األجــرة ‪ ،‬وإمنــا كذلــك ألن‬\n      ‫ا‬ ‫التعويــض يف الفقــه اإلســامي ال يكــون إال عــن ضــرر مالــي واقــع فعـ ً‬\n      ‫ألنــه الســبب يف التعويــض واملســبب ال يتقــدم ســببه وإال لــم يكــن ســبب ًا‬\n      ‫لــه أ‪.‬ه ـ وبعــرض هــذه االجابــة علــى املدعــي وكالــة قــال إن البائــع قــد‬\n      ‫بلــغ الشــركة ببيعــه للعقــار وأن عليهــم االخــاء خــال مــدة اقصاهــا‬\n      ‫نهايــة االيجــار املدفــوع يف ‪1433/6/30‬ه ـ وذلــك بتاريــخ ‪1433/2/24‬هـ‬\n      ‫كمــا أن الشــركة املدعــى عليهــا اســتعدت وأرســلت ملوكلتــي خطابــا‬\n      ‫بتاريــخ ‪1433/11/9‬ه ـ يلتــزم فيــه باإلخــاء خــال خمســة عشــر يومــا‬\n      ‫مــن تاريــخ اخلطــاب وهــذا ملــزم للشــركة باإلخــاء هكــذا قــرر فطلبــت‬\n      ‫مــن املدعــي وكالــة هــذا اخلطــاب فأبــرز ورقــة مــن مطبوعــات شــركة‬\n      ‫‪.......‬بيــت ‪ ...‬مؤرخــة يف ‪1433/11/9‬ه ـ وهــذا نصهــا الســيد ‪.......‬احملترم‬\n      ‫الســام عليكــم ورحمــة اهلل وبركاتــه اشــارة الــى احملادثــة الهاتفيــة‬\n      ‫مــع املهنــدس ‪.......‬معــرض ‪ ...‬الواقــع يف حــي ‪.......‬طريــق الطائــف مبكــة‬\n      ‫املكرمــة بخصــوص االخــاء نفيدكــم بأنــه خــال ‪ 15‬يــوم مــن تاريــخ‬\n      ‫خطابنــا هــذا ســوف نقــوم بإخــاء املوقــع نهائيــا وتســليمه اليكــم مــع‬\n      ‫اعتذارنــا الشــديد ونقــدر لكــم تعاونكــم خــال الفتــرة املاضيــة ونأمــل‬\n\n\n‫‪219‬‬\n\f‫أن نقــدم لكــم خدماتنــا كشــركة معروفــة ونكــرر اعتذارنــا ولكــم‬\n‫الشــكر والتقديــر أه ـ وبعــرض هــذه الورقــة علــى املدعــى عليــه وكالــة‬\n‫فقــال أطلــب إمهالــي لالطــاع علــى هــذه الورقــة ولــذا رفعــت اجللســة ثــم‬\n‫يف جلســة أخــرى‪ ،‬حضــر الطرفــان وكالــة وبســؤال املدعــى عليــه‬\n‫وكالــة عمــا اســتمهل ألجلــه يف اجللســة املاضيــة فأبــرز ورقــة هــذا‬\n‫نصهــا‪ -:‬لقــد قــدم املدعــي يف اجللســة املاضيــة وهــو بصــدد الــرد علــى‬\n‫مذكــرة دفاعنــا صــورة خطــاب مــؤرخ يف ‪1433/11/09‬ه ـ بتوقيــع بيــت‬\n‫‪ ...‬موجــه لــأخ ‪.......‬انتهــى فيــه محــرره بعــد اإلشــارة إلــى املكاملــة‬\n‫الهاتفيــة مــع املهنــدس ‪.......‬إلــى اإلفــادة بأنــه ســيخلي املعــرض خــال (‪15‬‬\n‫يومــا) مــن تاريخــه ‪ ،‬وال يفيــد املدعــي االســتناد إلــى هــذا اخلطــاب لتبريــر‬\n‫تصرفــه مــن تأجيــر املوقــع خــال مــدة احلــج مببلــغ (‪ )200.000‬ريــال وال‬\n‫يف عــدم هدمــه وبنــاء فنــدق وتأجيــره خــال فتــرة احلــج ليــس فقــط‬\n‫لتناقضــه وافتقــاره إلــى الدليــل الــذي يؤيــده وإمنــا كذلــك ألن محــرر‬\n‫اخلطــاب لــم يكــن هــو مســتأجر املعــرض وال مــأذون لــه فيــه ‪ ،‬وحتــى‬\n‫علــى فــرض ذلــك فإنــه ال يعــدو عــن كونــه مجــرد وعــد ال يلــزم الوفــاء بــه‬\n‫وال يكــون فرضــا مــن إجنــاز الوعــد والعهــد إال علــى مــن وعــد بواجــب‬\n‫عليــه ـ وال ريــب يف أن اإلخــاء ليــس بواجــب علــى مــن وعــد ‪ ،‬ومــن ثــم‬\n‫فإنــه ال جــدال يف انتفــاء اخلطــأ كذلــك لهــذا الســبب وبالبنــاء علــى مــا‬\n‫تقدم وما ســبق أن قدمناه يف مذكرتنا الســابقة نلتمس من فضيلتكم‬\n‫عــدم ســماع دعــوى املدعــي ـ وأنــه كل مــا لــه هــو نصف القيمــة اإليجارية‬\n‫التــي امتنــع عــن اســتالمها ا‪.‬ه ـ ‪ ،‬فســألت املدعــى عليــه وكالــة هــل‬\n‫اســتأجر موكلــه العقــار لكامــل عــام ‪1433‬ه ـ مبوجــب عقــد محــرر‬\n‫فقــال أن الشــركة موكلتــي اســتأجرت العقــار لكامــل عــام‬\n\n\n                                                                                       ‫‪220‬‬\n\f      ‫‪1432‬ه ــبعقد محــرر وأمــا عــام ‪1433‬ه ـ فــا يوجــد عقــد محــرر ولكــن‬\n      ‫مالــك العقــار اســتلم الدفعــة األولــى مــن األجــرة مبوجــب ســند قبــض‬\n      ‫وهــذا يعــد جتديــد ًا للعقــد لعــام ‪1433‬ه ـ هكــذا قــرر فطلبــت مــن‬\n      ‫املدعــى عليــه وكالــة ســند قبــض الدفعــة األولــى مــن األجــرة لعــام‬\n      ‫‪1433‬ه ـ فأبــرز ســند قبــض مــن مطبوعــات ورثــة ‪.......‬برقــم ‪ 356‬مــؤرخ‬\n      ‫يف ‪1432/12/6‬ه ـ باســتالم مبلــغ مائتــن وخمســة وعشــرين ألــف ريــال‬\n      ‫ببيــت ‪ ...‬مبوجــب شــيك علــى البنــك ‪.......‬التجــاري وذلــك مقابــل أيجــار‬\n      ‫بيــت ‪ ...‬مــن الفتــرة مــن ‪1433/1/1‬ه ـ حتــى ‪1433/6/30‬ه ـ ثــم توقيــع‬\n      ‫ا‪.‬هــ‪ ،‬فســألت املدعــى عليــه وكالــة هــل يوجــد ســند أخــر أو عقــد ملــا‬\n      ‫بعــد ‪1433/6/30‬ه ـ فقــال ال ولكننــا حررنــا شــيكات للمدعــي أصالة‬\n      ‫بصفتــه املشــتري اجلديــد للعقــار فرفــض اســتالمها هكــذا قــرر وبعرض‬\n      ‫ذلــك علــى املدعــي وكالــة قــال إن البائــع لــم يجــدد العقــد لكامــل عــام‬\n      ‫‪1433‬ه ـ وإمنــا جــدده للمــدة مــن ‪1433/1/1‬ه ـ حتــى ‪1433/6/30‬ه ـ‬\n      ‫حســب ســند القبــض كمــا أن عقــد التأجيــر االساســي لــم يذكــر فيــه‬\n      ‫العقــد يتجــدد تلقائيــا كمــا ان العقــد نــص علــى أنــه يف حــال بيــع العــن‬\n      ‫املؤجــرة فــإن علــى املســتأجر االتفــاق مــع املالــك اجلديــد كمــا أن املالــك‬\n      ‫الســابق للعقــار بعــث ورقــة للمدعــى عليــه أصالــة بتاريــخ ‪1433/2/24‬ه ـ‬\n      ‫وأبلغــه فيهــا أنــه بــاع العقــار وأن علــى الشــركة أخــاء العقــار يف مــدة‬\n      ‫أقصاهــا نهايــة االيجــار املدفــوع ‪1433/6/30‬هـ وقد اســتلمت الشــركة‬\n      ‫هــذا اخلطــاب كل هــذا يــدل علــى أنــه ليــس مــن حــق الشــركة البقــاء‬\n      ‫بعــد ‪1433/6/30‬ه ـ هكــذا قــرر فطلبــت مــن املدعــى عليــه وكالــة‬\n      ‫العقــد مــع املالــك الســابق كمــا طلبــت مــن املدعــي وكالــة الورقــة التــي‬\n      ‫بعثهــا املالــك الســابق للمدعــى عليــه فابــرز املدعــى عليــه وكالــة عقــد‬\n\n\n‫‪221‬‬\n\f‫االجــارة بــن موكلــه واملالــك الســابق وهــذا نصــه (عقــد إيحــار بعــون‬\n‫اهلل وتوفيقــه أنــه يف يــوم الثالثــاء املوافــق ‪1432/01/01‬ه ـ مبدينةمكة‬\n‫املكرمــة مت االتفــاق بــن كل مــن‪ :‬االســم ‪ :‬ورثــة ‪.......‬وميثلــه يف هــذا‬\n‫العقــد األســتاذ ‪ .......‬اجلنســية ‪...........‬ســعودي مبوجــب ‪ :‬بطاقــة أحــوال‬\n‫‪ .......‬ويشــار إليــه فيمــا بعــد بالطــرف األول والســادة ‪ :‬مجموعــة ‪.......‬‬\n‫لصاحبهــا ‪.......‬وشــركاه مبوجــب ســجل جتــاري ‪.......‬وميثلــه يف هــذا‬\n‫العقــد ‪....... :‬اجلنســية ‪ :‬ميانــي مبوجــب‪ :‬أقامــه رقــم ‪.......‬ويشــار إليــه فيمــا‬\n‫بعــد بالطــرف الثانــي اتفقــا وهمــا وبحالتهمــا املعتبــرة شــرع ًا علــى أن‬\n‫يؤجــر الطــرف األول للطــرف الثانــي معــرض بيــع (‪ )...‬الكائــن ‪...‬‬\n‫اجلنوبيــة وذلــك بقصــد اســتخدامها ل ـ بيع أجهزة مكتبية وأثاث وحســب‬\n‫مــا نــص بالســجل التجــاري ـ ـ ـ وفقــا للمــواد التاليــة املــادة األولــى‪ :‬مــدة‬\n‫هــذا العقــد هــي ســنة هجريــة تبــدأ مــن ‪1432/01/01‬ه ـ وتنتهــي بنهايــة‬\n‫‪1432/12/30‬ه ـ املــادة الثانيــة‪ -1 :‬يلتــزم الطــرف الثانــي بدفــع مبلــغ‬\n‫ســنوي وقــدره ‪ 450000‬ريــال فقــط أربعمائــة وخمســون ألــف ريــال ال‬\n‫غيــر أجــرة للعــن تســدد دفعتــن بدايــة كل ســتة أشــهر مــن العــام‬\n‫الهجــري دون تأخيــر وحالــة تأخــره عــن الســداد مــدة ثالثــن يوم ـ ًا فــأن‬\n‫للطــرف األول احلــق يف املطالبــة بفســخ العقــد ‪ -2‬يف حالــة تــرك الطــرف‬\n‫الثانــي للعــن قبــل نهايــة العقــد يلتــزم بســداد باقــي أجــرة مــدة العقــد (مــا‬\n‫لــم تتــم تســوية هــذا املوضــوع ودي ـ ًا بينهمــا) املــادة الثالثــة‪ :‬يقــر الطــرف‬\n‫الثانــي باســتالمه العــن املؤجــرة و أنــه عايــن املــكان املســتأجر بنفســه‬\n‫أو بواســطة وكيلــة ووجــده ســليم ًا وصاحل ـ ًا لالســتعمال للغــرض الــذي‬\n‫اســتأجره مــن أجلــه ويقــع عليه وحده مســؤولية احلصول علــى التراخيص‬\n‫الرســمية الالزمــة املرتبطــة بذلــك االســتعمال ‪ .‬املــادة الرابعــة ‪ -1 :‬يقــر‬\n\n\n                                                                                           ‫‪222‬‬\n\f      ‫الطــرف الثانــي باحملافظــة علــى كامــل العــن املســتأجرة أو أحــد‬\n      ‫مرافقهــا ســواء وقــع منــه أو مــن أحــد التابعــن لــه وعليــه تســليم العــن يف‬\n      ‫نهايــة العقــد خاليــة مــن األضــرار الناجمــة عــن االســتعمال غيــر العــادي‪.‬‬\n      ‫‪ -2‬يلتــزم الطــرف الثانــي بعــدم إحــداث أي إضافــات أو تعديــات ثابتــة‬\n      ‫يف العــن املســتأجرة إال بعــد احلصــول علــى موافقــة خطيــة مــن املالــك‬\n      ‫حتــدد بشــكل واضــح ووضــع أولويــة هــذه االضافــات أو التعديــات‬\n      ‫والتزامــات الطرفــن عنــد نهايــة العقــد وذلــك طبق ـ ًا لألصــول الفنيــة‪.‬‬\n      ‫‪ -3‬يلتــزم الثانــي بعــدم تأجيــر العــن املســتأجرة أو جــزء منهــا مــن الباطن‬\n      ‫أو التنــازل عنهــا إال بعــد احلصــول علــى موافقــة خطيــة مــن الطــرف األول‬\n      ‫ويف حالــة مخالفــة الطــرف الثانــي لذلــك يحــق للطــرف األول املطالبــة‬\n      ‫بفســخ العقــد بعــد توجيــه انــذار خطــي للطــرف الثانــي ملــدة شــهر‬\n      ‫وللطــرف األول حــق املطالبــة بالتعويــض عــن األضــرار الناجمــة عــن‬\n      ‫ذلــك‪ .‬املــادة اخلامســة ‪ -1 :‬يلتــزم الطــرف الثانــي مبراعــاة تعاليــم الديــن‬\n      ‫اإلســامي احلنيــف وبعــدم إبــراء املطلوبــن للعدالــة أو املخالفــن للنظــام‬\n      ‫أو احتــواء أي ممنوعــات ويتحمــل املســؤولية املطلقــة جتــاه ذلــك‪-2.‬‬\n      ‫يحظــر علــى الطــرف الثانــي أن يضــع أو يخــزن يف املــكان املســتأجر‬\n      ‫مــواد خطــرة أو مضــرة بالصحــة العامــة أو بالعــن املســتأجرة إال إذا‬\n      ‫اســتأجر املــكان لغــرض صناعــي فيكــون املســتأجر مســئو ًال عــن‬\n      ‫احملافظــة علــى ســامة العــن املســتأجرة وحتمل مســؤولياتها مع مراعاة‬\n      ‫كل طــرف ملــا يجــب عليــه حــول أنظمــة وتعليمــات وإرشــادات الدفــاع‬\n      ‫املدنــي املــادة السادســة ‪ -1 :‬يف حالــة وفــاة أحــد طــريف العقــد ال يترتــب‬\n      ‫علــى ذلــك فســخ العقــد إال يف حالــة اصطــاح األطــراف علــى إنهائــه أو‬\n      ‫كــون الطــرف الثانــي ليــس لــه وارث يف اســتيفاء املنفعــة وتســتويف‬\n\n\n‫‪223‬‬\n\f‫األجــرة عــن املــدة الســابقة‪ -2 .‬يف حالــة حــدوث كارثــة مــن احلــاالت‬\n‫املعتبــرة شــرع ًا وبقــوة قاهــرة بحيــث ال ميكــن للطــرف الثانــي اســتيفاء‬\n‫املنافــع املعقــود عليهــا بفســخ العقــد وبانفســاخه يســتحق الطــرف األول‬\n‫أجــرة املــدة الســابقة لذلــك‪ -3 .‬يف حالــة بيــع العــن املؤجــرة أو بيــع العقــار‬\n‫الــذي مــن ضمنــه العــن املؤجــرة يعتبــر العقــد مســتمرا ونافــذا إلــى نهايــة‬\n‫املــدة املتفــق عليهــا مبوجــب هــذا العقــد ويتــم االتفــاق بــن الطــرف الثانــي‬\n‫واملالــك اجلديــد‪ .‬املــادة الســابعة ‪ :‬يقــر الطــرف الثانــي بتفويضــه للطــرف‬\n‫األول أو مــن ينــوب عنــه تفويضــا الزمــا غيــر قابــل للرجــوع بفتــح العــن‬\n‫املؤجــرة [أي طريقــة يراهــا مناســبة بعــد انقضــاء شــهر مــن انتهــاء مــدة‬\n‫العقــد وعــدم دفــع القيمــة اإليجاريــة يف املوعــد احملــدد لهــا ويف حالــة‬\n‫تغيب املستأجر أو سفر أو أي سبب آخر فللطرف األول احلق بالتصرف‬\n‫يف املنقــوالت واســتالمها (( ســواء كانــت عينيــة أو نقديــة )) وتأجيــر‬\n‫العــن للغيــر وال يحــق للطــرف الثانــي املطالبــة بــأي تعويض ‪.‬املــادة الثامنة‬\n‫‪ :‬يف حالــة حــدوث خــاف نتيجــة لتنفيــذ هــذا العقــد أو تفســير أحــد‬\n‫بنــوده فــإن احملكمــة املختصــة هــي جهــة البــت يف اخلــاف ملحوظــة‪:‬‬\n‫يلتــزم الطــرف الثانــي حســب االتفــاق بعمــل شــبكة انــذار حريــق حســب‬\n‫طلــب الدفــاع املدنــي وعلــى حســابه حــرر هــذا العقــد مــن نســختان أصلية‬\n‫بيــد كل طــرف نســخة للعمــل مبوجبهــا وأذنــا ملــن يشــهد واهلل خيــر‬\n‫الشــاهدين‪ ) .‬وبعــرض هــذا العقــد علــى املدعــي وكالــة قــال هذا العقد‬\n‫صحيــح وهــو بــن املدعــى عليــه وكالــة واملالــك الســابق وهــو خــاص‬\n‫بعــام وال يتجــدد تلقائيــا هكــذا قــرر ثــم ابــرز املدعــى عليــه أصالــة‬\n‫خطاب ـ ًا مــن املالــك الســابق موجه ـ ًا الــى املدعــى عليــه أصالــة مــؤرخ‬\n‫يف‪1433/2/24‬هـ وهذا نصه ( الســادة شــركة مجموعة ‪.......‬الســام‬\n\n\n                                                                                         ‫‪224‬‬\n\f      ‫عليكــم ورحمــة اهلل وبركاتــه نفيدكــم علمــا بأننــا قــد قمنــا ببيــع‬\n      ‫العقــار املؤجــر لكــم ‪ ...‬وعليــه نرجــوا منكــم اخــاء العقــار يف مــدة‬\n      ‫اقصاهــا نهايــة االيجــار املدفــوع ‪1433/6/30‬ه ـ وذلــك لتســليمه للمالــك‬\n      ‫اجلديــد ورثــة ‪ ).......‬وبعــرض هــذا اخلطــاب علــى املدعــى عليــه وكالــة‬\n      ‫قــال هــذا اخلطــاب اســتلمه موكلــي ولكــن ليــس مــن حــق املالــك‬\n      ‫الســابق مخاطبتنــا بعــد بيعــه العقــار الن عالقتنــا اصبحــت مــع املالــك‬\n      ‫اجلديــد وقــد ارســل لنــا املالــك اجلديــد خطاب ـ ًا يف شــهر شــعبان يطلــب‬\n      ‫االخــاء خــال خمســة أيــام مــن تاريــخ خطابــه هكــذا قــرر فســألت‬\n      ‫املدعــى عليــه وكالــة هــل مت االتفــاق مــع املالــك اجلديــد علــى اجــرة املــدة‬\n      ‫التــي بعــد ‪1431/6/30‬ه ـ فقــال ال لــم نتفــق معــه ولكــن كان هنــاك‬\n      ‫شــكوى يف شــرطة العزيزيــة يف شــهر رمضــان ثــم ابلغنــا املالــك اجلديــد‬\n      ‫اننــا ســنخلي يف شــهر ذي احلجــة هكــذا قــرر وعليــه فقــد جــرى بعــث‬\n      ‫املعاملــة لهيئــة النظــر لتقديــر أجــرة العقــار للمــدة مــن ‪1433/7/1‬ه ـ‬\n      ‫حتــى ‪1433/12/3‬ه ـ واالســعار الســائدة يف ذلــك الوقــت وذلك بخطابي‬\n      ‫رقــم ‪ 34/821159‬يف ‪1434/5/25‬ه ـ فــوردت اإلجابــة مــن هيئــة النظــر‬\n      ‫برقــم ‪ 34/821159‬يف ‪1434/7/1‬ه ـ وهــذا نصــه احملضــر ‪ -:‬احلمــد هلل‬\n      ‫وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ..‬وبعــد بنــاء علــى املعاملة‬\n      ‫الــواردة مــن فضيلــة الشــيخ الدكتــور ‪.......‬برقــم ‪ 34821159‬وتاريــخ‬\n      ‫‪1434/5/25‬ه ـ واملتعلقــة بدعــوى ‪.......‬ضــد ‪ .......‬بخصــوص أجــرة عقار‬\n      ‫والــذي طلــب فيهــا فضيلتــه تقديــر أجــرة املــدة مــن تاريــخ ‪1433/7/1‬ه ـ‬\n      ‫حتــى تاريــخ اإلخــاء ‪1433/12/3‬ه ـ حســب األســعار الســائدة يف ذلــك‬\n      ‫الوقــت ‪ ،‬وعليــه فقــد جــرى االجتمــاع بطــريف الدعــوى والــذي نــراه يف‬\n      ‫تقديــر أجــرة املــدة مــن تاريــخ ‪1433/7/1‬ه ـ حتــى تاريــخ اإلخــاء‬\n\n\n‫‪225‬‬\n\f‫‪1433/12/3‬ه ـ حســب األســعار الســائدة هــو مبلــغ أربعمائــة وثمانــون‬\n‫ألــف ريــال (‪ )480.000‬ألــف ريــال مقابــل الفتــرة املذكــورة أعــاه ‪ .‬هــذا‬\n‫مــا جــرى تقديــره والســام عضــو هيئــة النظــر توقيــع ‪.......‬توقيــع عضــو‬\n‫هيئــة النظــر ‪.......‬ا‪.‬ه ـ ‪ ،‬وبعــرض هــذا القــرار علــى الطرفــن قــال املدعــي‬\n‫وكالــة إن موكلــي يقــدر األجــرة بأربعمائــة وخمســن ألــف ريــال فقــط‬\n‫ويطالــب بهــذا املبلــغ مقابــل األجــرة ويطالــب أيضــا باإلضــرار الناجتــة‬\n‫عــن تأخــر املدعــى عليــه يف أخــاء املبنــى ممــا فــوت علــى موكلــي هــدم‬\n‫املوقــع وإعــادة بنائــه والتأجيــر ملوســم احلــج لعــام ‪1434‬ه ـ وموكلــي يقدر‬\n‫هــذا الضــرر مبليــون وخمســمائة وخمســن ألــف ريــال ولــذا فــإن اجمالــي‬\n‫مــا يطالــب بــه موكلــي هــو مليونــا ريــال هكــذا قــرر وبعــرض قــرار‬\n‫هيئــة النظــر ومــا قــرره املدعــي وكالــة علــى املدعــى عليــه وكالــة قــال‬\n‫أطلــب إمهالــي ملراجعــة موكلــي ولــذا رفعــت اجللســة ثــم يف جلســة أخــرى‬\n‫‪ ،‬حضــر الطرفــان وكالــة وبســؤال املدعــى عليــه وكالــة عمــا اســتمهل‬\n‫ألجلــه وأبــرز ورقــة هــذا نصهــا أتقــدم لفضيلتكــم مبذكــرة الــرد علــى‬\n‫تقديــر هيئــة النظــر الصــادر يف القضيــة املنظــورة أمــام فضيلتكــم برقــم‬\n‫(‪ )34/821159‬وتاريــخ ‪1434/4/3‬ه ـ وبــكل احتــرام ؟ فإننــي ال أتفــق‬\n‫مــع هيئــة النظــر فيمــا انتهــى إليــه مــن تقديــر قيمــة أجــرة املثــل مببلــغ‬\n‫(‪ )480000‬ريــال للســتة شــهور الالحقــة مباشــرة علــى األجــرة املدفوعــة‬\n‫للســتة شــهور الســابقة عليهــا والبالغــة (‪ )225000‬ريــال ‪ ،‬فليــس مــن‬\n‫املعقــول أن تزيــد األجــرة خــال الســتة شــهور أكثــر مــن (‪ )%100‬وأن‬\n‫صــح ذلــك يف العمائــر التجاريــة واملــوالت لألجــرة التــي مت االتفــاق عليهــا‬\n‫منــذ ســنوات ‪ ،‬فــا يصبــح يف الهناجــر (الشــنكو) ‪ ،‬ومــن مت فإننــا‬\n‫نعتــرض علــى تقديــر هيئــة النظــر ‪ ،‬ونلتمــس مــن فضيلتكــم طلــب‬\n\n\n                                                                                       ‫‪226‬‬\n\f      ‫إعــادة النظــر فيــه علــى ضــوء املــكان والزمــان مــا بــن األجــرة وأجــرة‬\n      ‫املثــل وامتــداد مــدة العقــد لنفــس مدتــه ‪.‬ا‪.‬ه ـ ‪ ،‬وبســؤال املدعــي عــن‬\n      ‫تاريــخ اصــدار رخصــة املبنــى وعــدد أدوار العمــارة فقــال انهــا صــدرت‬\n      ‫بتاريــخ ‪1434/3/25‬ه ـ ولكــن قبــل ذلــك بدأنــا باحلفــر وإزالــة املنشــآت‬\n      ‫الســابقة والعمــارة مكونــة مــن بــدروم وأرض وميزايــن ومطعــم ومصلــى‬\n      ‫ومطعــم وخدمــات وخمســة عشــر دورا متكــررا ا‪.‬ه ـ فطلبــت منه رخصة‬\n      ‫البنــاء فأبــرز رخصــة صــادرة مــن إدارة الرخــص بأمانــة العاصمــة‬\n      ‫املقدســة برقــم ‪ 3401500961‬يف ‪1434/3/25‬ه ـ ‪،‬وباالطــاع عليــه‬\n      ‫وجدتهــا تتضمــن التصريــح للمدعــي أصالــة بنــاء عمــارة مكونــه مــن‬\n      ‫بــدروم ودور أرضــي وميزانــن ومصلــى ومطعــم وخدمــات وخمســة عشــر‬\n      ‫دورا متكــررا ا‪.‬ه ـ ‪،‬وبســؤال الطرفــن هــل لديهمــا مــا يضيفانــه فقــال‬\n      ‫ليــس لدينــا ســوى مــا قدمنــاه ســلفا ‪ ،‬فبنــاء علــى مــا تقــدم مــن الدعــوى‬\n      ‫واإلجابــة وبعــد االطــاع علــى قــرار هيئــة النظــر وعلــى صــك امللكيــة‬\n      ‫وعلــى عقــد اإلجــارة بــن املدعــى عليــه أصالــة والبائــع وألن هــذا العقــد‬\n      ‫نــص علــى أن مــدة العقــد ســنه واحــدة وهــي لعــام ‪1432‬ه ـ فقــط دون‬\n      ‫االشــارة إلــى جتــدده تلقائيــا وبعــد االطــاع علــى املراســات بــن البائــع‬\n      ‫واملدعــى عليــه واملتضمــن إبــاغ البائــع للمدعــى عليــه بالبيــع وإمهالــه‬\n      ‫للخــروج حتــى ‪1433/6/30‬ه ـ كمــا تضمــن أيضــا الســند املوقــع مــن‬\n      ‫البائــع باســتالم األجــرة أن هــذه األجــرة للمــدة مــن ‪1432/1/1‬ه ـ حتــى‬\n      ‫‪1433/6/30‬ه ـ فقــط وكذلــك مطالبة املشــتري للمدعــى عليه باخلروج‬\n      ‫بعــد انتهــاء املــدة وألن املدعــي أصالــة قــدر أجــرة املــدة مــن ‪1433/7/1‬هـ‬\n      ‫بأربعمائــة وخمســن ألــف ريــال وطالــب بهــذا املبلــغ وهــو أقــل ممــا قدرتــه‬\n      ‫هيئــة النظــر كمــا طالــب بتعويضــه عــن التأخيــر يف هــدم املوقــع وبنــاء‬\n\n\n‫‪227‬‬\n\f‫عمــارة عليــه وتأجيــر ملوســم احلــج لهــذا العــام ‪1434‬ه ـ لذلــك كلــه وألن‬\n‫مطالبــة املدعــي بأجــرة مــدة بقــاء املدعــى عليــه مــن ‪1433/7/1‬ه ـ حتــى‬\n‫تاريــخ اإلخــاء وقدرهــا بأربعمائــة وخمســن ألــف ريــال وألن مــا قررتــه‬\n‫هيئــة النظــر هــو أكثــر مــن هــذا املبلــغ وقــد قــرر املدعــي وكالــة أن‬\n‫موكلــه يطالــب باألجــرة التــي يدعيهــا وال يطالــب مبــا قــدرت بــه هيئــة‬\n‫النظــر وألن مطالبــة املدعــي باألجــرة لهــذه املــدة هــو إقــرار منــه ببقــاء‬\n‫املدعــى عليــه يف املوقــع فــا ميكنــه اجلمــع يف املطالبــة بــن األجــرة وضرر‬\n‫التأخــر يف اإلخــاء كمــا إن هــذه اإلضــرار التــي يدعيهــا وهــي عــدم‬\n‫متكنــه مــن بنــاء العمــارة وتأجيرهــا ملوســم حــج هــذا العــام ‪1434‬ه ــي‬\n‫دعــوى بضــرر عــن فــوات تأجيــر مبنــى غيــر موجــود ولــم يبــدأ بنائــه اال‬\n‫بعــد اصــدار تصريــح البنــاء يف ‪1434/3/25‬ه ـ وألن انتهــاء املبنــى قبــل‬\n‫موســم احلــج وتأجيــره هــذا املوســم أمــر لــم يحصــل وهــو ضــرر متوقــع‬\n‫فقــد ينتهــي مــن البنــاء قبــل املوســم ويؤجــره وقــد ال يتمكــن مــن ذلــك‬\n‫ألســباب أخــرى وألن الضــرر املضمــون هــو الضــرر الواقــع أمــا الربــح‬\n‫الفائــت والضــرر غيــر املتوقــع فهــو غيــر مضمــون كمــا قــرر ذلــك أهــل‬\n‫العلــم قــال البهوتــي يف شــرح املنتهــى ‪ 122/4‬وال يضمــن ربــح فــأت علــى‬\n‫مالــك بحبــس غاصــب مــال جتــارة مــدة ميكــن أن يتجــر فيهــا إذا لــم‬\n‫يتجــر فيــه الغاصــب « وينظــر شــرح املنتهــى البــن النجــار ‪ 215/5‬لذلــك‬\n‫كلــه فقــد حكمــت علــى املدعــى عليــه اصالــه بــأن يدفــع للمدعــى‬\n‫أجــرة املــدة مــن ‪1433/7/1‬ه ـ حتــى تاريــخ اإلخــاء مبلغ وقــدره أربعمائة‬\n‫وخمســون ألــف ريــال وعــدم اســتحقاق املدعــي للتعويــض الــذي يطالــب‬\n‫بــه وبعــرض احلكــم علــى الطرفــن قــررا عــدم القناعــة وطلبــا رفعــه‬\n‫حملكمــة االســتئناف بعــد تقــدمي الئحــة اعتراضيــة عليــه فأفهمتهمــا‬\n\n\n                                                                                     ‫‪228‬‬\n\f      ‫مبراجعــة احملكمــة خــال عشــرة أيــام الســتالم صــورة الصــك وتقــدمي‬\n      ‫الالئحــة االعتراضيــة خــال ثالثــن يومــا مــدة االعتــراض فــإذا تأخــرا‬\n      ‫عــن تقــدمي الالئحــة االعتراضيــة ســقط حقهمــا يف طلــب االســتئناف‬\n      ‫واكتســب احلكــم القطعيــة ‪ ،‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n                          ‫محمد وعلى آله وصحبه وسلم ‪ .‬حرر يف ‪1434/8/16‬هـ‬\n      ‫احلمد هلل ‪ ،‬والصالة والسالم على رسول اهلل ‪ ،‬وبعد ‪ :‬ـ فقـد جـرى م ّنا‬\n      ‫نح ــن رئيس وأعضاء الدائ ــرة احلقوقي ــة الثالثة يف محكم ــة االستئناف‬\n      ‫مبنطقة مك ــة املكرم ــة االطال ُع عل ــى هـذا الصك الصـادر من فضيـلة‬\n      ‫الشي ــخ ‪.......‬القاضــي باحملكمــة العامــة مبكــة املكرمــة واملســجل‬\n      ‫بعــدد ‪ 34300352‬وتــاري ــخ ‪1434/8 /17‬ه ـ املتضمــن دعــوى ‪.......‬ضــد‬\n      ‫شــركة ‪.......‬وشــركاه يف مبلــغ مالــي احملكــوم فيــه مبــا دون باطنــه‬\n      ‫وبــدراس ــة احلك ــم وص ــورة ضبط ــه والئحتــه االعتراضيــة تقـ ـ ـ ـ ــررت‬\n      ‫املـ ــوافقـ ـ ـ ــة علــى احلكــم وبــاهلل تعالــى التوفيــق وصل ــى اهلل عل ــى نبي ــنا‬\n                                                 ‫محم ــد وعل ــى آل ــه وصحب ــه وسـلم ‪،‬‬\n\n\n\n\n‫‪229‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"612f1ba9-3f27-52bc-993f-69d3ecdc8564","source_page_start":214,"source_page_end":229,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"641972f524692bf43caeb9dd80cfc8687ea97f9850c87b6f0f6fe5deb9b6adb6","normalized_text_hash":"5d0f9867b0eb204bde20edfc4c9cbf1f323027924b2927ffcb18c36f9d408869","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v7-p214-34300352"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"64cc5c82-5f5f-54e3-89d8-c56e4bd95c2a","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقد -أجارة -مطالبة بأجرة عن -سماع الدعوى غيابي ا لتعذر إباغ املدعى عليه -البينة بشهادة الشهود واليمن -األصل عدم دفع األجرة -وجوب الوفاء بالعقود احلكم بإلزام املدعى عليه بدفع باقي أجرة العن -رفع احلكم حملكمة الاستئناف لتعذر تبليغ املدعى عليه باحلكم.","document_number":"34271615","case_number":"33710584","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/17","year":"1434","subject":"عقد -أجارة -مطالبة بأجرة عن -سماع الدعوى غيابي ا لتعذر إباغ املدعى عليه -البينة بشهادة الشهود واليمن -األصل عدم دفع األجرة -وجوب الوفاء بالعقود احلكم بإلزام املدعى عليه بدفع باقي أجرة العن -رفع احلكم حملكمة الاستئناف لتعذر تبليغ املدعى عليه باحلكم.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/7/17 :‬هـ‬\n                 ‫ُ‬                 ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪34271615 :‬‬\n                    ‫َر ْق ُم الدعوى‪33710584 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n           ‫‪ 34345213‬تاريخه‪1434/10/29:‬هـ‬\n\n\n\n‫عقــد ‪ -‬أجــارة ‪ -‬مطالبــة بأجــرة عــن ‪ -‬ســماع الدعــوى غيابي ـ ًا لتعــذر‬\n‫إبــاغ املدعــى عليــه ‪ -‬البينــة بشــهادة الشــهود واليمــن ‪ -‬األصــل عــدم‬\n‫دفــع األجــرة ‪ -‬وجــوب الوفــاء بالعقــود احلكــم بإلــزام املدعــى عليــه‬\n‫بدفــع باقــي أجــرة العــن ‪ -‬رفــع احلكــم حملكمــة االســتئناف لتعــذر‬\n                                            ‫تبليــغ املدعــى عليــه باحلكــم‪.‬‬\n\n\n\n\n                   ‫‪ .1‬قوله تعالى (يا أيها الذين آمنوا أوفوا بالعقود)‪.‬‬\n‫‪ .2‬قولــه صلــى اهلل عليــه وســلم (املســلمون علــى شــروطهم) رواه‬\n                                                  ‫الترمــذي وأبــو داوود‪.‬‬\n‫‪ .3‬قولــه صلــى اهلل عليــه وســلم (البينــة علــى املدعــي واليمــن علــى‬\n                                              ‫املدعــى عليــه) رواه الترمــذي‪.‬‬\n‫‪ .4‬جــاء يف مجمــوع الفتــاوى ‪( 24/300‬إذا كان الــذي عليــه احلــق قــادرا‬\n‫علــى الوفــاء وعطلــه حتــى أحوجــه إلــى الشــكاية فمــا غرمــه بســبب‬\n      ‫ذلــك فهــو علــى الظالــم املماطــل إذا غرمــه علــى الوجــه املعتــاد)‪.‬‬\n                          ‫‪ .5‬املادة ‪ 55‬و‪ 5/176‬من نظام املرافعات الشرعية‪.‬‬\n                                                     ‫‪ .6‬قاعدة‪ :‬األصل العدم ‪.‬‬\n\n\n\n\n                                                                                  ‫‪184‬‬\n\f      ‫ادعــى املدعــي ضــد املدعــى عليــه الغائــب عــن مجلــس احلكــم بأنــه‬\n      ‫كان مســتأجر ًا للشــقة رقــم ‪ 11‬يف عمــارة بحــي ‪ ...‬مبحافظــة جــدة‪،‬‬\n      ‫بأجــرة ســنوية قدرهــا اثنــان وعشــرون ألــف ريــال‪ ،‬إضافــة إلــى اخلدمــات‬\n      ‫مببلــغ قــدره ألفــان وأربعمائــة ريــال‪ ،‬اعتبــار ًا مــن تاريــخ ‪1432/9/1‬هــ‪،‬‬\n      ‫وقــد أخلــى العقــار يف ‪1434/2/10‬ه ـ مبوجــب محضــر معــد مــن قبــل‬\n      ‫حــارس العمــارة واثنــن مــن ســكانها‪ ،‬وبقــي يف ذمتــه مــن أجــرة العقــار‬\n      ‫مــن تاريــخ ‪1432/11/1‬ه ـ وحتــى تاريــخ اإلخــاء يف ‪1434/2/10‬ه ـ‬\n      ‫مبلغــا قــدره واحــد وثالثــون ألفــا ومائــة وســبعون ريــا ًال ‪ ،‬وعليــه فاتــورة‬\n      ‫اســتهالك كهربــاء مبلغــا قــدره أربعمائــة وثمانيــة وخمســون ريــاال‬\n      ‫وخمســه وأربعــون هللــة‪ ،‬وقــد نصــت الفقــرة ‪ 19‬مــن العقــد املبــرم بــن‬\n      ‫الطرفــن علــى أنــه (إذا تأخــر الطــرف الثانــي عــن دفــع أي مبلــغ مســتحق‬\n      ‫مــدة خمســة عشــر يومــا فــإن ‪ ..‬للطــرف األول أو نائبــه احلــق يف رفــع‬\n      ‫القضيــة إلــى اجلهــة املختصــة إلجبــار الطــرف الثانــي بدفــع املســتحق‬\n      ‫مــع إلــزام الطــرف الثانــي بدفــع ‪ %25‬مــن أصــل املبلــغ زيــادة علــى املبلــغ‬\n      ‫األصلــي)‪ ،‬وقدرهــا ســبعة آالف وتســعمائة وســبعة ريــاالت‪ ،‬يطلــب إلزام‬\n      ‫املدعــى عليــه بدفــع كامــل املبلــغ محــل الدعــوى هكــذا ادعى‪،‬لــم يبلــغ‬\n      ‫املدعــى عليــه حيــث لــم يتــم العثــور عليــه حســب إفــادة الشــرطة‪ ،‬جــرى‬\n      ‫ســماع الدعــوى غيابيـ ًا بنــاء علــى املــادة ‪ 55‬مــن نظــام املرافعات الشــرعية‬\n      ‫‪ ،‬بينــة املدعــي عقــد اإليجــار وصــك ملكيــة العقــار ومحضــر اإلخــاء‪،‬‬\n      ‫كمــا أحضــر شــاهدين شــهدا بإخــاء املدعــى عليــه للعقــار كمــا يف‬\n      ‫الدعــوى‪ ،‬قــرر املدعــي بــأن املدعــى عليــه ســلم مبلــغ وقــدره ســبعة آالف‬\n\n‫‪185‬‬\n\f‫ريــال حلــارس العمــارة وأن املتبقــي يف ذمتــه مــن املبلــغ املدعــى بــه قــدره‬\n‫اثنــان وثالثــون ألــف وخمســمائة وثالثــون رياالً‪،‬حلف املدعــي على صحة‬\n‫دعــواه بعــد طلبهــا منــه‪ ،‬وبنــاء علــى البينــة ســالفة الذكــر‪ ،‬وبنــاء علــى‬\n‫أن األصــل عــدم دفــع األجــرة ‪ ،‬وليمــن املدعــي علــى صحــة دعــواه وعــدم‬\n‫اســتالمه مــن مبلــغ الدعــوى شــيئا ‪ ،‬ولقولــه تعالــى (يــا أيهــا الذيــن آمنــوا‬\n‫أوفــوا بالعقــود)‪ ،‬وحلديــث (املســلمون علــى شــروطهم) رواه الترمــذي‬\n‫وأبــو داوود‪ ،‬وحلديــث (البينــة علــى املدعــي واليمــن علــى املدعــى عليــه)‬\n‫رواه الترمــذي ‪ ،‬وملــا جــاء يف الفتــاوى مــا نصــه قــال شــيخ اإلســام ( إذا‬\n‫كان الــذي عليــه احلــق قــادرا علــى الوفــاء وعطلــه حتــى أحوجــه إلــى‬\n‫الشــكاية فمــا غرمــه بســبب ذلــك فهــو علــى الظالــم املماطــل إذا غرمــه‬\n‫علــى الوجــه املعتــاد) ‪ ، 24/300‬وهــو موافــق للشــرط املضمــن بالعقــد‬\n‫مــن حيــث املبــدأ ‪ ،‬وبنــاء علــى املــادة ‪ 55‬و ‪ 5/176‬مــن نظــام املرافعــات‬\n‫الشــرعية‪ ،‬وملــا تقــدم صــدر احلكــم علــى املدعــى عليــه بدفــع مبلــغ قــدره‬\n‫اثنــان وثالثــون ألفــا وخمســمائة وثالثــون ريــاال للمدعــي‪ ،‬قنــع املدعــي‬\n‫باحلكــم مت بعــث املعاملــة حملكمــة االســتئناف لتدقيــق احلكــم‪ ،‬صــدق‬\n‫احلكــم مــن الدائــرة احلقوقيــة الرابعــة مبحكمــة االســتئناف مبنطقــة‬\n                                                                 ‫مكــة املكرمــة‪.‬‬\n\n\n\n\n‫احلمد هلل وحده وبعد فلدي ‪.......‬القاضي يف احملكمة العامة مبحافظة‬\n‫جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫مبحافظــة جدة‪/‬املســاعد برقــم ‪ 33710584‬وتاريــخ ‪1433/12/28‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 332267614‬وتاريــخ ‪1433/12/28‬ه ـ ففــي‬\n\n                                                                                        ‫‪186‬‬\n\f      ‫يــوم الســبت املوافــق ‪1434/03/28‬ه ـ افتتحــت اجللســة الســاعة ‪08 : 30‬‬\n      ‫وفيهــا حضــر املدعــي ‪ .......‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n      ‫رقــم ‪ .......‬ولــم يحضــر املدعــى عليــه ‪ .......‬ســعودي اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم ‪ .......‬وال مــن ميثلــه ‪ ،‬وقــد خطــاب مديــر مركــز‬\n      ‫شــرطة النزهــة برقــم ‪ 36/1300‬وتاريــخ ‪1434/2/19‬ه ـ واملتضمــن‬\n      ‫أنــه (بالرجــوع إلــى احلاســب اآللــي طرفنــا اتضــح بــأن عنــوان املذكــور‬\n      ‫حــي ‪ ...‬وبالبحــث والتحــري عــن املذكــور لــم يتــم العثــور عليــه كمــا مت‬\n      ‫االتصــال علــى جــوال‪ .......‬ومت الــرد مــن قبــل شــخص اســمه‪ ......‬وبســؤاله‬\n      ‫عــن املذكــور أفــاد بأنــه ال يعرفــه)‪ .‬أه ـ وبعرضــه علــى املدعــي قــال ‪:‬‬\n      ‫أطلــب التعميــم علــى املدعــى عليــه وإيقــاف خدماتــه‪ .‬ثــم رفعــت اجللســة‬\n      ‫لذلك‪ .‬ويف يوم األحد املوافق ‪1434/06/18‬هـ افتتحت اجللســة الســاعة‬\n      ‫‪ 10 : 30‬وفيهــا حضــر املدعــي ‪ .......‬ولــم يحضــر املدعــى عليــه‪.......‬وال من‬\n      ‫ميثلــه ‪ ،‬وقــد جــرت الكتابــة لشــرطة محافظــة جــدة إليقــاف خدمــات‬\n      ‫املدعــى عليــه مبوجــب خطابنــا رقــم ‪ 34764870‬وتاريــخ ‪1434/3/29‬هـ‬\n      ‫ولــم يراجعنــا أحــد ‪ ،‬فبنــاء علــى املــادة ‪ 55‬مــن نظــام املرافعــات الشــرعية‬\n      ‫ولتعــذر العثــور علــى املدعــى عليــه وتبليغــه فقــد قررت الســير يف الدعوى‬\n      ‫غيابيــا يف حــق املدعــى عليــه ‪ ،‬وادعــى املدعــي قائــا ‪ :‬لقــد كان املدعى‬\n      ‫عليــه مســتأجرا للشــقة رقــم ‪ 11‬يف عمــارة مملوكــة لــي يف حــي ‪ ...‬رقــم‬\n      ‫‪ ....‬مبحافظــة جــدة ‪ ،‬بأجــرة ســنوية قدرهــا اثنــان وعشــرون ألــف ريــال ‪،‬‬\n      ‫إضافــة إلــى اخلدمــات مببلــغ قــدره ألفــان وأربعمائــة ريــال‪ ،‬اعتبــارا مــن‬\n      ‫تاريــخ ‪1432/9/1‬ه ـ ‪ ،‬مبوجــب عقــد إيجــار رقــم ‪ 11‬فئــة (أ) وتاريــخ‬\n      ‫‪1432/9/1‬ه ـ ‪ ،‬وقــد أخلــى العقــار يف ‪1434/2/10‬ه ـ مبوجــب محضر‬\n      ‫معــد مــن قبــل حــارس العمــارة واثنــن مــن ســكانها ‪ ،‬وبقــي يف ذمتــه‬\n\n\n‫‪187‬‬\n\f‫مــن أجــرة العقــار مــن تاريــخ ‪1432/11/1‬ه ـ وحتــى تاريــخ اإلخــاء يف‬\n‫‪1434/2/10‬ه ـ مبلغــا قــدره واحــد وثالثــون ألفــا ومائــة وســبعون ريــاال ‪،‬‬\n‫وعليــه فاتــورة اســتالك كهربــاء مبلغــا قــدره أربعمائة وثمانية وخمســون‬\n‫ريــاال وخمســة وأربعــون هللــة مبوجــب فاتــورة اســتالك كهربــاء رقــم‬\n‫‪ 24902‬للفتــرة مــن ‪1434/1/7‬ه ـ وحتــى ‪1434/2/6‬ه ـ للحســاب رقــم‬\n‫‪ ، 267384906‬وقــد نصــت الفقــرة ‪ 19‬مــن العقــد املبــرم بــن الطرفــن‬\n‫علــى أنــه (إذا تأخــر الطــرف الثانــي عــن دفــع أي مبلــغ مســتحق مــدة‬\n‫خمســة عشــر يومــا فــإن ‪ ..‬للطــرف األول أو نائبــه احلــق يف رفــع القضيــة‬\n‫إلــى اجلهــة املختصــة إلجبــار الطــرف الثانــي بدفــع املســتحق مــع إلــزام‬\n‫الطــرف الثانــي بدفــع ‪ %25‬مــن أصــل املبلــغ زيــادة علــى املبلــغ األصلــي) ‪،‬‬\n‫وقدرهــا ســبعة آالف وتســعمائة وســبعة ريــاالت ‪ ،‬أطلــب إلــزام املدعــى‬\n‫عليــه بدفــع كامــل املبلــغ محــل الدعــوى وقــدره تســعة وثالثــون ألفــا‬\n‫وخمســمائة وخمســة وثالثون رياال ‪ .‬هذه دعواي ‪ .‬ثم أبرز املدعي صورة‬\n‫مــن عقــد اإليجــار وأصــل محضــر اإلخــاء وأصــل فاتــورة اســتهالك‬\n‫كهربــاء ‪ ،‬ومت تزويــد املعاملــة بنســخة منهــا ‪ ،‬وبســؤاله عــن أصــل عقــد‬\n‫اإليجــار وأصــل صــك امللكيــة وشــهود محضــر اإلخــاء قــال‪ :‬أطلــب‬\n‫اإلمهــال إلحضارهــا يف اجللســة القادمــة ‪ .‬ثــم رفعــت اجللســة لذلــك‪ .‬ويف‬\n‫يــوم االثنــن املوافــق ‪1434/07/17‬ه ـ افتتحــت اجللســة الســاعة ‪02 : 00‬‬\n‫وفيهــا حضــر املدعــي ‪ .......‬ولــم يحضــر املدعــى عليــه ‪ .......‬وال مــن ميثلــه‪،‬‬\n‫وقــد أبــرز املدعــي أصــل صــك امللكيــة الصــادر مــن كتابة العــدل الولى‬\n‫بجــدة برقــم ‪ 3557‬وتاريــخ ‪1420/12/27‬ه ـ واملتضمــن انتقــال ملكيتــه‬\n‫للمدعــي يف ‪1425/6/23‬ه ـ ‪ ،‬كمــا أبــرز أصــل عقــد اإليجــار‪ ،‬ومت‬\n‫تزويــد املعاملــة بنســخة منهمــا ‪ ،‬كمــا أحضــر للشــهادة وأدائهــا كال‬\n\n\n                                                                                        ‫‪188‬‬\n\f      ‫مــن ‪.......‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪.......‬وهــو مــن‬\n      ‫مواليــد ‪1403‬ه ـ ويعمــل يف ‪.......‬ويســكن يف حــي ‪.......‬مبحافظــة جــدة‪،‬‬\n      ‫وهــو ابــن أخ للمدعــي ‪ ،‬و‪.......‬مصــري اجلنســية مبوجــب اإلقامــة رقــم‬\n      ‫‪.......‬وهــو مــن مواليــد ‪1979‬م ويعمــل حــارس للعمــارة محــل الدعــوى لــدى‬\n      ‫املدعــي ‪ ،‬ويســكن فيهــا بحــي ‪ ...‬رقــم ‪ ...‬مبحافظــة جــدة ‪ ،‬وشــهد كل‬\n      ‫واحــد منهمــا مبفــرده قائــا ‪ :‬أشــهد هلل تعالــى بــأن املدعــى عليــه ‪.......‬‬\n      ‫قــد أخلــى الشــقة رقــم ‪ 11‬محــل الدعــوى يف ‪1434/2/10‬ه ـ بعــد أن‬\n      ‫أخــذ كل أغراضــه ‪ ،‬وســلم املفتــاح للشــاهد الثانــي حــارس العمــارة ‪.‬‬\n      ‫هكــذا شــهدا ‪ .‬وقــرر املدعــي قائــا ‪ :‬لقــد تبــن لــي بــأن املدعــى عليــه‬\n      ‫قــد ســدد مبلغــا قــدره ســبعة آالف ريــال وســلمها حلــارس العمــارة وهــو‬\n      ‫الشــاهد الثانــي ‪ ،‬وبقــي يف ذمتــه مــن مبلــغ الدعــوى مبلغــا قــدره اثنــان‬\n      ‫وثالثــون ألفــا وخمســمائة وثالثــون ريــاال ‪ ،‬وأطلــب إلــزام املدعــى عليــه‬\n      ‫بدفــع هــذا املبلــغ بالتفصيــل الســابق ‪ .‬وبعــرض اليمــن علــى املدعــي علــى‬\n      ‫صحــة الدعــوى وعــدم اســتالمه مــن مبلــغ الدعــوى شــيئا اســتعد لذلــك‪،‬‬\n      ‫ثــم حلــف قائــا ‪ :‬واهلل العظيــم الــذي ال إلــه إال هــو أن املدعــى عليــه‬\n      ‫يف‪.......‬ي كان مســتأجرا للشــقة رقــم ‪ 11‬يف عمــارة مملوكــة لــي يف‬\n      ‫حــي ‪.......‬رقــم ‪ ...‬مبحافظــة جــدة ‪ ،‬بأجــرة ســنوية قدرهــا اثنان وعشــرون‬\n      ‫ألــف ريــال ‪ ،‬إضافــة إلــى اخلدمــات مببلــغ قــدره ألفــان وأربعمائــة ريــال‬\n      ‫‪ ،‬اعتبــارا مــن تاريــخ ‪1432/9/1‬ه ـ ‪ ،‬مبوجــب عقــد إيجــار رقــم ‪11‬‬\n      ‫فئــة (أ) وتاريــخ ‪1432/9/1‬ه ـ ‪ ،‬وقــد أخلــى العقــار يف ‪1434/2/10‬ه ـ‬\n      ‫مبوجــب محضــر معــد مــن قبــل حــارس العمــارة واثنــن مــن ســكانها ‪،‬‬\n      ‫وبقــي يف ذمتــه مــن أجــرة العقــار مــن تاريــخ ‪1432/11/1‬ه ـ وحتــى تاريــخ‬\n      ‫اإلخــاء يف ‪1434/2/10‬ه ـ مبلغــا قــدره أربعــة وعشــرون ألفــا ومائــة‬\n\n\n‫‪189‬‬\n\f‫وســبعون ريــاال ‪ ،‬وعليــه فاتــورة اســتالك كهربــاء مبلغــا قــدره أربعمائــة‬\n‫وثمانيــة وخمســون ريــاال وخمســة وأربعــون هللــة مبوجــب فاتورة اســتالك‬\n‫كهربــاء رقــم ‪ 24902‬للفتــرة مــن ‪1434/1/7‬ه ـ وحتــى ‪1434/2/6‬ه ـ‬\n‫للحســاب رقــم ‪ ، 267384906‬وقــد نصــت الفقــرة ‪ 19‬مــن العقــد املبــرم‬\n‫بــن الطرفــن علــى أنــه (إذا تأخــر الطــرف الثانــي عــن دفــع أي مبلــغ‬\n‫مســتحق مــدة خمســة عشــر يومــا فــإن ‪ ..‬للطــرف األول أو نائبــه احلــق يف‬\n‫رفــع القضيــة إلــى اجلهــة املختصــة إلجبــار الطــرف الثانــي بدفــع املســتحق‬\n‫مــع إلــزام الطــرف الثانــي بدفــع ‪ %25‬مــن أصــل املبلــغ زيــادة علــى املبلــغ‬\n‫األصلــي) ‪ ،‬وقدرهــا ســبعة آالف وتســعمائة وســبعة ريــاالت ‪ ،‬وبقــي يف‬\n‫ذمتــه مــن مبلــغ الدعــوى مبلغــا قــدره اثنــان وثالثــون ألفــا وخمســمائة‬\n‫وثالثــون ريــاال‪ ،‬ولــم يدفــع املدعــى عليــه مــن ذلــك املبلــغ شــيئا حتــى‬\n‫اآلن‪ .‬هكــذا حلــف ‪ .‬فبنــاء علــى مــا تقــدم مــن الدعــوى والبينــة املتمثلــة‬\n‫يف الصــك رقــم ‪ 3557‬وتاريــخ ‪1420/12/27‬هــ‪ ،‬وعقــد اإليجــار رقــم‬\n‫‪ 11‬فئــة (أ) وتاريــخ ‪1432/9/1‬ه ـ ‪ ،‬وشــهادة ‪ ،..............‬ومحضــر‬\n‫اإلخــاء‪ ،‬وفاتــورة اســتهالك كهربــاء رقــم ‪ ، 24902‬وبنــاء علــى أن‬\n‫األصــل عــدم دفــع األجــرة ‪ ،‬وليمــن املدعــي علــى صحــة دعــواه وعــدم‬\n‫اســتالمه مــن مبلــغ الدعــوى شــيئا ‪ ،‬ولقولــه تعالــى (يــا أيهــا الذيــن آمنــوا‬\n‫أوفــوا بالعقــود) ‪ ،‬وحلديــث (املســلمون علــى شــروطهم) رواه الترمــذي‬\n‫وأبــو داوود ‪ ،‬وحلديــث (البينــة علــى املدعــي واليمــن علــى املدعــى عليــه)‬\n‫رواه الترمــذي ‪ ،‬قــال أبــو عيســى ‪ :‬العمــل عنــد أهــل العلــم مــن أصحــاب‬\n‫النبــي صلــى اهلل عليــه وســلم وغيرهــم أن البينــة علــى املدعــي واليمــن‬\n‫علــى املدعــى عليــه ‪ ،‬وملــا جــاء يف الفتــاوى مــا نصــه قــال شــيخ اإلســام‬\n‫(إذا كان الــذي عليــه احلــق قــادرا علــى الوفــاء وعطلــه حتــى أحوجــه إلــى‬\n\n\n                                                                                        ‫‪190‬‬\n\f      ‫الشــكاية فمــا غرمــه بســبب ذلــك فهــو علــى الظالــم املماطــل إذا غرمــه‬\n      ‫علــى الوجــه املعتــاد) ‪ ،24/300‬وهــو موافــق للشــرط املضمــن بالعقــد‬\n      ‫مــن حيــث املبــدأ‪ ،‬وبنــاء علــى املــادة ‪ 55‬و ‪ 5/176‬مــن نظــام املرافعــات‬\n      ‫الشــرعية‪ ،‬لذلــك كلــه‪ ،‬فقــد حكمــت علــى املدعــى عليــه‪ ...........‬بدفــع‬\n      ‫مبلــغ قــدره اثنــان وثالثــون ألفــا وخمســمائة وثالثــون ريــاال للمدعــي‬\n      ‫‪ ...........‬وبــه قنــع املدعــي‪ ،‬وقــررت بعــث املعاملــة حملكمــة االســتئناف‬\n      ‫لتدقيــق احلكــم لتعــذر العثــور علــى املدعــى عليــه‪ .‬وأقفلــت اجللســة‬\n      ‫الســاعة ‪ .02 : 40‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                    ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/07/17‬ه ـ‬\n      ‫احلمــد هلل‪ ،‬والصــاة والســام علــى رســول اهلل‪ ،‬وبعــد‪ .:‬فقــد‬\n      ‫جــرى اطالعنــا نحــن رئيــس وعضــوي الدائــرة احلقوقيــة الرابعــة يف‬\n      ‫محكمــة االســتئناف مبنطقــة مكــة املكرمــة علــى الصــك الصــادر‬\n      ‫مــن فضيلــة الشــيخ‪ .......‬القاضــي باحملكمــة العامــة بجــدة واملســجل‬\n      ‫بعــدد‪ 34271615‬وتاريــخ ‪1434/7/17‬ه ـ املتضمــن دعــوى ‪ .......‬ضــد‬\n      ‫‪ .......‬واحملكــوم فيــه مبــا دون باطنــة وبدراســة الصــك وصــورة ضبطــه‬\n      ‫تقــررت املوافقــة علــى احلكــم واملدعــي عليــه علــى حجتــه إذا حضــر‬\n                    ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪191‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"612f1ba9-3f27-52bc-993f-69d3ecdc8564","source_page_start":184,"source_page_end":191,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"f119e2076133a1638374c24f2193a49ca29814e168b2ab1567b413570d934d5f","normalized_text_hash":"2ee8d3c609e3430eedc002ef5dd1846ebbf1fb519706c5ac3888d6c6552fd1f3","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v7-p184-34271615"},{"id":"f912dc5f-1519-5730-bc23-6405cc4880d3","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقد -إجارة -إخاء عقار من غائب -سماع الدعوى غيابي ا لتعذر تبليغ املدعى عليه -البينة بشهادة الشهود املعدلن واليمني -وجوب الوفاء بالعقود -احلكم بفتح العن وإخالءها وحفظ محتويات العن يف بيت املال -بيع ما يخشى تلفه وإيداع ثمنه يف بيت املال -الغائب على حجته متى حضر .","document_number":"3463007","case_number":"34106198","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/15","year":"1434","subject":"عقد -إجارة -إخاء عقار من غائب -سماع الدعوى غيابي ا لتعذر تبليغ املدعى عليه -البينة بشهادة الشهود املعدلن واليمني -وجوب الوفاء بالعقود -احلكم بفتح العن وإخالءها وحفظ محتويات العن يف بيت املال -بيع ما يخشى تلفه وإيداع ثمنه يف بيت املال -الغائب على حجته متى حضر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/3/15 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪3463007 :‬‬\n                   ‫َر ْق ُم الدعوى‪34106198 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n           ‫‪ 34211510‬تاريخه‪1434/5/12:‬هـ‬\n\n\n‫عقــد ‪ -‬إجــارة ‪ -‬إخــاء عقــار مــن غائــب ‪-‬ســماع الدعــوى غيابيـ ًا لتعــذر‬\n‫تبليــغ املدعــى عليــه ‪-‬البينــة بشــهادة الشــهود املعدلــن واليمني ‪ -‬وجوب‬\n‫الوفــاء بالعقــود ‪ -‬احلكــم بفتــح العــن وإخالءهــا وحفــظ محتويــات‬\n‫العــن يف بيــت املــال ‪ -‬بيــع مــا يخشــى تلفــه وإيــداع ثمنــه يف بيــت املــال‬\n                                         ‫‪ -‬الغائــب علــى حجتــه متــى حضــر ‪.‬‬\n\n\n\n                      ‫‪ .1‬قوله تعالى (يا أيها الذين آمنوا أوفوا بالعقود)‪.‬‬\n‫‪ .2‬قولــه صلــى اهلل عليــه وســلم (املســلمون علــى شــروطهم) رواه‬\n                                                  ‫الترمــذي وأبــو داود‪.‬‬\n‫‪ .3‬قولــه صلــى اهلل عليــه وســلم (ال ضــرر وال ضــرار) رواه أبــو داود‬\n                                                   ‫وصححــه احلاكــم‪.‬‬\n‫‪ .4‬قولــه صلــى اهلل عليــه وســلم (البينــة علــى املدعــي واليمــن علــى‬\n                                         ‫املدعــى عليــه) رواه الترمــذي‪.‬‬\n                    ‫‪ .5‬املادة ‪ 55‬و ‪ 5/176‬من نظام املرافعات الشرعية‪.‬‬\n\n\n\n‫ادعــى املدعــي ضــد املدعــى عليــه الغائب عن مجلــس احلكم بأن املدعى‬\n‫عليــه اســتأجر منــه بيــت شــعبي يف ‪ ...‬حــي ‪ ...‬ملــدة ســنة اعتبــارا مــن تاريــخ‬\n\n                                                                                         ‫‪192‬‬\n\f      ‫‪1433/11/4‬ه ـ بأجــرة شــهرية قدرهــا ألــف ومائتــان وخمســون ريــاال ‪،‬‬\n      ‫وقــد دفــع املدعــى عليــه أجــرة شــهرين مــن تاريــخ العقــد ‪ ،‬ثــم انقطــع‬\n      ‫عــن الســداد‪ ،‬ومنــذ شــهر محــرم لعــام ‪1434‬ه ـ واملدعــى عليــه متغيــب‪،‬‬\n      ‫ولتضــرره مــن حرمانــه مــن االنتفــاع بالعقــار وعــدم دفــع املدعــى عليــه‬\n      ‫ألجــرة العقــار‪ ،‬يطلــب احلكــم بفتــح العقــار عــن طريــق اجلهــات املختصــة‬\n      ‫وإخــاء املدعــى عليــه منــه هكــذا ادعــى‪ ،‬مت البحــث عــن املدعــى عليــه‬\n      ‫لتبليغــه ولــم يعثــر عليــه حســب إفــادة الشــرطة‪ ،‬بنــاء علــى املــادة ‪ 55‬مــن‬\n      ‫نظــام املرافعــات الشــرعية ولتعــذر تبليــغ املدعــى عليــه تقــرر النظــر يف‬\n      ‫الدعــوى غيابي ـ ًا ‪ ،‬بينــة املدعــي عقــد اإليجــار وشــاهدان شــهدا طبــق‬\n      ‫دعــواه‪ ،‬حلــف املدعــي اليمــن بعــد طلبهــا منــه علــى صحــة دعــواه وعلــى‬\n      ‫عــدم اســتالمه األجــرة بعــد الشــهرين التاليــن لبدايــة العقــد ‪-‬لتغيــب‬\n      ‫املدعــى عليــه ولقولــه تعالــى (يــا أيهــا الذيــن آمنــوا أوفــوا بالعقــود)‬\n      ‫وقولــه صلــى اهلل عليــه وســلم (املســلمون علــى شــروطهم) رواه الترمــذي‬\n      ‫وأبــو داوود وقولــه صلــى اهلل عليــه وســلم ( ال ضــرر و ال ضــرار )‪ ،‬ملــا‬\n      ‫تقــدم احلكــم بفتــح العقــار محــل الدعــوى وإخــاؤه عــن طريــق اجلهــات‬\n      ‫املختصــة ‪ ،‬واالحتفــاظ مبوجــودات العقــار مــا يخــص املدعــى عليــه منــه‬\n      ‫لــدى اجلهــة املعنيــة ‪ ،‬وبيــع مــا يخشــى تلفــه ‪ ،‬وإيــداع ثمنــه لــدى بيــت‬\n      ‫مــال احملكمــة وتســليم املدعــي عقــاره ليتمكــن مــن االنتفــاع بــه‪ ،‬جــرى‬\n      ‫إفهــام املدعــي بــأن املدعــى عليــه علــى حجتــه متــى حضــر‪ ،‬بعــث املعاملــة‬\n      ‫حملكمــة االســتئناف لتدقيــق احلكــم‪ ،‬صــدق احلكــم مــن الدائــرة‬\n            ‫احلقوقيــة الثالثــة مبحكمــة االســتئناف مبنطقــة مكــة املكرمــة ‪.‬‬\n\n\n\n\n‫‪193‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.......‬القاضــي يف احملكمــة العامــة‬\n‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة مبحافظــة جدة‪/‬املســاعد برقــم ‪ 34106198‬وتاريــخ‬\n‫‪1434/03/03‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34533438‬وتاريــخ‬\n‫‪1434/03/01‬ه ـ ففــي يــوم األحــد املوافــق ‪1434/03/15‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪ 02 : 00‬وفيهــا حضــر املدعــي ‪.......‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم ‪.......‬ولــم يحضــر املدعــى عليــه ‪.......‬‬\n‫باكســتاني اجلنســية مبوجــب اإلقامــة رقــم ‪.......‬وال مــن ميثلــه ‪ ،‬وقــد‬\n‫وردنــا خطــاب مديــر شــرطة محافظــة جــدة برقــم ‪25/1/20/1653‬‬\n‫وتاريــخ ‪1434/2/25‬ه ـ املتضمــن أن مت البحــث والتحــري عــن املســتأجر‬\n‫ولــم يعثــر عليــه ‪ .‬أه ـ فبنــاء علــى املــادة ‪ 55‬مــن نظــام املرافعــات الشــرعية‬\n‫‪ ،‬ولتعــذر تبليــغ املدعــى عليــه فقــد قــررت النظــر يف الدعــوى غيابيــا‬\n‫يف حــق املدعــى عليــه ‪ ،‬وادعــى املدعــي قائــا ‪ :‬لقــد اســتأجر املدعــى‬\n‫عليــه منــي عقــارا مملــوكا لــي مبوجــب وثيقــة مبايعــة أنقــاض برقــم‬\n‫‪ 126‬وتاريــخ ‪1425/4/20‬ه ـ علــى أوراق مؤسســة ‪ .......‬للمقــاوالت‬\n‫العامــة والعقــار وهــو عبــارة بيــت شــعبي يف ‪ ...‬حــي ‪ ...‬ويحــده مــن الشــمال‬\n‫حــوش ‪ ،.......‬ومــن اجلنــوب شــارع عــرض ‪ 8‬م ‪ ،‬ومــن الغــرب شــارع عــرض‬\n‫‪7‬م ومــن الشــرق ملــك ‪ ،‬ومبوجــب عــداد التيــار الكهربائــي املســجل‬\n‫باســمي حتــت رقــم املشــترك ‪ 10023‬للحســاب رقــم ‪ ،.......‬وقــد اســتأجر‬\n‫املدعــى عليــه ذلــك العقــار ملــدة ســنة اعتبــارا مــن تاريــخ ‪1433/11/4‬ه ـ‬\n‫بأجــرة شــهرية قدرهــا ألــف ومائتــان وخمســون ريــاال مبوجــب عقــد‬\n\n                                                                                         ‫‪194‬‬\n\f      ‫اإليجــار رقــم ‪ 0337‬وتاريــخ ‪1433/11/4‬ه ـ احملــرر علــى أوراق ‪.......‬‬\n      ‫للعقــار ‪ ،‬وقــد دفــع املدعــى عليــه أجــرة شــهرين مــن تاريــخ العقــد ‪ ،‬ثــم‬\n      ‫انقطــع عــن الســداد ‪ ،‬ومنــذ شــهر محــرم لعــام ‪1434‬ه ـ واملدعــى عليــه‬\n      ‫متغيــب ‪ ،‬ولتضــرري مــن حرمانــي مــن االنتفــاع بعقــاري وعــدم دفــع‬\n      ‫املدعــى عليــه ألجــرة العقــار ‪ ،‬أطلــب احلكــم بفتــح العقــار عــن طريــق‬\n      ‫اجلهــات املختصــة ومتكينــي مــن عقــاري وإخــاء املدعــى عليــه منــه ومــن‬\n      ‫مــا ميلكــه فيــه ‪ .‬هــذه دعــواي ‪ .‬ثــم أبــرز املدعــي صــورة مــن وثيقــة مبايعــة‬\n      ‫أنقــاض وأصــل فاتــورة اســتهالك تيــار كهربائــي للحســاب املذكــور يف‬\n      ‫الدعــوى برقــم ‪ 13666‬وأصــل عقــد اإليجــار املشــار إليهــا يف الدعــوى‬\n      ‫‪ ،‬ومت تزويــد أوراق املعاملــة بنســخة منهــا ‪ ،‬وبطلــب زيــادة بينــة مــن‬\n      ‫املدعــي علــى صحــة دعــواه أحضــر للشــهادة وأدائهــا كال مــن ‪.......‬‬\n      ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪.......‬وهــو مــن مواليــد‬\n      ‫‪1394‬ه ـ ويعمــل يف ‪ ، ...‬ويســكن يف حــي ‪.......‬مبحافظــة جــدة ‪ ،‬وهــو‬\n      ‫أخ للمدعــي‪ ....... ،‬فلســطيني اجلنســية بوثيقــة مصريــة مبوجــب اإلقامــة‬\n      ‫رقــم ‪.......‬وهــو مــن مواليــد ‪1386‬ه ـ ويعمــل يف مؤسســة ‪ ،.......‬ويســكن‬\n      ‫يف حــي ‪.......‬مبحافظــة جــدة ‪ ،‬وليــس بينــه وبــن الطرفني قرابة ‪ ،‬وشــهد‬\n      ‫كل واحــد منهمــا مبفــرده قائــا ‪ :‬أشــهد بــاهلل العظيــم بــأن املدعــي‬\n      ‫‪.......‬مالــك للعقــار محــل الدعــوى ‪ ،‬وأن املدعــى عليــه ‪ ..............‬كان‬\n      ‫مســتأجرا لذلــك العقــار ‪ ،‬وأن املدعــى عليــه متغيــب منــذ حوالــي شــهرين‬\n      ‫‪ ،‬والعقــار محــل الدعــوى مغلــق منــذ تغيــب املدعــى عليــه ‪ .‬هكــذا شــهدا‬\n      ‫‪ .‬وعــدال مــن قبــل ‪.......‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n      ‫‪.......‬و‪.......‬مينــي اجلنســية مبوجــب اإلقامــة رقــم ‪ ........‬وبعــرض اليمــن‬\n      ‫علــى املدعــي علــى صحــة دعــواه وعــدم اســتالمه ألجــرة العقــار محــل‬\n\n\n‫‪195‬‬\n\f‫الدعــوى بعــد الشــهرين التاليــن لبدايــة عقــد اإليجــار ولتغيــب املدعــى‬\n‫عليــه ‪ ،‬اســتعد لذلــك ‪ ،‬ثــم حلــف قائــا ‪ :‬واهلل العظيــم الــذي ال إلــه إال‬\n‫هــو أننــي أملــك عقــارا مبوجــب وثيقــة مبايعــة أنقــاض برقــم ‪ 126‬وتاريــخ‬\n‫‪1425/4/20‬ه ـ علــى أوراق مؤسســة ‪ .......‬للمقــاوالت العامــة والعقــار‬\n‫وهــو عبــارة بيــت شــعبي يف كيلــو ‪ 7‬حــي (‪ ،)....‬ومبوجــب عــداد التيــار‬\n‫الكهربائــي املســجل باســمي حتــت رقــم املشــترك ‪ 10023‬للحســاب‬\n‫رقــم ‪ ، 252591609‬وقــد اســتأجر املدعــى عليــه ‪ .......‬ذلــك العقــار ملــدة‬\n‫ســنة اعتبــارا مــن تاريــخ ‪1433/11/4‬ه ـ بأجــرة شــهرية قدرهــا ألــف‬\n‫ومائتــان وخمســون ريــاال مبوجــب عقــد اإليجــار رقــم ‪ 0337‬وتاريــخ‬\n‫‪1433/11/4‬ه ـ احملــرر علــى أوراق ‪.......‬للعقــار ‪ ،‬وقــد دفــع املدعــى عليه‬\n‫أجــرة شــهرين مــن تاريــخ العقــد ‪ ،‬ثــم انقطــع عــن الســداد ‪ ،‬ومنــذ شــهر‬\n‫محــرم لعــام ‪1434‬ه ـ واملدعــى عليــه متغيــب ‪ .‬هكــذا حلــف فبنــاء علــى‬\n‫مــا تقــدم مــن الدعــوى والبينــة املتمثلــة يف وثيقــة مبايعــة أنقــاض برقــم‬\n‫‪ 126‬وتاريــخ ‪1425/4/20‬ه ـ ‪ ،‬وفاتــورة اســتهالك التيــار الكهربائــي‬\n‫رقــم ‪ 13666‬للمشــترك ‪ 10023‬باحلســاب رقــم ‪ ، 252591609‬وعقــد‬\n‫اإليجــار رقــم ‪ 0337‬وتاريــخ ‪1433/11/4‬ه ـ ‪ ،‬ومــا شــهد بــه الشــاهدان‬\n‫‪....... .......‬واملعدلــة شــهادتهما مــن قبــل كل مــن ‪ ،.......‬وبنــاء علــى‬\n‫خطــاب مديــر شــرطة محافظــة جــدة برقــم ‪ 25/1/20/1653‬وتاريــخ‬\n‫‪1434/2/25‬ه ـ ‪ ،‬ولقولــه تعالــى (يــا أيهــا الذيــن آمنــوا أوفــوا بالعقــود) ‪،‬‬\n       ‫وحلديــث (املســلمون علــى شــروطهم) رواه الترمــذي وأبــو داوود ‪،‬‬\n‫وحلديث ( ال ضرر و ال ضرار ) رواه أبو داوود وصححه احلاكم ‪ ،‬وألن‬\n‫الضــرر يف الشــريعة مرفــوع ‪ ،‬وحلديــث (البينــة علــى املدعــي واليمــن‬\n‫علــى املدعــى عليــه) رواه الترمــذي ‪ ،‬قــال أبــو عيســى ‪ :‬العمــل عنــد أهــل‬\n\n\n                                                                                    ‫‪196‬‬\n\f      ‫العلــم مــن أصحــاب النبــي صلــى اهلل عليــه وســلم وغيرهــم أن البينــة علــى‬\n      ‫املدعــي واليمــن علــى املدعــى عليــه ‪ ،‬وبنــاء علــى املــادة ‪ 55‬و ‪ 5/176‬مــن‬\n      ‫نظــام املرافعــات الشــرعية ‪ ،‬لذلــك كلــه ‪ ،‬فقــد حكمــت بفتــح العقــار‬\n      ‫محــل الدعــوى وإخــاؤه عــن طريــق اجلهــات املختصــة‪ ،‬واالحتفــاظ‬\n      ‫مبوجــودات العقــار مــا يخــص املدعــى عليــه منــه لــدى اجلهــة املعنيــة ‪،‬‬\n      ‫وأمــرت ببيــع مــا يخشــى تلفــه ‪ ،‬وإيــداع ثمنــه لــدى بيــت مــال احملكمــة‪،‬‬\n      ‫وتســليم املدعــي عقــاره ليتمكــن مــن االنتفــاع بــه ‪ .‬وبــه حكمــت‪.‬‬\n      ‫وأفهمــت املدعــي بــأن املدعــى عليــه علــى حجتــه متــى حضــر‪ ،‬وقــررت‬\n      ‫بعــث املعاملــة حملكمــة االســتئناف لتدقيــق احلكــم ‪ .‬وأقفلــت اجللســة‬\n      ‫الســاعة ‪ . 02 : 30‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                       ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/03/15‬ه ـ‬\n      ‫احلمد هلل ‪ ،‬والصالة والسالم على رسول اهلل ‪ ،‬وبعد ‪ :‬ـ فقـد جـرى م ّنا‬\n      ‫نح ــن رئيس وأعضاء الدائ ــرة احلقوقي ــة الثالثة يف محكم ــة االستئناف‬\n      ‫مبنطقة مك ــة املكرم ــة االطال ُع عل ــى هـذا الصك الصـادر من فضيـلة‬\n      ‫الشي ــخ ‪ .......‬القاضــي باحملكمــة العامــة مبحافظــة جــدة واملســجل‬\n      ‫بعــدد ‪ 3463007‬وتــاري ــخ ‪1434/3/15‬ه ـ املتضمــن دعــوى ‪ .....‬ضــد‬\n      ‫‪ ( .......‬باكســتاني اجلنســية ) يف عقــار احملكــوم فيــه مبــا دون باطنــه‪.‬‬\n      ‫وبــدراس ــة احلك ــم وص ــورة ضبط ــه تقـ ـ ـ ـ ــررت املـ ــوافقـ ـ ـ ــة علــى احلكــم‬\n      ‫والغائــب علــى حجتــه واهلل املوفــق وصل ــى اهلل عل ــى نبي ــنا محم ــد وعل ــى‬\n                                                                         ‫آل ــه وصحبـه وسـلم‪.‬‬\n\n\n\n\n‫‪197‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"612f1ba9-3f27-52bc-993f-69d3ecdc8564","source_page_start":192,"source_page_end":197,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"2f316ea0f4d6f3866f4f2a16cd0634076b9750e5cb8f92161f9fa1b923f8ac2d","normalized_text_hash":"27121781410bc3d2fb1049f624651cdc323ffc62cec8932594081682ec8312af","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v7-p192-3463007"},{"id":"6bfda33b-1522-514b-ad8a-bb65012a7e48","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقد -إجارة -إخاء عقار النتهاء مدته -إخطار باإلخاء - املسلمون على شروطهم -إقرار املدعى عليه بالدعوى -احلكم","document_number":"34182875","case_number":"34110084","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالدمام","circuit":"الدائرة احلقوقية الثانية رقم 34255062يف 1434/06/28ه وللبيان","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/8","year":"1434","subject":"عقد -إجارة -إخاء عقار النتهاء مدته -إخطار باإلخاء - املسلمون على شروطهم -إقرار املدعى عليه بالدعوى -احلكم","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1434/4/8 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34182875 :‬‬\n                   ‫َر ْق ُم الدعوى‪34110084 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n           ‫‪ 34255062‬تاريخه‪1434/6/28 :‬هـ‬\n\n\n‫عقــد ‪ -‬إجــارة ‪ -‬إخــاء عقــار النتهــاء مدتــه ‪-‬إخطــار باإلخــاء ‪-‬‬\n‫املســلمون علــى شــروطهم ‪ -‬إقــرار املدعــى عليــه بالدعــوى ‪ -‬احلكــم‬\n                                                      ‫بإخــاء العقــار‪.‬‬\n\n\n\n\n              ‫‪ .1‬قوله صلى اهلل عليه وسلم (( املسلمون على شروطهم ))‬\n                               ‫‪ .2‬القاعدة الفقهية ( ال عذر ملن اقر )‬\n\n\n\n\n‫ادعــى املدعــي بالوكالــة بــأن املدعــى عليــه اســتأجر مــن موكلــه‬\n‫شــقة ذكــر وصفهــا يف نــص القضيــة ملــدة ســنة قابلــة للتجديــد اعتبــار ًا‬\n‫مــن ‪1430/3/24‬ه ـ وقــد انتهــت مــدة العقــد وطالــب املدعــي أصالــة‬\n‫مــن املدعــى عليــه إخــاء الشــقة قبــل نهايــة العقــد بســتة أشــهر لعــدم‬\n‫رغبتــه بالتجديــد لكــن املدعــى عليــه رفــض اإلخــاء وطلــب احلكــم‬\n‫علــى املدعــى عليــه بإخــاء العقــار‪ ،‬أجــاب املدعــى عليــه باملصادقــة‬\n‫علــى الدعــوى وذكــر انــه لــن يخــرج إال بعــد أن يجــد لــه عقــار ًا آخــر‬\n‫‪-‬مت اطــاع ناظــر القضيــة علــى عقــد اإليجــار وصــك امللكيــة‪ ،‬صــدر‬\n‫ـاء علــى قولــه صلــى اهلل عليه وســلم (( املســلمون‬‫حكــم ناظــر القضيــة بنـ ً‬\n‫علــى شــروطهم )) و إلقــرار املدعــى عليــه باحلكــم علــى املدعــى عليــه‬\n\n                                                                                   ‫‪198‬‬\n\f      ‫بإخــاء العقــار فــور ًا وتســليمه للمدعــي بحالتــه الســليمة‪ ،‬قــرر املدعــى‬\n      ‫عليــه املعارضــة‪ ،‬صــدر قــرار محكمــة االســتئناف باملنطقــة الشــرقية‬\n                                                       ‫باملصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا‪ ...........‬القاضــي يف احملكمــة العامــة‬\n      ‫بالدمــام وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بالدمــام املســاعد برقــم ‪ 34110084‬وتاريــخ ‪1434/03/07‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 34577647‬وتاريــخ ‪1434/03/07‬ه ـ حضــر‬\n      ‫‪...........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‪ ...........‬بصفتــه‬\n      ‫وكيــا عــن املدعــي مبوجــب الوكالــة الصــادرة عــن كتــاب العــدل‬\n      ‫اجلفــر رقــم ‪.........‬مجلــد ‪ 1098‬بتاريــخ ‪1428/01/10‬ه ـ واملخــول‬\n      ‫لــه فيهــا باملطالبــة واملرافعــة واملخاصمــة وغيرهــا وحضــر حلضــوره‬\n      ‫‪ ...........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‪ ...........‬وادعــى‬\n      ‫األول قائــا اســتأجر هــذا احلاضــر معــي وأشــار إلــى املدعــى عليــه مــن‬\n      ‫موكلــي شــقة مكونــة مــن أربــع غــرف ودورتــن للميــاه ومطبــخ وصالــة‬\n      ‫ورقمهــا واحــد (‪ )1‬يف العقــار الكائــن بحــي ‪.........‬مبدينــة الدمــام‬\n      ‫واململــوك ملوكلــي مبوجــب الصــك الصــادر مــن كتابــة عــدل الدمــام‬\n      ‫األولــى برقــم ‪ 930106005923‬يف ‪1428/01/08‬ه ـ بأجــرة ســنوية‬\n      ‫قدرهــا اثنــان وعشــرون ألــف ريــال ملــدة ســنة قابلــة للتجديــد اعتبــارا‬\n      ‫مــن ‪ 1430/03 /24‬ه ـ وذلــك مبوجــب العقــد الصــادر مــن مكتــب‬\n      ‫‪ .........‬للخدمــات العقاريــة برقــم ‪ 953‬يف ‪1430/03/24‬ه ـ وقــد انتهــت‬\n      ‫املــدة يف ‪1434/03 /24‬ه ـ وطلــب منــه موكلــي إخــاء الشــقة قبلهــا‬\n\n‫‪199‬‬\n\f‫بســتة أشــهر لعــدم رغبــة موكلــي يف التجديــد لــه إال أنــه رفــض ولــذا‬\n‫وحيــث انتهــت مــدة اإليجــار ولــم يقــم باإلخــاء فأطلــب إلــزام املدعــى‬\n‫عليــه بإخــاء الشــقة املوصوفــة وتســليمها ملوكلــي حــاال هــذه دعــواي‬\n‫وبعــرض الدعــوى علــى املدعــى عليــه أجــاب بقولــه‪ :‬مــا ذكــره املدعــي‬\n‫وكالــة كلــه صحيــح فقــد اســتأجرت مــن موكلــه الشــقة املوصوفــة‬\n‫يف الدعــوى باألجــرة التــي ذكرهــا املدعــي وكالــة وقــد انتهــى العقــد‬\n‫يف‪1434/03/24‬ه ـ وصحيــح بــأن موكلــه أشــعرني باإلخــاء قبــل‬\n‫نهايتــه بســتة أشــهر إال أننــي لســت مســتعد باإلخــاء إال بعــد ســتة أشــهر‬\n‫مــن اآلن لكــي أمتكــن مــن البحــث عــن شــقة بديلــة هكــذا أجــاب وبــرد‬\n‫ذلــك علــى املدعــي وكالــة قــال موكلــي ال يوافــق علــى طلبــه ويطلــب‬\n‫إلزامــه باإلخــاء فــورا وقــد جــرى منــي االطــاع علــى العقــد املشــار إليــه‬\n‫بعــد أن أبــرزه املدعــي وكالــة فوجدتــه مطابقــا ملــا ذكــره كمــا اطلعــت‬\n‫علــى أصــل الصــك املشــار إليــه فوجدتــه مملــوكا للمدعــي أصالــة‬\n‫املدعــو فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وحيــث طلــب املدعــي‬\n‫وكالــة إلــزام املدعــى عليــه بإخــاء الشــقة املوصوفــة يف الدعــوى‬\n‫واململوكــة ملوكلــه النتهــاء العقــد و عــدم رغبــة موكلــه يف جتديــده‬\n‫وحيــث أقــر املدعــى عليــه باالســتئجار ومقــدار األجــرة وانتهــاء العقــد‬\n‫وإشــعاره باإلخــاء قبــل انتهائــة بســتة أشــهر وحيــث ال عــذر ملــن أقــر‬\n‫ولقولــه صلــى اهلل عليــه وســلم املســلمون علــى شــروطهم لــذا وجلميــع مــا‬\n‫تقــدم فقــد ألزمــت املدعــى عليــه بــأن يخلــي الشــقة املوصوفــة يف الدعــوى‬\n‫فــورا ويســلمها للمدعــي أصالــة بحالتهــا الســليمة ومبــا تقــدم حكمــت‬\n‫وبعــرض احلكــم عليــه قــرر اعتراضــه عليــه وطلــب االســتئناف بــدون‬\n‫تقــدمي الئحــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n\n\n                                                                                     ‫‪200‬‬\n\f                                     ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/04/07‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فقــد جــرى املصادقــة علــى هــذا احلكــم الصــادر‬\n      ‫منــا يف هــذه القضيــة وذلــك مبوجــب قــرار أصحــاب الفضيلــة قضــاة‬\n      ‫الدائــرة احلقوقيــة الثانيــة رقــم ‪ 34255062‬يف ‪1434/06/28‬ه ـ وللبيــان‬\n      ‫جــرى حتريــره وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد ‪.‬حــرر يف‬\n                                                                       ‫‪1434/07/09‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة احلقوقيــة‬\n      ‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة املقيــدة‬\n      ‫لــدى احملكمــة برقــم ‪ 341349347‬وتاريــخ ‪1434/ 6/5‬ه ـ الــواردة مــن‬\n      ‫فضيلــة رئيــس احملكمــة العامــة مبدينــة الدمــام برقــم ‪341074162‬‬\n      ‫وتاريــخ ‪1434/5/12‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة القاضي‬\n      ‫باحملكمــة الشــيخ‪ /‬املســجل برقــم ‪ 34182875‬وتاريــخ ‪1434/4/8‬ه ـ‬\n      ‫بشــأن دعــوى‪ /‬ضــد‪ /‬يف قضيــة حقوقيــة وقــد تضمــن الصــك حكــم‬\n      ‫فضيلــة القاضــي مبــا هــو مــدون ومفصــل فيــه ‪ .‬وبدراســة الصــك وصــورة‬\n      ‫ضبطــه وأوراق املعاملــة قررنــا املصادقــة علــى احلكم واهلل املوفق وصلى‬\n          ‫اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم حــرر يف‪1434/6/28‬ه ـ ‪.‬‬\n\n\n\n\n‫‪201‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"612f1ba9-3f27-52bc-993f-69d3ecdc8564","source_page_start":198,"source_page_end":201,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"6f03ff6c9adc19901e1dea4073cea32cc2577250afd298ed3bd51287ff065451","normalized_text_hash":"4c1ddbfbee8d6b0d6a9f17d9aa13fabd9efcd4ab3002043f145ce58c4efde8c6","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v7-p198-34182875"},{"id":"0928b3d1-b63e-5584-9dfd-97dd8fb0de22","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقد -إجارة -مطالبة بقيمة حتسينات -األصل يف الشروط احلل -ما يقوم به املستأجر من حتسينات ال تلزم املؤجر إذا نص العقد على ذلك -وجوب الوفاء بالعقود -رد دعوى املدعى .","document_number":"34203864","case_number":"34128028","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/1","year":"1434","subject":"عقد -إجارة -مطالبة بقيمة حتسينات -األصل يف الشروط احلل -ما يقوم به املستأجر من حتسينات ال تلزم املؤجر إذا نص العقد على ذلك -وجوب الوفاء بالعقود -رد دعوى املدعى .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/5/1 :‬هـ‬\n                ‫ُ‬                 ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34203864 :‬‬\n                   ‫َر ْق ُم الدعوى‪34128028 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n          ‫‪ 34366025‬تاريخه‪1434/11/23:‬هـ‬\n\n\n‫عقــد ‪ -‬إجــارة ‪ -‬مطالبــة بقيمــة حتســينات ‪ -‬األصــل يف الشــروط احلــل‬\n‫‪ -‬مــا يقــوم بــه املســتأجر مــن حتســينات ال تلــزم املؤجــر إذا نــص العقــد‬\n              ‫علــى ذلــك‪ -‬وجــوب الوفــاء بالعقــود ‪ -‬رد دعــوى املدعــى ‪.‬‬\n\n\n\n\n                     ‫‪ -1‬قوله تعالى {يا أيها الذين امنوا أوفوا بالعقود}‪.‬‬\n              ‫‪ -2‬قوله صلى اهلل عليه وسلم ( املسلمون على شروطهم ) ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي ضــد املدعــى عليــه بأنــه اســتأجر مــن املدعــى عليــه بيت ـ ًا‬\n‫شــعبي ًا مرفق ـ ًا بــه ثــاث محــات يف حــي ‪ .......‬بجــدة بأجــرة قدرهــا‬\n‫عشــرون ألــف ريــال وقــام بعمــل حتســينات باحملــل كلفتــه مبلــغ وقــدره‬\n‫خمســة وخمســون ألف ريال وطلب منه املدعى عليه بعدم جتديد العقد‬\n‫ويطالــب بإلزامــه بتعويضــه عــن اخلســارة التــي تكبدهــا يف التحســينات‬\n‫وقدرهــا خمســة وخمســون ألــف ريــال هكــذا ادعــى‪ ،‬أجــاب املدعــى‬\n‫عليــه بإنــكار عمــل التحســينات مــن قبــل املدعــي وأن الــذي قــام بــه هــو‬\n‫عمــل فتحــة واحــدة بــدون علمــه وال إخطار كتابي وأنه ال يســتحق شــيء‬\n‫ويطلــب رد الدعــوى‪ ،‬ليــس للمدعــي بينــة علــى أن املدعــى عليــه يلتــزم‬\n‫بدفــع التعويضــات‪ ،‬أضــاف املدعــى عليــه بــأن املــادة اخلامســة مــن عقــد‬\n\n                                                                                     ‫‪202‬‬\n\f      ‫اإليجــار تنــص ( بــأن ال يحــق للمســتأجر إجــراء أي تغييــر يف الواجهــات‬\n      ‫اخلارجيــة أو الترتيبــات الداخليــة إال بعــد احلصــول علــى موافقــة خطيــة‬\n      ‫مــن املالــك ‪ ...‬كل هــذا بــدون حــق مطالبــة الطــرف الثانــي للطــرف األول‬\n      ‫بــأي تعويــض علمــا بــأن كل اإلصالحــات والتغييــرات التــي ســيوافق‬\n      ‫عليهــا املؤجــر خطيــا تكــون علــى نفقــة املســتأجر بكاملهــا)‪ ،‬بنــاء‬\n      ‫علــى املــادة اخلامســة مــن العقــد املبــرم بــن الطرفــن‪ ،‬ولقولــه تعالــى ‪:‬‬\n      ‫(يــا أيهــا الذيــن امنــوا أوفــوا بالعقــود )‪ ،‬وألن األصــل يف الشــروط احلــل‬\n      ‫ولقولــه صلــى اهلل عليــه وســلم ‪ ( :‬املســلمون علــى شــروطهم )‪ ،‬ملــا تقــدم‬\n      ‫صــدر احلكــم بــرد دعــوى املدعــي لعــدم اســتحقاقه مــا يدعيــه‪ ،‬قنــع‬\n      ‫املدعــى عليــه باحلكــم واعتــرض املدعــي بالئحــة‪ ،‬صــدق احلكــم بعــد‬\n      ‫مداولــة مــن الدائــرة احلقوقيــة الثالثــة مبحكمــة االســتئناف مبنطقــة‬\n                                                                  ‫مكــة املكرمــة‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.......‬القاضــي يف احملكمــة العامــة‬\n      ‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة العامــة مبحافظــة جدة‪/‬املســاعد برقــم ‪ 34128028‬وتاريــخ‬\n      ‫‪1434/03/17‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34617355‬وتاريــخ‬\n      ‫‪1434/03/10‬ه ـ ففــي يــوم األربعــاء املوافق‪1434/05/01‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة ‪ 11 : 30‬وفيهــا حضــر املدعــي أصالــة ‪.......‬ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪.......‬وحضــر حلضــوره املدعــى‬\n      ‫عليــه أصالــة ‪.......‬ســعودي بالســجل رقــم ‪.......‬وبســؤال املدعــي عــن دعــواه‬\n      ‫أفــاد قائــا ‪ :‬لقــد قمــت باســتئجار بيــت شــعبي مــن دوريــن وبــه مرفــق‬\n\n‫‪203‬‬\n\f‫ثــاث محــات مــن املدعــى عليــه ‪.......‬يف حــي ‪.......‬بجــدة مببلــغ وقــدره‬\n‫عشــرون ألــف ريــال وكنــت ملتــزم بااليجــارات وقمــت بعمــل حتســينات‬\n‫يف هــذه احملــات كلفتنــي خمســة وخمســون ألــف ريــال ثــم قــام املدعــى‬\n‫عليــه ‪.......‬وطلــب منــي عــدم جتديــد العقــد أطلــب إلزامــه بتعويضــي عــن‬\n‫اخلســارات التــي تكبدتهــا يف التحســينات وهــي مبلــغ وقــدره خمســة‬\n‫وخمســون ألــف ريــال ودفعهــا لــي هــذه دعــواي وبعرضهــا علــى املدعــى‬\n‫عليــه أجــاب قائــا ‪ :‬مــا ذكــره املدعــي يف دعــواه غيــر صحيــح واملدعــي‬\n‫قــام بعمــل فتحــة واحــدة بــدون علمنــا وال إخطــار كتابــي منــا وعليــه فهــو‬\n‫ال يســتحق شــيئا لــذا أطلــب رد دعــوى املدعــي هكــذا أجــاب ثــم جــرى‬\n‫االطــاع علــى عقــد اإليجــار الــذي بــن الطرفــن فوجــدت البنــد اخلامــس‬\n‫يتضمــن مــا نصــه ‪ :‬ال يحــق للمســتأجر إجــراء أي تغييــر يف الواجهــات‬\n‫اخلارجيــة أو الترتيبــات الداخليــة إال بعــد احلصــول علــى موافقــة خطيــة‬\n‫مــن املالــك أو مــن ينــوب عنــه وإال كان علــى نفقتــه إعــادة املــكان‬\n‫املؤجــر إلــى حالتــه التــي كان عليهــا إمــا فــورا وإمــا عنــد انتهــاء عقــد‬\n‫اإليجــار وتســليم املــكان املؤجــر وهــذا االختيــار حســب رغبــة الطــرف‬\n‫األول ‪ ....‬كل هــذا بــدون حــق مطالبــة الطــرف الثانــي للطرف األول بأي‬\n‫تعويــض علمــا بــأن كل اإلصالحــات والتغييــرات التــي ســيوافق عليهــا‬\n‫املؤجــر خطيــا تكــون علــى نفقــة املســتأجر بكاملهــا أ ‪ .‬ه ـ وبســؤال‬\n‫املدعــي عــن بينتــه علــى أن املدعــى عليــه قــد التــزم بتعويضــه عمــا قــام‬\n‫بــه مــن إصالحــات أجــاب قائــا ‪ :‬ال بينــة لــدي علــى ذلــك هكــذا أجــاب‬\n‫وبعرضــه علــى املدعــى عليــه أجــاب قائــا ‪ :‬إن املــادة اخلامســة مــن العقــد‬\n‫تضمنــت مــا نصــه‪ ( :‬كل هــذا بــدون حــق مطالبــة الطــرف الثانــي‬\n‫للطــرف األول بــأي تعويــض علمــا بــأن كل االصالحــات والتغييــرات‬\n\n\n                                                                                     ‫‪204‬‬\n\f      ‫التــي ســيوافق عليهــا املؤجــر خطيــا تكــون علــى نفقــة املســتأجر‬\n      ‫بكاملهــا ) وقــد حاولــت الصلــح بــن الطرفــن فأصــر املدعــى عليــه على‬\n      ‫رفضــه عليــه فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة ومبــا أن املدعــي‬\n      ‫حصــر دعــواه يف املطالبــة بتعويضــه عمــا قــام بــه مــن حتســينات وذلــك‬\n      ‫مببلــغ وقــدره خمســة وخمســون ألــف ريــال ومبــا أن املدعــى عليــه أنكــر‬\n      ‫دعــوى املدعــي جملــة وتفصيــا ومبــا أن العقــد الــذي بــن الطرفــن‬\n      ‫قــد نــص كمــا يف املــادة اخلامســة منــه (كل هــذا بــدون حــق مطالبــة‬\n      ‫الطــرف الثانــي للطــرف األول بــأي تعويــض علمــا بــأن كل االصالحــات‬\n      ‫والتغييــرات التــي ســيوافق عليهــا املؤجــر خطيــا تكــون علــى نفقــة‬\n      ‫املســتأجر بكاملهــا) ولقولــه تعالــى ‪( :‬يــا أيهــا الذيــن أمنــوا أوفــوا‬\n      ‫بالعقــود ) اآليــة وألن األصــل يف الشــروط احلــل ولقولــه صلــى اهلل عليــه‬\n      ‫وســلم ‪ ( :‬املســلمون علــى شــروطهم) وجلميــع مــا تقــدم فقــد حكمــت بــرد‬\n      ‫دعــوى املدعــي لعــدم اســتحقاقه مــا يدعيــه وبعرضــه علــى الطرفــن قــرر‬\n      ‫املدعــى عليــه القناعــة وقــرر املدعــي عــدم القناعــة وطلــب االســتئناف‬\n      ‫فأجيــب إلــى طلبــه وجــرى تســليمه نســخة مــن احلكــم لالعتــراض عليــه‬\n      ‫خــال ثالثــن يومــا تبــدأ مــن تاريــخ احلكــم وإذا انتهــت مــدة االعتــراض‬\n      ‫ولــم يتقــدم بالالئحــة االعتراضيــة فيســقط حقــه يف طلــب االســتئناف‬\n      ‫ويكتســب احلكــم القطعيــة وأغلقــت اجللســة الســاعة ‪ 12 : 00‬وبــاهلل‬\n      ‫التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر‬\n                                                               ‫يف ‪1434/05/01‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.......‬القاضــي يف احملكمــة العامــة‬\n      ‫مبحافظــة جــدة ففــي يــوم األحــد املوافق‪1434/10/25‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة ‪ 08 : 30‬وفيهــا حضــر املدعــي أصالــة ‪.......‬املدونــة هويتــه‬\n\n\n‫‪205‬‬\n\f‫ســابقا ولــم يحضــر املدعــى عليــه ‪.......‬ولــم يردنــا مــا يفيــد تبلغــه وقــد‬\n‫عــادت لنــا املعاملــة مــن محكمــة االســتئناف مبكــة املكرمــة بخطــاب‬\n‫فضيلــة رئيســها رقــم ‪ 34617355‬وتاريــخ ‪1434/06/18‬ه ـ واملتضمنــة‬\n‫القــرار الصــادر مــن الدائــرة احلقوقيــة الثالثــة يف محكمــة االســتئناف‬\n‫برقــم ‪ 34237805‬وتاريــخ ‪1434/06/12‬ه ـ والــذي نصــه بعــد املقدمــة‪:‬‬\n‫( وبدراســة احلكــم وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر إعادتهــا‬\n‫لفضيلتــه ملالحظــة أنــه ذكــر يف الالئحــة مــا يوجــب فتــح جلســة‬\n‫والتأكــد منــه وهــو وجــود موافقــة خطيــة فهــل هــذا ثابــت ‪ ..‬إلــخ وإجــراء‬\n‫املقتضــى الشــرعي نحــوه وبــاهلل التوفيــق قاضــي اســتئناف ‪ .......‬توقيــع‬\n‫وقاضــي اســتئناف ‪.......‬توقيــع ورئيــس الدائــرة صقــر املــدرع توقيــع) أ ‪ .‬هـ‬\n‫وعليــه أجيــب أصحــاب الفضيلــة وفقهــم اهلل لطاعتــه وهداهــم ملرضاتــه‬\n‫أنــه بســؤال املدعــي مــن املوافقــة اخلطيــة التــي ذكرهــا أجــاب قائــا ‪:‬‬\n‫إن بينتــي هــي مــا ورد يف اخلطــاب الصــادر مــن املدعــى عليــه ‪.......‬بتاريــخ‬\n‫‪1433/11/23‬هـ ونصه ‪ ( :‬اتعهد أنا ‪ ....‬مبساعدة السيد ‪.......‬ومتكينه‬\n‫مــن حتصيــل جميــع إيجاراتــه املتبقيــة لــدى ســكان بيــت عمتــي ‪.......‬يف‬\n‫حــي ‪.......‬واعطــاءه مهلــة إلــى آخــر شــهر محــرم ‪ 1434‬الســتالم البيــت‬\n‫منــه ومــن حــق ‪.......‬اغــاق احمللــن الــذي اســتحدثهم يف البيــت وهــذا‬\n‫تعهــد منــا بذلــك ‪.......‬توقيــع) أ ‪ .‬ه ـ وبســؤاله هــل لديــك بينــة أخــرى أجاب‬\n‫قائــا ‪ :‬ال ليــس لــدي بينــة أخــرى وباالطــاع علــى هــذا اخلطــاب لــم أجــد‬\n‫فيــه مــا يــدل علــى إذن املدعــى عليــه للمدعــي باســتحداث احمللــن اللذين‬\n‫يطالــب املدعــي بالتعويــض عــن اخلســائر التــي تكبدهــا وعليــه فلــم أجــد‬\n‫تأثيــرا علــى مــا حكمــت بــه ســابقا أمــرت باحلــاق ذلــك علــى صكــه‬\n‫وســجله وإعادتــه إلــى محكمــة االســتئناف وأغلقــت اجللســة الســاعة ‪00‬‬\n\n\n                                                                                       ‫‪206‬‬\n\f      ‫‪ 09 :‬وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                  ‫وســلم ‪ .‬حــرر يف ‪1434/10/25‬ه ـ ‪.‬‬\n      ‫احلمد هلل ‪ ،‬والصالة والسالم على رسول اهلل ‪ ،‬وبعد ‪ :‬ـ فقـد جـرى م ّنا‬\n      ‫نح ــن رئيس وأعضاء الدائ ــرة احلقوقي ــة الثالثة يف محكم ــة االستئناف‬\n      ‫مبنطقــة مك ــة املكرم ــة االطــا ُع عل ــى ه ــذا الصــك الص ــادر مــن‬\n      ‫فضي ــلة الشــيخ ‪.......‬القاضــي باحملكمــة العامــة بجــدة املســجل بعــدد‬\n      ‫‪.......‬وتاريــخ ‪1434/05/01‬ه ـ املتضمــن دعــوى ‪ .......‬ضــد ‪.......‬يف مبلــغ‬\n      ‫مالــي احملكــوم فيــه مبــا دون باطنــه وبــدراس ــة احلكــم وصــورة ضبطــه‬\n      ‫والئحتــه االعتراضيــة تقـ ـ ـ ـ ــررت املـ ــوافقـ ـ ـ ــة علــى احلكــم بعــد اإلجــراء‬\n      ‫االخيــر وبــاهلل تعالــى التوفيــق وصل ــى اهلل عل ــى نبي ــنا محم ــد وعل ــى آل ــه‬\n                                                                              ‫وصحب ــه وسـلم ‪.‬‬\n\n\n\n\n‫‪207‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"612f1ba9-3f27-52bc-993f-69d3ecdc8564","source_page_start":202,"source_page_end":207,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d210023f9b795ea67e47c2da7760b94e9151f3e31f45d7553640f1bd37aa1b51","normalized_text_hash":"b7c061ea6be4db1d321352c88cb81b2b8dc3c2e262a4bf922d8830ead604c103","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v7-p202-34203864"},{"id":"69eb2376-4810-576f-a363-3c1118a50f6c","document_type":"judgment","category":"judicial","subcategory":"general","title":"إجارة -املطالبة بتنفيذ العقد -انتقال العن من مالك آلخر ال يلغي العقود املتعلقة بالعن -وجوب الوفاء بالعقود -شراء العن ال يسري على املنفعة إال بعد انتهاء مدة عقد اإليجار -احلكم بتسليم العن حتى نهاية مدة العقد .","document_number":"34191964","case_number":"34152805","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة الرس","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/20","year":"1434","subject":"إجارة -املطالبة بتنفيذ العقد -انتقال العن من مالك آلخر ال يلغي العقود املتعلقة بالعن -وجوب الوفاء بالعقود -شراء العن ال يسري على املنفعة إال بعد انتهاء مدة عقد اإليجار -احلكم بتسليم العن حتى نهاية مدة العقد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/4/20 :‬هـ‬\n                 ‫ُ‬                 ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪34191964 :‬‬\n                    ‫َر ْق ُم الدعوى‪34152805 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n            ‫‪ 34219690‬تاريخه‪1434/5/22:‬هـ‬\n\n\n‫إجــارة ‪ -‬املطالبــة بتنفيــذ العقــد ‪ -‬انتقــال العــن مــن مالــك آلخــر ال‬\n‫يلغــي العقــود املتعلقــة بالعــن ‪ -‬وجــوب الوفــاء بالعقــود ‪ -‬شــراء العــن‬\n‫ال يســري علــى املنفعــة إال بعــد انتهــاء مــدة عقــد اإليجــار ‪ -‬احلكــم‬\n                                ‫بتســليم العــن حتــى نهايــة مــدة العقــد ‪.‬‬\n\n\n\n\n                             ‫قوله تعالى {يا أيها الذين آمنوا أوفوا بالعقود}‪.‬‬\n\n\n\n\n‫ا جتاريـ ًا‬\n          ‫ادعــى املدعــي ضــد املدعــى عليــه بأنــه اســتأجر مــن املالــك محـ ً‬\n‫علــى طريــق ‪ ...........‬مقابــل ‪ ...‬علــى أن يبــدأ اإليجار بتاريخ ‪1432/4/1‬هـ‬\n‫وينتهــي يف ‪1435/4/1‬ه ـ بقيمــة ثمانيــة آالف للســنة الواحــدة وقــد قــام‬\n‫املدعــى عليــه يف يــوم األحــد املوافــق ‪1434/3/29‬ه ـ وقبــل أن يحــل‬\n‫اإليجــار بيــوم واحــد بالتهجــم علــى احملــل وأخبــره العامــل بــأن املدعــى‬\n‫عليــه يقــول‪ :‬عليــك أن تدفــع واحــد ًا وعشــرين ألــف ريــال بــدل املتفــق‬\n‫عليــه بالعقــد أو يطلــب منــه اخلــروج مــن احملــل وبعــد عــدة ســاعات أتــى‬\n‫للمحــل وأقفلــه بقفــل حديــدي ويطلــب إلــزام املدعــى عليــه بتنفيــذ موجب‬\n‫العقــد املبــرم بينهمــا هكــذا ادعــى‪ ،‬أجــاب املدعــى عليــه باملصادقــة‬\n‫علــى الدعــوى وأنــه اشــترى الــدكان مــن املالــك األصلــي يف شــهر‬\n\n                                                                                     ‫‪208‬‬\n\f      ‫جمــادى اآلخــرة مــن الســنة املاضيــة‪ ،‬وحيــث صــادق املدعــى عليــه علــى‬\n      ‫دعــوى املدعــي وبعــد االطــاع علــى أصــل عقــد الــدكان وأصــل صــك‬\n      ‫ملكيــة العقــار وحيــث أن انتقــال العــن مــن مالــك آلخــر ال يلغــي العقــود‬\n      ‫املتعلقــة بالعــن حيــث أن املســتأجر ميلــك منفعــة الــدكان حتــى نهايــة‬\n      ‫العقــد لقولــه تعالــى ( يــا أيهــا الذيــن آمنــو أوفــوا بالعقــود) وألن شــراء‬\n      ‫املدعــى عليــه وقــع علــى ذات العــن ولــم يقــع علــى منفعتهــا النشــغالها‬\n      ‫بعقــد ســابق فــا يســري علــى املنفعــة إال بعــد انتهــاء عقــد اإليجــار‪ ،‬ملــا‬\n      ‫تقــدم صــدر احلكــم علــى املدعــى عليــه بــأن يســلم الــدكان للمدعــي‬\n      ‫حتــى نهايــة العقــد املذكــور يف الدعــوى يف ‪1435/4/1‬ه ـ ‪ -‬قنــع املدعي‬\n      ‫باحلكــم واعتــرض املدعــى عليــه بالئحــة‪ ،‬صــدق احلكــم مــن الدائــرة‬\n                     ‫احلقوقيــة األولــى مبحكمــة االســتئناف مبنطقــة القصيــم ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.......‬القاضــي يف احملكمــة العامــة‬\n      ‫مبحافظــة الــرس وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة العامــة مبحافظــة الــرس برقــم ‪ 34152805‬وتاريــخ‬\n      ‫‪ 1434/04/03‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34813522‬وتاريــخ‬\n      ‫‪ 1434/04/03‬ه ـ ففــي يــوم األربعــاء املوافق‪ 1434/04/17‬هـ افتتحت‬\n      ‫اجللســة الســاعة ‪ 08 : 00‬وفيهــا حضــر ‪.......‬ســعودي اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم ‪.......‬وحضــر حلضــوره ‪.......‬ســعودي بالســجل رقــم‬\n      ‫ال جتاري ًا‬\n               ‫‪.......‬وادعــى االول قائــا اســتأجرت مــن املالك الســابق ‪.......‬مح ً‬\n      ‫علــى طريــق ‪ ...........‬املدينــة ســابقا مقابــل بــرج ‪.......‬بالعقــد الصــادر مــن‬\n      ‫مكتــب ‪.......‬بتاريــخ ‪1432/1/20‬ه ـ علــى ان يبــدأ االيجــار بتاريــخ‬\n\n‫‪209‬‬\n\f‫‪1432/4/1‬ه ـ وينتهــي يف ‪1435/4/1‬ه ـ بقيمــة ثمانيــة االف للســنة‬\n‫الواحــدة وقــد قــام املدعــى عليــه يف يــوم االحــد املوافــق ‪1434/3/29‬ه ـ‬\n‫وقبــل ان يحــل االيجــار بيــوم واحــد بالتهجــم علــى احملــل وابلغنــي العامــل‬\n‫ان املدعــى عليــه يقــول ‪ :‬ان عليــك ان تدفــع واحــدا وعشــرين الــف ريــال‬\n‫بــدل املتفــق عليــه بالعقــد او يطلــب منــي اخلــروج مــن احملــل وبعــد عــدة‬\n‫ســاعات اتــى للمحــل واقفلــه بقفــل حديــدي ويف نفــس اليــوم مت ابــاغ‬\n‫شــرطة الــرس بذلــك وحضــر البحــث اجلنائــي ومت رصــد الواقعــة لديهــم‬\n‫بالصــور اطلــب الــزام املدعــى عليــه بتنفيــذ موجــب العقــد املبــرم بيننــا‬\n‫هــذه دعــواي هكــذا ادعــى وبعــرض دعــوى املدعــي علــى املدعــى عليــه‬\n‫اجــاب قائــا ماذكــره املدعــي مــن اســتئجار الــدكان الواقــع يف شــارع‬\n‫امللك ‪.......‬مقابل مؤسســة ‪ ...‬من تاريخ ‪1432/4/1‬هـ الى ‪1435/4/1‬هـ‬\n‫كمــا جــاء بالعقــد املرفــق رقــم ‪ 1426‬يف ‪1432/1/20‬ه ـ كلــه صحيــح‬\n‫وقــد اشــتريت الــدكان مــن املالــك االصلــي يف شــهر جمــادى االخــرة مــن‬\n‫الســنة املاضيــة مــن املســمى ‪.......‬وقــد اغلقــت بــاب الــدكان ألن اســعار‬\n‫االيجــارات مرتفعــة فقلــت لــه إمــا ان يكــون االيجــار واحــدا وعشــرين‬\n‫الــف ريــال او تخــرج مــن الــدكان هــذه اجابتــي هكــذا اجــاب فبناء على‬\n‫ماتقــدم مــن الدعــوى واالجابــة وحيــث صــادق املدعــى عليــه علــى دعــوى‬\n‫املدعــي وبعــد االطــاع علــى اصــل عقــد الــدكان املتضمــن (مت االتفــاق‬\n‫بــن الطرفــن ‪.......‬طــرف اول و‪.......‬طــرف ثانــي ان يســتأجر الطــرف‬\n‫الثانــي ورشــة ‪ ...‬الشــارع ‪........‬مقابــل بــرج ‪ ...‬مــدة االيجــار ثــاث ســنوات‬\n‫بــدا مــن تاريــخ ‪1432/4/1‬ه ـ حتــى ‪1435/4/1‬ه ـ االيجــار الســنوي‬\n‫‪ 8000‬ريــال ســعودي ) ورخصــة احملــل املتضمنــة ( رقــم الرخصــة ‪.......‬‬\n‫يف ‪1420/1/5‬ه ـ وتنتهــي يف ‪1435/1/5‬ه ـ اســم صاحب الرخصة ‪.......‬‬\n\n\n                                                                                       ‫‪210‬‬\n\f      ‫االســم التجــاري محــل ‪ )....... .......‬وباالطــاع علــى أصــل صــك ملكيــة‬\n      ‫العقــار رقــم ‪ 93‬وتاريــخ ‪1433/5/15‬ه ـ املتضمــن (حضــر علــي ‪.......‬‬\n      ‫اصيــا عــن نفســه ووكالــة عــن ورثــة والــده وقــرر بطوعــه واختيــاره‬\n      ‫انــه اجلــاري يف ملكــي وحتــت تصــريف الــدكان رقــم ‪ 3‬الواقــع باجلهــة‬\n      ‫الغربيــة مــن محافظــة الــرس وقــد بعتــه ‪.‬ل‪ )......‬ومت االستفســار عــن‬\n      ‫ســريان مفعولــه برقــم ‪ 34952827‬وتاريــخ ‪1434/4/17‬ه ـ تبــن انــه‬\n      ‫الصــك ســاري املفعــول والتوجــد عليــه مالحظــات وكذلــك الصــك رقــم‬\n      ‫‪ 94‬يف ‪1433/5/15‬ه ـ املتضمــن (حضــر ‪.......‬اصيــا عن نفســه ووكالة‬\n      ‫عــن ورثــة والــده وقــرر بطوعــه واختيــاره انــه اجلــاري يف ملكــي وحتــت‬\n      ‫تصــريف الــدكان رقــم ‪ 2‬الواقــع باجلهــة الغربيــة مــن محافظــة الــرس وقــد‬\n      ‫بعتــه ل‪ ).......‬ومت االستفســار عــن ســريان مفعولــه برقــم ‪349527777‬‬\n      ‫يف ‪1434/4/17‬ه ـ تبــن انــه الصــك ســاري املفعــول والتوجــد عليــه‬\n      ‫مالحظــات وحيــث ان انتقــال العــن مــن مالــك آلخــر اليلغــي العقــود‬\n      ‫املتعلقــة بالعــن حيــث ان املســتأجر ميلــك منفعــة الــدكان حتــى نهايــة‬\n      ‫العقــد لقولــه تعالــى ( ياأيهــا الذيــن امنــو اوفــوا بالعقــود ) وألن شــراء‬\n      ‫املدعــى عليــه وقــع علــى ذات العــن ولــم يقــع علــى منفعتهــا إلنشــغالها‬\n      ‫بعقــد ســابق فاليســري علــى املنفعــة اال بعــد انتهــاء عقد االيجــار لذا فقد‬\n      ‫حكمــت علــى املدعــى عليــه بــأن يســلم الــدكان للمدعــي حتــى نهايــة‬\n      ‫العقــد املذكــور يف الدعــوى يف ‪1435/4/1‬ه ـ وبعــرض ماحكمــت بــه‬\n      ‫علــى الطرفــن قــرر املدعــي قناعتــه باحلكــم وقــرر املدعــى عليــه عــدم‬\n      ‫القناعة وافهمته بأن يحضر يف يوم الســبت الســتالم نســخة من احلكم‬\n      ‫لتقــدمي الالئحــة االعتراضيــة ففهــم ذلــك وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n      ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/04/17‬هـ‬\n\n\n‫‪211‬‬\n\f‫احلمــد هلل وحــده والصــاة والســام علــى نبينــا محمــد وعلــى آلــه‬\n‫وصحبــه وبعــد‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة احلقوقيــة األولــى‬\n‫مبحكمــة االســتئناف مبنطقــة القصيــم علــى املعاملــة الــواردة مــن‬\n‫فضيلــة رئيــس احملكمــة العامــة مبحافظــة الــرس برقــم(‪)34813522‬‬\n‫وتاريــخ ‪1434/5/6‬ه ـ ؛ احملالــة إلينــا برقــم (‪ )34214668‬؛ املرفــق بهــا‬\n‫الصــك املســجل برقــم(‪ ).......‬وتاريــخ ‪1434/4/20‬ه ـ ؛ الصــادر مــن‬\n‫فضيلــة الشــيخ‪......./‬القاضي باحملكمــة؛ اخلــاص بدعــوى ‪.......‬ضــد‬\n‫‪ ........‬بشــأن تنفيــذ عقــد مبــرم حملــل عقــار ‪ .‬وقــد تضمــن الصــك حكــم‬\n‫فضيلتــه بــأن علــى املدعــى عليــه أن يســلم الــدكان للمدعــي حتــى نهايــة‬\n‫العقــد املذكــور يف الدعــوى يف‪1435/4/1‬ه ـ ‪ .‬علــى النحــو املفصــل‬\n‫فيــه‪ .‬وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق‬\n‫املعاملــة نقــرر املصادقــة علــى احلكــم اهلل املوفــق‪ ،‬وصلــى اهلل وســلم‬\n                                    ‫علــى نبينــا محمــد وآلــه وصحبــه وســلم‪.‬‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.......‬القاضــي يف احملكمــة‬\n‫العامــة مبحافظــة الــرس وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n‫رئيــس احملكمــة العامــة مبحافظــة الــرس برقــم ‪34152805‬‬\n‫وتاريــخ ‪1434/04/03‬ه ـ املقيــدة باحملكمــة برقــم ‪34813522‬‬\n‫وتاريــخ ‪1434/04/03‬ه ـ ‪.......‬ضــد ‪ .......‬ففــي يــوم اخلميــس‬\n‫املوافق‪1434/10/15‬ه ـ افتتحــت اجللســة الســاعة ‪ 10.15‬وفيهــا وردت‬\n‫املعاملــة مــن رئيــس دائــرة التنفيــذ باحملكمــة العامــة مبحافظــة الــرس‬\n‫برقــم ‪342110908‬يف ‪1434/9/2‬ه ـ واملتضمــن اســتالم املدعــي‬\n‫الــدكان املطالــب بــه والصــادر بــه الصــك الشــرعي رقــم ‪34191964‬‬\n‫يف ‪1434/4 /20‬ه ـ وبهــذا ليــس للمدعــي اي شــئ بخصــوص هــذه‬\n\n\n                                                                                  ‫‪212‬‬\n\f      ‫القضيــة وامــرت بالتهميــش علــى ضبطــه وســجله حتــى ال يخفــى وبــاهلل‬\n      ‫التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر‬\n                                                             ‫يف ‪ 1434/10/15‬ه ـ‬\n\n\n\n\n‫‪213‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"612f1ba9-3f27-52bc-993f-69d3ecdc8564","source_page_start":208,"source_page_end":213,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"2bc3c6dc4472fc1f347bd72bc80f14ff4e12479e5287289cd302f53b725e7dab","normalized_text_hash":"c35bef4e573ee2adacba31033d979e3764f09ef12dc6fb24033725b71e9778f8","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v7-p208-34191964"},{"id":"794bcb94-f800-51b9-973b-b525ec3b0aea","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقد -اجاره -مطالبه بأجره مدة بقاء املستأجر بعد انتهاء العقد- مطالبه بالتعويض عن التأخير يف اخاء املبنى -تقدير األجرة عن طريق قسم اخلبراء -الضرر املضمون هو الضرر الواقع فقط وليس الضرر املتوقع -احلكم بسداد قيمة األجرة املستحقة -عدم استحقاق التعويض قال البهوتي يف شرح املنتهى ( 122/4وال يضمن ربح فات على مالك بحبس غاصب مال جتارة مدة ميكن أن يتجر فيها إذا لم","document_number":"34300352","case_number":"34154268","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/8/17","year":"1434","subject":"عقد -اجاره -مطالبه بأجره مدة بقاء املستأجر بعد انتهاء العقد- مطالبه بالتعويض عن التأخير يف اخاء املبنى -تقدير األجرة عن طريق قسم اخلبراء -الضرر املضمون هو الضرر الواقع فقط وليس الضرر املتوقع -احلكم بسداد قيمة األجرة املستحقة -عدم استحقاق التعويض قال البهوتي يف شرح املنتهى ( 122/4وال يضمن ربح فات على مالك بحبس غاصب مال جتارة مدة ميكن أن يتجر فيها إذا لم","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/8/17 :‬هـ‬\n                ‫ُ‬                  ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪34300352 :‬‬\n                    ‫َر ْق ُم الدعوى‪34154268 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34346377‬تاريخه‪1434/11/2 :‬هـ‬\n\n\n‫عقــد ‪ -‬اجــاره ‪ -‬مطالبــه بأجــره مــدة بقــاء املســتأجر بعــد انتهــاء العقد‪-‬‬\n‫مطالبــه بالتعويــض عــن التأخيــر يف اخــاء املبنــى ‪ -‬تقديــر األجــرة‬\n‫عــن طريــق قســم اخلبــراء ‪ -‬الضــرر املضمــون هــو الضــرر الواقــع فقــط‬\n‫وليــس الضــرر املتوقــع ‪ -‬احلكــم بســداد قيمــة األجــرة املســتحقة ‪ -‬عــدم‬\n                                                          ‫اســتحقاق التعويــض‬\n\n\n\n\n‫قــال البهوتــي يف شــرح املنتهــى ‪( 122/4‬وال يضمــن ربــح فــات علــى‬\n‫مالــك بحبــس غاصــب مــال جتــارة مــدة ميكــن أن يتجــر فيهــا إذا لــم‬\n     ‫يتجــر فيــه الغاصــب) وينظــر شــرح املنتهــى البــن النجــار ‪215/5‬‬\n\n\n\n\n‫ادعــى املدعــي وكالــة ضــد املدعــى عليــه مبطالبتــه باألجــرة والتعويــض‬\n‫عــن الضــرر لتأخــره يف إخــاء املبنــى ‪ -‬حيــث اســتأجر املدعــى عليــه‬\n‫املبنــى ملــدة ســنة تنتهــي يف ‪1432/12/30‬ه ـ ومت جتديــد العقــد ملــدة‬\n‫ســتة أشــهر تنتهــي يف ‪1433/6/30‬ه ثــم بــاع املالــك علــى املدعــي املبنــى‬\n‫وقبــل نهايــة الســتة أشــهر طلــب املدعــي مــن املدعــى عليــه إخــاء املبنــى‬\n‫بنهايــة الســتة أشــهر ولكــن املدعــى عليــه لــم يخلــه وأكمــل حتــى‬\n‫‪1433/12/18‬ه ـ يطالــب املدعــي بأجــرة قدرهــا أربعمائــة وخمســون‬\n\n                                                                                    ‫‪214‬‬\n\f      ‫ألــف ريــال وتعويــض عــن الضــرر يف التأخــر عــن إخــاء املبنــى مببلــغ‬\n      ‫قــدره مليــون وخمســمائة وخمســون ألــف ريــال وذلــك ألن موكلــه أراد‬\n      ‫هــدم املبنــى وبنــاء فنــدق لتأجيــره يف حــج عــام ‪1434‬ه ـ ‪ ،‬أجــاب املدعــى‬\n      ‫عليــه وكالــة باملصادقــة علــى عقــد اإليجــار ومتديــد العقــد ملــدة ســنة‬\n      ‫وليــس ســتة أشــهر وأن املالــك الســابق اســتلم أجــرة الســتة أشــهر وأن‬\n      ‫موكلــه تلقــى خطاب ـ ًا مــن املالــك األول ببيــع العقــار وتنبيهــه باإلخــاء‬\n      ‫بعــد نهايــة الســتة أشــهر وأن مديــر معــرض موكلــه تلقــى فاكــس‬\n      ‫مــن املالــك اجلديــد يطلــب فيــه اإلخــاء وأن ليــس للمدعــي ســوى مبلــغ‬\n      ‫مائتــن وخمســة وعشــرون ألــف ريــال املتبقــي مــن أجــرة الســتة أشــهر‬\n      ‫للســنة الثانيــة وان التعويــض يف الشــريعة يكــون عــن ضــرر مالــي واقــع‬\n      ‫كمــا أن اخلطــأ منتفــي عــن موكلــه فقــد انتفــع بالعــن حتــى نهايــة‬\n      ‫املــدة احملــددة هكــذا أجــاب‪ ،‬عقــد اإليجــار بــن املالــك األول واملدعــى‬\n      ‫عليــه ملــدة ســنة ولــم يذكــر فيــه جتــدد العقــد تلقائي ـاً‪ ،‬رخصــة البنــاء‬\n      ‫لــم تصــدر إال بتاريــخ ‪1434/3/25‬ه ـ مت تقديــر األجــرة عــن طريــق‬\n      ‫قســم اخلبــراء بانهــا مبلــغ أربعمائــة وثمانــون ألــف ريــال لــم يقنــع املدعــى‬\n      ‫عليــه وكالــة بالتقديــر‪ ،‬وأمــا املدعــي وكالــة فقــرر مبطالبتــه مببلــغ‬\n      ‫أربعمائــة وخمســن ألــف ريــال دون مــا قدرتــه هيئــة النظــر ‪ ،‬وألن هــذا‬\n      ‫العقــد نــص علــى أن مــدة العقــد ســنه واحــدة وهــي لعــام ‪1432‬ه ـ فقــط‬\n      ‫دون اإلشــارة إلــى جتــدده تلقائيــا وحيــث جــرى إبــاغ البائــع للمدعــى‬\n      ‫عليــه بالبيــع وإمهالــه للخــروج حتــى ‪1433/6/30‬ه ـ كمــا تضمــن أيضــا‬\n      ‫الســند املوقــع مــن البائــع باســتالم األجــرة أن هــذه األجــرة للمــدة مــن‬\n      ‫‪1432/1/1‬ه ـ حتــى ‪1433/6/30‬ه ـ فقــط وكذلــك مطالبــة املشــتري‬\n      ‫للمدعــى عليــه باخلــروج بعــد انتهــاء املــدة وألن املدعــي أصالــة قــدر أجــرة‬\n\n\n‫‪215‬‬\n\f‫املــدة مــن ‪1433/7/1‬ه ـ بأربعمائــة وخمســن ألــف ريــال وطالــب بهــذا‬\n‫املبلــغ وهــو أقــل ممــا قدرتــه هيئــة النظــر كمــا طالــب بتعويضــه عــن‬\n‫التأخيــر يف هــدم املوقــع وبنــاء عمــارة عليــه وتأجيرهــا ملوســم احلــج لهــذا‬\n‫العــام ‪1434‬ه ـ وألن الضــرر املضمــون هــو الضــرر الواقــع أمــا الربــح‬\n‫الفائــت والضــرر غيــر املتوقــع فهــو غيــر مضمــون كمــا قــرر ذلــك أهــل‬\n‫العلــم ينظــر شــرح املنتهــى ‪ ،122/4‬صــدر احلكــم بإلــزام املدعــى عليــه‬\n‫بدفــع أجــرة املــدة مــن ‪1433/7/1‬ه ـ حتــى تاريــخ اإلخــاء مبلــغ وقــدره‬\n‫أربعمائــة وخمســون ألــف ريــال وعــدم اســتحقاق املدعــي للتعويــض الــذي‬\n‫يطالــب بــه ‪ ،‬اعتــرض الطرفــان بالئحــة ‪ ،‬صــدق احلكــم مــن الدائــرة‬\n     ‫احلقوقيــة الثالثــة مبحكمــة االســتئناف مبنطقــة مكــة املكرمــة‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .......‬القاضــي باحملكمــة العامــة‬\n‫مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة مبكــة املكرمــة املقيــدة باحملكمــة برقــم‬\n‫‪ 34821159‬وتاريــخ ‪1434/04/03‬ه ـ وفيهــا حضــر املدعــي وكالــة‬\n‫‪.......‬ســجل مدنــي رقــم ‪ .......‬بوكالتــه عــن ‪.......‬بصفتــه الوكيــل‬\n‫الشــرعي عــن أخيــه ‪.......‬بالوكالــة الصــادرة مــن كتابــة عــدل بريــدة‬\n‫الثانيــة برقــم ‪ 5681/43997‬يف ‪1433/8/17‬ه ـ والتــي تخولــه املطالبــة‬\n‫واملداعــاة واملخاصمــة وســماع الدعــاوي والــرد عليهــا ‪..‬الــخ كمــا حضــر‬\n‫‪.......‬ســجل مدنــي رقــم ‪.......‬بوكالتــه عــن أوالد ‪.......‬بصفتهــم شــركاء‬\n‫يف شــركة ‪.......‬وشــركاه بالوكالــة الصــادرة مــن كتابــة عــدل الثانيــة‬\n‫بجنــوب الريــاض برقــم ‪ 2617/4779‬يف ‪1430/1/16‬ه ـ والتــي تخولــه‬\n\n                                                                                      ‫‪216‬‬\n\f      ‫املرافعــة واملدافعــة ‪..‬الــخ قائــا يف دعــواه عليــه بتاريــخ ‪1433/3/1‬ه ـ‬\n      ‫اشــترى موكلــي العقــار الواقــع بالعزيزيــة علــى طريــق الطائــف الهــدا‬\n      ‫احملــدود واملــذروع مبوجــب الصــك الصــادر مــن كتابــة العــدل مبكــة‬\n      ‫املكرمــة برقــم ‪/106‬أ يف ‪1400/3/17‬ه ـ وكان مؤجــرا مــن املالــك‬\n      ‫الســابق علــى شــركة ‪.......‬وشــركاه (‪ ).......‬وعقــد االيجــار يتنهــي يف‬\n      ‫‪1433/6/30‬ه ـ وقــد مت ابــاغ الشــركة باإلخــاء يف ذلــك التاريــخ‬\n      ‫بواســطة مديــر فــرع الشــركة مبكــة املكرمــة ‪.......‬ووقــع خطابــا‬\n      ‫بالتــزام الشــركة باإلخــاء يف املوعــد احملــدد ولكــن الشــركة لــم‬\n      ‫تخــل املوقــع وبقيــت فيــه حتــى ‪1433/12/18‬ه ـ فأطلــب الــزام الشــركة‬\n      ‫بدفــع اجــرة املــدة مــن ‪1433/7/1‬ه ـ حتــى ‪1433/12/3‬ه ـ وقدرهــا‬\n      ‫أربعمائــة وخمســون الــف ريــال كمــا أنــه بســبب تأخــر الشــركة يف‬\n      ‫االخــاء أدى ذلــك الــى ضــرر موكلــي فلــم يبــدأ بهــدم املوقــع واعــادة‬\n      ‫بنائــه وكان مــن املقــرر أنــه ســيبدأ بالهــدم فــور االخــاء ومــن ثــم بنــاء‬\n      ‫فندقــا يؤجــر يف حــج هــذا العــام ‪1434‬ه ـ وتأخــر الشــركة يف االخــاء‬\n      ‫ادى الــى فــوات ذلــك علــى موكلــي وموكلــي يطلــب الــزام الشــركة‬\n      ‫بدفــع مليــون وخمســمائه وخمســن مقابــل هــذا الضــرر هــذه دعــواي‬\n      ‫وبســؤال املدعــي عليــه وكالــه عــن دعــوى املدعــي وكالــه اجــاب بورقــه‬\n      ‫هــذا نصهــا ‪ -:‬أتقــدم لفضيلتكــم مبذكــرة الــرد علــى دعــوى املدعــي‬\n                            ‫‪.......‬بالوكالــة عــن ‪ .......‬والــذي يطلــب مبقتضاهــا‪:‬‬\n      ‫‪ .1‬أجــرة املــدة مــن ‪1433/7/1‬ه ـ وحتــى ‪1433/12/30‬ه ـ وقدرهــا‬\n                                                   ‫أربعمائــة وخمســون ألــف ريــال‪.‬‬\n      ‫‪ .2‬تعويضــه عــن التأخيــر يف إخــاء املبنــى وبالتالــي تأخــر هــدم املعــرض‬\n      ‫وبنائــه فنــدق وتأجيــره يف حــج عــام ‪1434‬ه ـ ممــا فـ ّـوت عليــه مبلــغ مليــون‬\n\n\n‫‪217‬‬\n\f‫وخمســمائة وخمســون ألــف ريــال ‪ .‬الوقائــع والدفــاع ‪ -:‬مبوجــب عقــد‬\n‫إيجــار محــرر يف ‪1432/1/1‬ه ـ جــدد ورثــة ‪ .......‬مــرزا إجــارة املعــرض‬\n‫العائــد ملورثهــم إلــى شــركة مجموعــة ‪ .......‬لســنة أخــرى تنتهــي يف‬\n‫‪1432/12/30‬ه ـ وبأجــرة ســنوية مقدارهــا (‪ )450.000‬أربعمائــة‬\n                                     ‫وخمســون ألــف ريــال (مســتند رقــم ‪. )1‬‬\n‫‪ .3‬وبعــد انقضــاء مــدة هــذا العقــد اســتمر الطرفــان يف تنفيــذه بشــغل‬\n‫املســتأجر العــن وقبــض املؤجــر ألجــرة القســط األول مــن األجــرة‬\n‫الســنوية ( مســتند رقــم ‪ ، ) 2‬تلقــي مديــر املعــرض خطــاب مــن وكيــل‬\n‫ورثــة املؤجــر بتاريــخ ‪1433/2/24‬ه ـ مفــاده أن موكليــه باعــوا العــن‬\n‫املســتأجرة (املعــرض) محــل عقــد اإليجــار وانتهــى إلــى طلــب اإلخــاء يف‬\n‫موعــد أقصــاه ‪1433/6/30‬ه ـ وذلــك بتســليمه للمالــك اجلديــد ( مســتند‬\n‫رقــم ‪ . ) 3‬وملــا كان مــن املســلم بــه شــرع ًا ؟ أن بيــع العــن املســتأجرة‬\n‫ينصــب علــى الرقبــة وال ينصــرف إلــى املنفعــة لتملــك املســتأجر لهــا‬\n‫وكانــت إجــارة موكلــي للعــن تنتهــي يف ‪1433/12/30‬ه ـ فقــد‬\n‫كان طبيعي ـ ًا أن يســتمر موكلــي يف االنتفــاع بالعــن املســتأجرة حتــى‬\n                                                                ‫‪1433/12/30‬ه ـ ‪.‬‬\n‫‪ .4‬وبتاريــخ ‪1433/8/7‬ه ـ املوافــق ‪2012/6/27‬م تلقــي مديــر املعــرض‬\n‫فاكــس بتوقيــع ‪( .......‬املالــك اجلديــد) يطلــب فيــه إخــاء املبنــى يف‬\n‫مــدة أقصاهــا خمســة أيــام مــن تاريخــه ‪ ( .‬مســتند رقــم ‪ ) 4‬وملــا كان‬\n‫مــن املســلم بــه شــرع ًا ؟ أن امللــك ينتقــل إلــى مــن خلــف البائــع يف مالــه‬\n‫ويتلقــى امللــك عنــه فــا اعتــراض لــه علــى عقــوده بــل هــو منفــذ لهــا وذلــك‬\n‫كالــوارث واملشــتري ؟ ومــن ثــم فــإن املالــك اجلديــد لــم يكــن لــه احلــق يف‬\n‫طلبــه إخــاء العــن قبــل انتهــاء مــدة اإلجــارة يف ‪1433/12/30‬ه ـ ‪ .‬ممــا‬\n\n\n                                                                                        ‫‪218‬‬\n\f                                                       ‫يتقــدم يتضــح لفضيلتكــم ‪:‬‬\n      ‫أو ًال ‪:‬أن كل مــا للمدعــي (املالــك اجلديــد) أجــرة النصــف الثانــي مــن‬\n      ‫مــدة اإلجــارة ومقدارهــا (‪ ) 225.000‬مائتــان وخمســة وعشــرون ألــف‬\n                                                                              ‫ريــال ‪.‬‬\n      ‫ثاني ـ ًا ‪:‬أنــه ال أســاس لطلــب املدعــى تعويضــه عــن الضــرر الــذي يدعيــه‬\n      ‫ليــس فقــط النتفــاء اخلطــأ يف جانــب املدعــي عليــه (ألن اجلــواز الشــرعي‬\n      ‫ينــايف الضمــان ) واملدعــى عليــه اســتعمل حقــه يف االنتفــاع بالعــن محــل‬\n      ‫اإلجــارة حتــى نهايــة املــدة احملــددة لدفــع األجــرة ‪ ،‬وإمنــا كذلــك ألن‬\n      ‫ا‬ ‫التعويــض يف الفقــه اإلســامي ال يكــون إال عــن ضــرر مالــي واقــع فعـ ً‬\n      ‫ألنــه الســبب يف التعويــض واملســبب ال يتقــدم ســببه وإال لــم يكــن ســبب ًا‬\n      ‫لــه أ‪.‬ه ـ وبعــرض هــذه االجابــة علــى املدعــي وكالــة قــال إن البائــع قــد‬\n      ‫بلــغ الشــركة ببيعــه للعقــار وأن عليهــم االخــاء خــال مــدة اقصاهــا‬\n      ‫نهايــة االيجــار املدفــوع يف ‪1433/6/30‬ه ـ وذلــك بتاريــخ ‪1433/2/24‬هـ‬\n      ‫كمــا أن الشــركة املدعــى عليهــا اســتعدت وأرســلت ملوكلتــي خطابــا‬\n      ‫بتاريــخ ‪1433/11/9‬ه ـ يلتــزم فيــه باإلخــاء خــال خمســة عشــر يومــا‬\n      ‫مــن تاريــخ اخلطــاب وهــذا ملــزم للشــركة باإلخــاء هكــذا قــرر فطلبــت‬\n      ‫مــن املدعــي وكالــة هــذا اخلطــاب فأبــرز ورقــة مــن مطبوعــات شــركة‬\n      ‫‪.......‬بيــت ‪ ...‬مؤرخــة يف ‪1433/11/9‬ه ـ وهــذا نصهــا الســيد ‪.......‬احملترم‬\n      ‫الســام عليكــم ورحمــة اهلل وبركاتــه اشــارة الــى احملادثــة الهاتفيــة‬\n      ‫مــع املهنــدس ‪.......‬معــرض ‪ ...‬الواقــع يف حــي ‪.......‬طريــق الطائــف مبكــة‬\n      ‫املكرمــة بخصــوص االخــاء نفيدكــم بأنــه خــال ‪ 15‬يــوم مــن تاريــخ‬\n      ‫خطابنــا هــذا ســوف نقــوم بإخــاء املوقــع نهائيــا وتســليمه اليكــم مــع‬\n      ‫اعتذارنــا الشــديد ونقــدر لكــم تعاونكــم خــال الفتــرة املاضيــة ونأمــل‬\n\n\n‫‪219‬‬\n\f‫أن نقــدم لكــم خدماتنــا كشــركة معروفــة ونكــرر اعتذارنــا ولكــم‬\n‫الشــكر والتقديــر أه ـ وبعــرض هــذه الورقــة علــى املدعــى عليــه وكالــة‬\n‫فقــال أطلــب إمهالــي لالطــاع علــى هــذه الورقــة ولــذا رفعــت اجللســة ثــم‬\n‫يف جلســة أخــرى‪ ،‬حضــر الطرفــان وكالــة وبســؤال املدعــى عليــه‬\n‫وكالــة عمــا اســتمهل ألجلــه يف اجللســة املاضيــة فأبــرز ورقــة هــذا‬\n‫نصهــا‪ -:‬لقــد قــدم املدعــي يف اجللســة املاضيــة وهــو بصــدد الــرد علــى‬\n‫مذكــرة دفاعنــا صــورة خطــاب مــؤرخ يف ‪1433/11/09‬ه ـ بتوقيــع بيــت‬\n‫‪ ...‬موجــه لــأخ ‪.......‬انتهــى فيــه محــرره بعــد اإلشــارة إلــى املكاملــة‬\n‫الهاتفيــة مــع املهنــدس ‪.......‬إلــى اإلفــادة بأنــه ســيخلي املعــرض خــال (‪15‬‬\n‫يومــا) مــن تاريخــه ‪ ،‬وال يفيــد املدعــي االســتناد إلــى هــذا اخلطــاب لتبريــر‬\n‫تصرفــه مــن تأجيــر املوقــع خــال مــدة احلــج مببلــغ (‪ )200.000‬ريــال وال‬\n‫يف عــدم هدمــه وبنــاء فنــدق وتأجيــره خــال فتــرة احلــج ليــس فقــط‬\n‫لتناقضــه وافتقــاره إلــى الدليــل الــذي يؤيــده وإمنــا كذلــك ألن محــرر‬\n‫اخلطــاب لــم يكــن هــو مســتأجر املعــرض وال مــأذون لــه فيــه ‪ ،‬وحتــى‬\n‫علــى فــرض ذلــك فإنــه ال يعــدو عــن كونــه مجــرد وعــد ال يلــزم الوفــاء بــه‬\n‫وال يكــون فرضــا مــن إجنــاز الوعــد والعهــد إال علــى مــن وعــد بواجــب‬\n‫عليــه ـ وال ريــب يف أن اإلخــاء ليــس بواجــب علــى مــن وعــد ‪ ،‬ومــن ثــم‬\n‫فإنــه ال جــدال يف انتفــاء اخلطــأ كذلــك لهــذا الســبب وبالبنــاء علــى مــا‬\n‫تقدم وما ســبق أن قدمناه يف مذكرتنا الســابقة نلتمس من فضيلتكم‬\n‫عــدم ســماع دعــوى املدعــي ـ وأنــه كل مــا لــه هــو نصف القيمــة اإليجارية‬\n‫التــي امتنــع عــن اســتالمها ا‪.‬ه ـ ‪ ،‬فســألت املدعــى عليــه وكالــة هــل‬\n‫اســتأجر موكلــه العقــار لكامــل عــام ‪1433‬ه ـ مبوجــب عقــد محــرر‬\n‫فقــال أن الشــركة موكلتــي اســتأجرت العقــار لكامــل عــام‬\n\n\n                                                                                       ‫‪220‬‬\n\f      ‫‪1432‬ه ــبعقد محــرر وأمــا عــام ‪1433‬ه ـ فــا يوجــد عقــد محــرر ولكــن‬\n      ‫مالــك العقــار اســتلم الدفعــة األولــى مــن األجــرة مبوجــب ســند قبــض‬\n      ‫وهــذا يعــد جتديــد ًا للعقــد لعــام ‪1433‬ه ـ هكــذا قــرر فطلبــت مــن‬\n      ‫املدعــى عليــه وكالــة ســند قبــض الدفعــة األولــى مــن األجــرة لعــام‬\n      ‫‪1433‬ه ـ فأبــرز ســند قبــض مــن مطبوعــات ورثــة ‪.......‬برقــم ‪ 356‬مــؤرخ‬\n      ‫يف ‪1432/12/6‬ه ـ باســتالم مبلــغ مائتــن وخمســة وعشــرين ألــف ريــال‬\n      ‫ببيــت ‪ ...‬مبوجــب شــيك علــى البنــك ‪.......‬التجــاري وذلــك مقابــل أيجــار‬\n      ‫بيــت ‪ ...‬مــن الفتــرة مــن ‪1433/1/1‬ه ـ حتــى ‪1433/6/30‬ه ـ ثــم توقيــع‬\n      ‫ا‪.‬هــ‪ ،‬فســألت املدعــى عليــه وكالــة هــل يوجــد ســند أخــر أو عقــد ملــا‬\n      ‫بعــد ‪1433/6/30‬ه ـ فقــال ال ولكننــا حررنــا شــيكات للمدعــي أصالة‬\n      ‫بصفتــه املشــتري اجلديــد للعقــار فرفــض اســتالمها هكــذا قــرر وبعرض‬\n      ‫ذلــك علــى املدعــي وكالــة قــال إن البائــع لــم يجــدد العقــد لكامــل عــام‬\n      ‫‪1433‬ه ـ وإمنــا جــدده للمــدة مــن ‪1433/1/1‬ه ـ حتــى ‪1433/6/30‬ه ـ‬\n      ‫حســب ســند القبــض كمــا أن عقــد التأجيــر االساســي لــم يذكــر فيــه‬\n      ‫العقــد يتجــدد تلقائيــا كمــا ان العقــد نــص علــى أنــه يف حــال بيــع العــن‬\n      ‫املؤجــرة فــإن علــى املســتأجر االتفــاق مــع املالــك اجلديــد كمــا أن املالــك‬\n      ‫الســابق للعقــار بعــث ورقــة للمدعــى عليــه أصالــة بتاريــخ ‪1433/2/24‬ه ـ‬\n      ‫وأبلغــه فيهــا أنــه بــاع العقــار وأن علــى الشــركة أخــاء العقــار يف مــدة‬\n      ‫أقصاهــا نهايــة االيجــار املدفــوع ‪1433/6/30‬هـ وقد اســتلمت الشــركة‬\n      ‫هــذا اخلطــاب كل هــذا يــدل علــى أنــه ليــس مــن حــق الشــركة البقــاء‬\n      ‫بعــد ‪1433/6/30‬ه ـ هكــذا قــرر فطلبــت مــن املدعــى عليــه وكالــة‬\n      ‫العقــد مــع املالــك الســابق كمــا طلبــت مــن املدعــي وكالــة الورقــة التــي‬\n      ‫بعثهــا املالــك الســابق للمدعــى عليــه فابــرز املدعــى عليــه وكالــة عقــد‬\n\n\n‫‪221‬‬\n\f‫االجــارة بــن موكلــه واملالــك الســابق وهــذا نصــه (عقــد إيحــار بعــون‬\n‫اهلل وتوفيقــه أنــه يف يــوم الثالثــاء املوافــق ‪1432/01/01‬ه ـ مبدينةمكة‬\n‫املكرمــة مت االتفــاق بــن كل مــن‪ :‬االســم ‪ :‬ورثــة ‪.......‬وميثلــه يف هــذا‬\n‫العقــد األســتاذ ‪ .......‬اجلنســية ‪...........‬ســعودي مبوجــب ‪ :‬بطاقــة أحــوال‬\n‫‪ .......‬ويشــار إليــه فيمــا بعــد بالطــرف األول والســادة ‪ :‬مجموعــة ‪.......‬‬\n‫لصاحبهــا ‪.......‬وشــركاه مبوجــب ســجل جتــاري ‪.......‬وميثلــه يف هــذا‬\n‫العقــد ‪....... :‬اجلنســية ‪ :‬ميانــي مبوجــب‪ :‬أقامــه رقــم ‪.......‬ويشــار إليــه فيمــا‬\n‫بعــد بالطــرف الثانــي اتفقــا وهمــا وبحالتهمــا املعتبــرة شــرع ًا علــى أن‬\n‫يؤجــر الطــرف األول للطــرف الثانــي معــرض بيــع (‪ )...‬الكائــن ‪...‬‬\n‫اجلنوبيــة وذلــك بقصــد اســتخدامها ل ـ بيع أجهزة مكتبية وأثاث وحســب‬\n‫مــا نــص بالســجل التجــاري ـ ـ ـ وفقــا للمــواد التاليــة املــادة األولــى‪ :‬مــدة‬\n‫هــذا العقــد هــي ســنة هجريــة تبــدأ مــن ‪1432/01/01‬ه ـ وتنتهــي بنهايــة‬\n‫‪1432/12/30‬ه ـ املــادة الثانيــة‪ -1 :‬يلتــزم الطــرف الثانــي بدفــع مبلــغ‬\n‫ســنوي وقــدره ‪ 450000‬ريــال فقــط أربعمائــة وخمســون ألــف ريــال ال‬\n‫غيــر أجــرة للعــن تســدد دفعتــن بدايــة كل ســتة أشــهر مــن العــام‬\n‫الهجــري دون تأخيــر وحالــة تأخــره عــن الســداد مــدة ثالثــن يوم ـ ًا فــأن‬\n‫للطــرف األول احلــق يف املطالبــة بفســخ العقــد ‪ -2‬يف حالــة تــرك الطــرف‬\n‫الثانــي للعــن قبــل نهايــة العقــد يلتــزم بســداد باقــي أجــرة مــدة العقــد (مــا‬\n‫لــم تتــم تســوية هــذا املوضــوع ودي ـ ًا بينهمــا) املــادة الثالثــة‪ :‬يقــر الطــرف‬\n‫الثانــي باســتالمه العــن املؤجــرة و أنــه عايــن املــكان املســتأجر بنفســه‬\n‫أو بواســطة وكيلــة ووجــده ســليم ًا وصاحل ـ ًا لالســتعمال للغــرض الــذي‬\n‫اســتأجره مــن أجلــه ويقــع عليه وحده مســؤولية احلصول علــى التراخيص‬\n‫الرســمية الالزمــة املرتبطــة بذلــك االســتعمال ‪ .‬املــادة الرابعــة ‪ -1 :‬يقــر‬\n\n\n                                                                                           ‫‪222‬‬\n\f      ‫الطــرف الثانــي باحملافظــة علــى كامــل العــن املســتأجرة أو أحــد‬\n      ‫مرافقهــا ســواء وقــع منــه أو مــن أحــد التابعــن لــه وعليــه تســليم العــن يف‬\n      ‫نهايــة العقــد خاليــة مــن األضــرار الناجمــة عــن االســتعمال غيــر العــادي‪.‬‬\n      ‫‪ -2‬يلتــزم الطــرف الثانــي بعــدم إحــداث أي إضافــات أو تعديــات ثابتــة‬\n      ‫يف العــن املســتأجرة إال بعــد احلصــول علــى موافقــة خطيــة مــن املالــك‬\n      ‫حتــدد بشــكل واضــح ووضــع أولويــة هــذه االضافــات أو التعديــات‬\n      ‫والتزامــات الطرفــن عنــد نهايــة العقــد وذلــك طبق ـ ًا لألصــول الفنيــة‪.‬‬\n      ‫‪ -3‬يلتــزم الثانــي بعــدم تأجيــر العــن املســتأجرة أو جــزء منهــا مــن الباطن‬\n      ‫أو التنــازل عنهــا إال بعــد احلصــول علــى موافقــة خطيــة مــن الطــرف األول‬\n      ‫ويف حالــة مخالفــة الطــرف الثانــي لذلــك يحــق للطــرف األول املطالبــة‬\n      ‫بفســخ العقــد بعــد توجيــه انــذار خطــي للطــرف الثانــي ملــدة شــهر‬\n      ‫وللطــرف األول حــق املطالبــة بالتعويــض عــن األضــرار الناجمــة عــن‬\n      ‫ذلــك‪ .‬املــادة اخلامســة ‪ -1 :‬يلتــزم الطــرف الثانــي مبراعــاة تعاليــم الديــن‬\n      ‫اإلســامي احلنيــف وبعــدم إبــراء املطلوبــن للعدالــة أو املخالفــن للنظــام‬\n      ‫أو احتــواء أي ممنوعــات ويتحمــل املســؤولية املطلقــة جتــاه ذلــك‪-2.‬‬\n      ‫يحظــر علــى الطــرف الثانــي أن يضــع أو يخــزن يف املــكان املســتأجر‬\n      ‫مــواد خطــرة أو مضــرة بالصحــة العامــة أو بالعــن املســتأجرة إال إذا‬\n      ‫اســتأجر املــكان لغــرض صناعــي فيكــون املســتأجر مســئو ًال عــن‬\n      ‫احملافظــة علــى ســامة العــن املســتأجرة وحتمل مســؤولياتها مع مراعاة‬\n      ‫كل طــرف ملــا يجــب عليــه حــول أنظمــة وتعليمــات وإرشــادات الدفــاع‬\n      ‫املدنــي املــادة السادســة ‪ -1 :‬يف حالــة وفــاة أحــد طــريف العقــد ال يترتــب‬\n      ‫علــى ذلــك فســخ العقــد إال يف حالــة اصطــاح األطــراف علــى إنهائــه أو‬\n      ‫كــون الطــرف الثانــي ليــس لــه وارث يف اســتيفاء املنفعــة وتســتويف‬\n\n\n‫‪223‬‬\n\f‫األجــرة عــن املــدة الســابقة‪ -2 .‬يف حالــة حــدوث كارثــة مــن احلــاالت‬\n‫املعتبــرة شــرع ًا وبقــوة قاهــرة بحيــث ال ميكــن للطــرف الثانــي اســتيفاء‬\n‫املنافــع املعقــود عليهــا بفســخ العقــد وبانفســاخه يســتحق الطــرف األول‬\n‫أجــرة املــدة الســابقة لذلــك‪ -3 .‬يف حالــة بيــع العــن املؤجــرة أو بيــع العقــار‬\n‫الــذي مــن ضمنــه العــن املؤجــرة يعتبــر العقــد مســتمرا ونافــذا إلــى نهايــة‬\n‫املــدة املتفــق عليهــا مبوجــب هــذا العقــد ويتــم االتفــاق بــن الطــرف الثانــي‬\n‫واملالــك اجلديــد‪ .‬املــادة الســابعة ‪ :‬يقــر الطــرف الثانــي بتفويضــه للطــرف‬\n‫األول أو مــن ينــوب عنــه تفويضــا الزمــا غيــر قابــل للرجــوع بفتــح العــن‬\n‫املؤجــرة [أي طريقــة يراهــا مناســبة بعــد انقضــاء شــهر مــن انتهــاء مــدة‬\n‫العقــد وعــدم دفــع القيمــة اإليجاريــة يف املوعــد احملــدد لهــا ويف حالــة‬\n‫تغيب املستأجر أو سفر أو أي سبب آخر فللطرف األول احلق بالتصرف‬\n‫يف املنقــوالت واســتالمها (( ســواء كانــت عينيــة أو نقديــة )) وتأجيــر‬\n‫العــن للغيــر وال يحــق للطــرف الثانــي املطالبــة بــأي تعويض ‪.‬املــادة الثامنة‬\n‫‪ :‬يف حالــة حــدوث خــاف نتيجــة لتنفيــذ هــذا العقــد أو تفســير أحــد‬\n‫بنــوده فــإن احملكمــة املختصــة هــي جهــة البــت يف اخلــاف ملحوظــة‪:‬‬\n‫يلتــزم الطــرف الثانــي حســب االتفــاق بعمــل شــبكة انــذار حريــق حســب‬\n‫طلــب الدفــاع املدنــي وعلــى حســابه حــرر هــذا العقــد مــن نســختان أصلية‬\n‫بيــد كل طــرف نســخة للعمــل مبوجبهــا وأذنــا ملــن يشــهد واهلل خيــر‬\n‫الشــاهدين‪ ) .‬وبعــرض هــذا العقــد علــى املدعــي وكالــة قــال هذا العقد‬\n‫صحيــح وهــو بــن املدعــى عليــه وكالــة واملالــك الســابق وهــو خــاص‬\n‫بعــام وال يتجــدد تلقائيــا هكــذا قــرر ثــم ابــرز املدعــى عليــه أصالــة‬\n‫خطاب ـ ًا مــن املالــك الســابق موجه ـ ًا الــى املدعــى عليــه أصالــة مــؤرخ‬\n‫يف‪1433/2/24‬هـ وهذا نصه ( الســادة شــركة مجموعة ‪.......‬الســام‬\n\n\n                                                                                         ‫‪224‬‬\n\f      ‫عليكــم ورحمــة اهلل وبركاتــه نفيدكــم علمــا بأننــا قــد قمنــا ببيــع‬\n      ‫العقــار املؤجــر لكــم ‪ ...‬وعليــه نرجــوا منكــم اخــاء العقــار يف مــدة‬\n      ‫اقصاهــا نهايــة االيجــار املدفــوع ‪1433/6/30‬ه ـ وذلــك لتســليمه للمالــك‬\n      ‫اجلديــد ورثــة ‪ ).......‬وبعــرض هــذا اخلطــاب علــى املدعــى عليــه وكالــة‬\n      ‫قــال هــذا اخلطــاب اســتلمه موكلــي ولكــن ليــس مــن حــق املالــك‬\n      ‫الســابق مخاطبتنــا بعــد بيعــه العقــار الن عالقتنــا اصبحــت مــع املالــك‬\n      ‫اجلديــد وقــد ارســل لنــا املالــك اجلديــد خطاب ـ ًا يف شــهر شــعبان يطلــب‬\n      ‫االخــاء خــال خمســة أيــام مــن تاريــخ خطابــه هكــذا قــرر فســألت‬\n      ‫املدعــى عليــه وكالــة هــل مت االتفــاق مــع املالــك اجلديــد علــى اجــرة املــدة‬\n      ‫التــي بعــد ‪1431/6/30‬ه ـ فقــال ال لــم نتفــق معــه ولكــن كان هنــاك‬\n      ‫شــكوى يف شــرطة العزيزيــة يف شــهر رمضــان ثــم ابلغنــا املالــك اجلديــد‬\n      ‫اننــا ســنخلي يف شــهر ذي احلجــة هكــذا قــرر وعليــه فقــد جــرى بعــث‬\n      ‫املعاملــة لهيئــة النظــر لتقديــر أجــرة العقــار للمــدة مــن ‪1433/7/1‬ه ـ‬\n      ‫حتــى ‪1433/12/3‬ه ـ واالســعار الســائدة يف ذلــك الوقــت وذلك بخطابي‬\n      ‫رقــم ‪ 34/821159‬يف ‪1434/5/25‬ه ـ فــوردت اإلجابــة مــن هيئــة النظــر‬\n      ‫برقــم ‪ 34/821159‬يف ‪1434/7/1‬ه ـ وهــذا نصــه احملضــر ‪ -:‬احلمــد هلل‬\n      ‫وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ..‬وبعــد بنــاء علــى املعاملة‬\n      ‫الــواردة مــن فضيلــة الشــيخ الدكتــور ‪.......‬برقــم ‪ 34821159‬وتاريــخ‬\n      ‫‪1434/5/25‬ه ـ واملتعلقــة بدعــوى ‪.......‬ضــد ‪ .......‬بخصــوص أجــرة عقار‬\n      ‫والــذي طلــب فيهــا فضيلتــه تقديــر أجــرة املــدة مــن تاريــخ ‪1433/7/1‬ه ـ‬\n      ‫حتــى تاريــخ اإلخــاء ‪1433/12/3‬ه ـ حســب األســعار الســائدة يف ذلــك‬\n      ‫الوقــت ‪ ،‬وعليــه فقــد جــرى االجتمــاع بطــريف الدعــوى والــذي نــراه يف‬\n      ‫تقديــر أجــرة املــدة مــن تاريــخ ‪1433/7/1‬ه ـ حتــى تاريــخ اإلخــاء‬\n\n\n‫‪225‬‬\n\f‫‪1433/12/3‬ه ـ حســب األســعار الســائدة هــو مبلــغ أربعمائــة وثمانــون‬\n‫ألــف ريــال (‪ )480.000‬ألــف ريــال مقابــل الفتــرة املذكــورة أعــاه ‪ .‬هــذا‬\n‫مــا جــرى تقديــره والســام عضــو هيئــة النظــر توقيــع ‪.......‬توقيــع عضــو‬\n‫هيئــة النظــر ‪.......‬ا‪.‬ه ـ ‪ ،‬وبعــرض هــذا القــرار علــى الطرفــن قــال املدعــي‬\n‫وكالــة إن موكلــي يقــدر األجــرة بأربعمائــة وخمســن ألــف ريــال فقــط‬\n‫ويطالــب بهــذا املبلــغ مقابــل األجــرة ويطالــب أيضــا باإلضــرار الناجتــة‬\n‫عــن تأخــر املدعــى عليــه يف أخــاء املبنــى ممــا فــوت علــى موكلــي هــدم‬\n‫املوقــع وإعــادة بنائــه والتأجيــر ملوســم احلــج لعــام ‪1434‬ه ـ وموكلــي يقدر‬\n‫هــذا الضــرر مبليــون وخمســمائة وخمســن ألــف ريــال ولــذا فــإن اجمالــي‬\n‫مــا يطالــب بــه موكلــي هــو مليونــا ريــال هكــذا قــرر وبعــرض قــرار‬\n‫هيئــة النظــر ومــا قــرره املدعــي وكالــة علــى املدعــى عليــه وكالــة قــال‬\n‫أطلــب إمهالــي ملراجعــة موكلــي ولــذا رفعــت اجللســة ثــم يف جلســة أخــرى‬\n‫‪ ،‬حضــر الطرفــان وكالــة وبســؤال املدعــى عليــه وكالــة عمــا اســتمهل‬\n‫ألجلــه وأبــرز ورقــة هــذا نصهــا أتقــدم لفضيلتكــم مبذكــرة الــرد علــى‬\n‫تقديــر هيئــة النظــر الصــادر يف القضيــة املنظــورة أمــام فضيلتكــم برقــم‬\n‫(‪ )34/821159‬وتاريــخ ‪1434/4/3‬ه ـ وبــكل احتــرام ؟ فإننــي ال أتفــق‬\n‫مــع هيئــة النظــر فيمــا انتهــى إليــه مــن تقديــر قيمــة أجــرة املثــل مببلــغ‬\n‫(‪ )480000‬ريــال للســتة شــهور الالحقــة مباشــرة علــى األجــرة املدفوعــة‬\n‫للســتة شــهور الســابقة عليهــا والبالغــة (‪ )225000‬ريــال ‪ ،‬فليــس مــن‬\n‫املعقــول أن تزيــد األجــرة خــال الســتة شــهور أكثــر مــن (‪ )%100‬وأن‬\n‫صــح ذلــك يف العمائــر التجاريــة واملــوالت لألجــرة التــي مت االتفــاق عليهــا‬\n‫منــذ ســنوات ‪ ،‬فــا يصبــح يف الهناجــر (الشــنكو) ‪ ،‬ومــن مت فإننــا‬\n‫نعتــرض علــى تقديــر هيئــة النظــر ‪ ،‬ونلتمــس مــن فضيلتكــم طلــب‬\n\n\n                                                                                       ‫‪226‬‬\n\f      ‫إعــادة النظــر فيــه علــى ضــوء املــكان والزمــان مــا بــن األجــرة وأجــرة‬\n      ‫املثــل وامتــداد مــدة العقــد لنفــس مدتــه ‪.‬ا‪.‬ه ـ ‪ ،‬وبســؤال املدعــي عــن‬\n      ‫تاريــخ اصــدار رخصــة املبنــى وعــدد أدوار العمــارة فقــال انهــا صــدرت‬\n      ‫بتاريــخ ‪1434/3/25‬ه ـ ولكــن قبــل ذلــك بدأنــا باحلفــر وإزالــة املنشــآت‬\n      ‫الســابقة والعمــارة مكونــة مــن بــدروم وأرض وميزايــن ومطعــم ومصلــى‬\n      ‫ومطعــم وخدمــات وخمســة عشــر دورا متكــررا ا‪.‬ه ـ فطلبــت منه رخصة‬\n      ‫البنــاء فأبــرز رخصــة صــادرة مــن إدارة الرخــص بأمانــة العاصمــة‬\n      ‫املقدســة برقــم ‪ 3401500961‬يف ‪1434/3/25‬ه ـ ‪،‬وباالطــاع عليــه‬\n      ‫وجدتهــا تتضمــن التصريــح للمدعــي أصالــة بنــاء عمــارة مكونــه مــن‬\n      ‫بــدروم ودور أرضــي وميزانــن ومصلــى ومطعــم وخدمــات وخمســة عشــر‬\n      ‫دورا متكــررا ا‪.‬ه ـ ‪،‬وبســؤال الطرفــن هــل لديهمــا مــا يضيفانــه فقــال‬\n      ‫ليــس لدينــا ســوى مــا قدمنــاه ســلفا ‪ ،‬فبنــاء علــى مــا تقــدم مــن الدعــوى‬\n      ‫واإلجابــة وبعــد االطــاع علــى قــرار هيئــة النظــر وعلــى صــك امللكيــة‬\n      ‫وعلــى عقــد اإلجــارة بــن املدعــى عليــه أصالــة والبائــع وألن هــذا العقــد‬\n      ‫نــص علــى أن مــدة العقــد ســنه واحــدة وهــي لعــام ‪1432‬ه ـ فقــط دون‬\n      ‫االشــارة إلــى جتــدده تلقائيــا وبعــد االطــاع علــى املراســات بــن البائــع‬\n      ‫واملدعــى عليــه واملتضمــن إبــاغ البائــع للمدعــى عليــه بالبيــع وإمهالــه‬\n      ‫للخــروج حتــى ‪1433/6/30‬ه ـ كمــا تضمــن أيضــا الســند املوقــع مــن‬\n      ‫البائــع باســتالم األجــرة أن هــذه األجــرة للمــدة مــن ‪1432/1/1‬ه ـ حتــى‬\n      ‫‪1433/6/30‬ه ـ فقــط وكذلــك مطالبة املشــتري للمدعــى عليه باخلروج‬\n      ‫بعــد انتهــاء املــدة وألن املدعــي أصالــة قــدر أجــرة املــدة مــن ‪1433/7/1‬هـ‬\n      ‫بأربعمائــة وخمســن ألــف ريــال وطالــب بهــذا املبلــغ وهــو أقــل ممــا قدرتــه‬\n      ‫هيئــة النظــر كمــا طالــب بتعويضــه عــن التأخيــر يف هــدم املوقــع وبنــاء‬\n\n\n‫‪227‬‬\n\f‫عمــارة عليــه وتأجيــر ملوســم احلــج لهــذا العــام ‪1434‬ه ـ لذلــك كلــه وألن‬\n‫مطالبــة املدعــي بأجــرة مــدة بقــاء املدعــى عليــه مــن ‪1433/7/1‬ه ـ حتــى‬\n‫تاريــخ اإلخــاء وقدرهــا بأربعمائــة وخمســن ألــف ريــال وألن مــا قررتــه‬\n‫هيئــة النظــر هــو أكثــر مــن هــذا املبلــغ وقــد قــرر املدعــي وكالــة أن‬\n‫موكلــه يطالــب باألجــرة التــي يدعيهــا وال يطالــب مبــا قــدرت بــه هيئــة‬\n‫النظــر وألن مطالبــة املدعــي باألجــرة لهــذه املــدة هــو إقــرار منــه ببقــاء‬\n‫املدعــى عليــه يف املوقــع فــا ميكنــه اجلمــع يف املطالبــة بــن األجــرة وضرر‬\n‫التأخــر يف اإلخــاء كمــا إن هــذه اإلضــرار التــي يدعيهــا وهــي عــدم‬\n‫متكنــه مــن بنــاء العمــارة وتأجيرهــا ملوســم حــج هــذا العــام ‪1434‬ه ــي‬\n‫دعــوى بضــرر عــن فــوات تأجيــر مبنــى غيــر موجــود ولــم يبــدأ بنائــه اال‬\n‫بعــد اصــدار تصريــح البنــاء يف ‪1434/3/25‬ه ـ وألن انتهــاء املبنــى قبــل‬\n‫موســم احلــج وتأجيــره هــذا املوســم أمــر لــم يحصــل وهــو ضــرر متوقــع‬\n‫فقــد ينتهــي مــن البنــاء قبــل املوســم ويؤجــره وقــد ال يتمكــن مــن ذلــك‬\n‫ألســباب أخــرى وألن الضــرر املضمــون هــو الضــرر الواقــع أمــا الربــح‬\n‫الفائــت والضــرر غيــر املتوقــع فهــو غيــر مضمــون كمــا قــرر ذلــك أهــل‬\n‫العلــم قــال البهوتــي يف شــرح املنتهــى ‪ 122/4‬وال يضمــن ربــح فــأت علــى‬\n‫مالــك بحبــس غاصــب مــال جتــارة مــدة ميكــن أن يتجــر فيهــا إذا لــم‬\n‫يتجــر فيــه الغاصــب « وينظــر شــرح املنتهــى البــن النجــار ‪ 215/5‬لذلــك‬\n‫كلــه فقــد حكمــت علــى املدعــى عليــه اصالــه بــأن يدفــع للمدعــى‬\n‫أجــرة املــدة مــن ‪1433/7/1‬ه ـ حتــى تاريــخ اإلخــاء مبلغ وقــدره أربعمائة‬\n‫وخمســون ألــف ريــال وعــدم اســتحقاق املدعــي للتعويــض الــذي يطالــب‬\n‫بــه وبعــرض احلكــم علــى الطرفــن قــررا عــدم القناعــة وطلبــا رفعــه‬\n‫حملكمــة االســتئناف بعــد تقــدمي الئحــة اعتراضيــة عليــه فأفهمتهمــا‬\n\n\n                                                                                     ‫‪228‬‬\n\f      ‫مبراجعــة احملكمــة خــال عشــرة أيــام الســتالم صــورة الصــك وتقــدمي‬\n      ‫الالئحــة االعتراضيــة خــال ثالثــن يومــا مــدة االعتــراض فــإذا تأخــرا‬\n      ‫عــن تقــدمي الالئحــة االعتراضيــة ســقط حقهمــا يف طلــب االســتئناف‬\n      ‫واكتســب احلكــم القطعيــة ‪ ،‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n                          ‫محمد وعلى آله وصحبه وسلم ‪ .‬حرر يف ‪1434/8/16‬هـ‬\n      ‫احلمد هلل ‪ ،‬والصالة والسالم على رسول اهلل ‪ ،‬وبعد ‪ :‬ـ فقـد جـرى م ّنا‬\n      ‫نح ــن رئيس وأعضاء الدائ ــرة احلقوقي ــة الثالثة يف محكم ــة االستئناف‬\n      ‫مبنطقة مك ــة املكرم ــة االطال ُع عل ــى هـذا الصك الصـادر من فضيـلة‬\n      ‫الشي ــخ ‪.......‬القاضــي باحملكمــة العامــة مبكــة املكرمــة واملســجل‬\n      ‫بعــدد ‪ 34300352‬وتــاري ــخ ‪1434/8 /17‬ه ـ املتضمــن دعــوى ‪.......‬ضــد‬\n      ‫شــركة ‪.......‬وشــركاه يف مبلــغ مالــي احملكــوم فيــه مبــا دون باطنــه‬\n      ‫وبــدراس ــة احلك ــم وص ــورة ضبط ــه والئحتــه االعتراضيــة تقـ ـ ـ ـ ــررت‬\n      ‫املـ ــوافقـ ـ ـ ــة علــى احلكــم وبــاهلل تعالــى التوفيــق وصل ــى اهلل عل ــى نبي ــنا‬\n                                                 ‫محم ــد وعل ــى آل ــه وصحب ــه وسـلم ‪،‬‬\n\n\n\n\n‫‪229‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"612f1ba9-3f27-52bc-993f-69d3ecdc8564","source_page_start":214,"source_page_end":229,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"641972f524692bf43caeb9dd80cfc8687ea97f9850c87b6f0f6fe5deb9b6adb6","normalized_text_hash":"5d0f9867b0eb204bde20edfc4c9cbf1f323027924b2927ffcb18c36f9d408869","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v7-p214-34300352"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS document_files
